window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["民政部"] = {"zhongguobianminyupilinguobianminhunyindengjibanfa":[{"i":1,"n":"第一条","txt":"为规范边民婚姻登记工作，保护婚姻当事人的合法婚姻权益，根据《中华人民共和国婚姻法》、《婚姻登记条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称边民是指中国与毗邻国边界线两侧县级行政区域内有当地常住户口的中国公民和外国人。中国与毗邻国就双方国家边境地区和边民的范围达成有关协议的，适用协议的规定。"},{"i":3,"n":"第三条","txt":"本办法适用于中国边民与毗邻国边民在中国边境地区办理婚姻登记。"},{"i":4,"n":"第四条","txt":"边民办理婚姻登记的机关是边境地区县级人民政府民政部门。 边境地区婚姻登记机关应当按照便民原则在交通不便的乡（镇）巡回登记。"},{"i":5,"n":"第五条","txt":"中国边民与毗邻国边民在中国边境地区结婚，男女双方应当共同到中国一方当事人常住户口所在地的婚姻登记机关办理结婚登记。"},{"i":6,"n":"第六条","txt":"办理结婚登记的中国边民应当出具下列证件、证明材料： （一）本人的居民户口簿、居民身份证; （二）本人无配偶以及与对方当事人没有直系血亲和三代以内旁系血亲关系的签字声明。 办理结婚登记的毗邻国边民应当出具下列证明材料： （一）能够证明本人边民身份的有效护照、国际旅行证件或者边境地区出入境通行证件； 所在国公证机构或者有权机关出具的、经中华人民共和国驻该国使（领）馆认证或者该国驻华使（领）馆认证的本人无配偶的证明，或者所在国驻华使（领）馆出具的本人无配偶的证明，或者由毗邻国边境地区与中国乡（镇）人民政府同级的政府出具的本人无配偶证明。"},{"i":7,"n":"第七条","txt":"办理结婚登记的当事人有下列情形之一的，婚姻登记机关不予登记： （一）未到中国法定结婚年龄的； （二）非双方自愿的； （三）一方或者双方已有配偶的； （四）属于直系血亲或者三代以内旁系血亲的； （五）患有医学上认为不应当结婚的疾病的。"},{"i":8,"n":"第八条","txt":"婚姻登记机关应当对结婚登记当事人出具的证件、证明材料进行审查并询问相关情况，对当事人符合结婚条件的，应当当场予以登记，发给结婚证。对当事人不符合结婚条件不予登记的，应当向当事人说明理由。"},{"i":9,"n":"第九条","txt":"男女双方补办结婚登记的，适用本办法关于结婚登记的规定。"},{"i":10,"n":"第十条","txt":"未到婚姻登记机关办理结婚登记以夫妻名义同居生活的，不成立夫妻关系。"},{"i":11,"n":"第十一条","txt":"因受胁迫结婚的，受胁迫的边民可以依据《中华人民共和国婚姻法》第十一条的规定向婚姻登记机关请求撤销其婚姻。受胁迫方应当出具下列证件、证明材料： （一）本人的身份证件； （二）结婚证； （三）要求撤销婚姻的书面申请； （四）公安机关出具或者人民法院作出的能够证明当事人被胁迫结婚的证明材料。 受胁迫方为毗邻国边民的，其身份证件包括能够证明边民身份的有效护照、国际旅行证件或者边境地区出入境通行证件。 婚姻登记机关经审查认为受胁迫结婚的情况属实且不涉及子女抚养、财产及债务问题的，应当撤销该婚姻，宣告结婚证作废。"},{"i":12,"n":"第十二条","txt":"中国边民与毗邻国边民在中国边境地区自愿离婚的，应当共同到中国边民常住户口所在地的婚姻登记机关办理离婚登记。"},{"i":13,"n":"第十三条","txt":"办理离婚登记的双方当事人应当出具下列证件、证明材料： （一） 本人的结婚证； （二） 双方当事人共同签署的离婚协议书。 除上述材料外，办理离婚登记的中国边民还需要提供本人的居民户口簿和居民身份证，毗邻国边民还需要提供能够证明边民身份的有效护照、国际旅行证件或者边境地区出入境通行证件。 离婚协议书应当载明双方当事人自愿离婚的意思表示以及对子女抚养、财产及债务处理等事项协商一致的意见。"},{"i":14,"n":"第十四条","txt":"办理离婚登记的当事人有下列情形之一的，婚姻登记机关不予受理： （一）未达成离婚协议的； （二）属于无民事行为能力或者限制民事行为能力人的； （三）其结婚登记不是在中国内地办理的。"},{"i":15,"n":"第十五条","txt":"婚姻登记机关应当对离婚登记当事人出具的证件、证明材料进行审查并询问相关情况。对当事人确属自愿离婚，并已对子女抚养、财产、债务等问题达成一致处理意见的，应当当场予以登记，发给离婚证。"},{"i":16,"n":"第十六条","txt":"离婚的男女双方自愿恢复夫妻关系的，应当到婚姻登记机关办理复婚登记。复婚登记适用本办法关于结婚登记的规定。"},{"i":17,"n":"第十七条","txt":"结婚证、离婚证遗失或者损毁的，中国边民可以持居民户口簿、居民身份证，毗邻国边民可以持能够证明边民身份的有效护照、国际旅行证件或者边境地区出入境通行证向原办理婚姻登记的机关或者中国一方当事人常住户口所在地的婚姻登记机关申请补领。婚姻登记机关对当事人的婚姻登记档案进行查证，确认属实的，应当为当事人补发结婚证、离婚证。"},{"i":18,"n":"第十八条","txt":"本办法自2012年10月1日起施行。1995年颁布的《中国与毗邻国边民婚姻登记管理试行办法》（民政部令第1号）同时废止。"}],"tiyuleiminbanfeiqiyedanweidengjishenchayuguanlizanc1e785-2":[{"i":1,"n":"第一条","txt":"为适应体育类民办非企业单位发展的需要，根据国务院《国民非企业单位登记管理暂行条例》（以下简称《条例》）等有关规定，结合体育事业的实际情况，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称体育类民办非企业单位，是指由企业事业单位、社会团体、其他社会力量和公民个人利用非国有资产举办的，不以营利为目的的，以开展体育活动为主要内容的民办的中心、院、社、俱乐部、场馆等社会组织。"},{"i":3,"n":"第三条","txt":"体育行政部门是体育类民办非企业单位的业务主管单位。国务院体育行政部门负责指导全国体育类民办非企业单位的登记审查工作，并负责在民政部登记的体育类民办非企业单位的登记审查工作。 县级以上地方各级人民政府体育行政部门负责本辖区内体育类民办非企业单位的设立审查工作。"},{"i":4,"n":"第四条","txt":"体育类民办非企业单位的业务主管单位履行下列职责： （一）负责体育类民办非企业单位设立、变更、注销登记前的审查； （二）监督、指导体育类民办非企业单位遵守国家宪法、法律、法规和政策并按照其章程开展活动； （三）对体育类民办非企业单位进行业务指导； （四）负责对体育类民办非企业单位年度检查的初审； （五）组织经验交流，表彰先进； （六）会同有关机关指导体育类民办非企业单位的清算事宜； （七）协助登记管理机关和其他有关部门查处体育类民办非企业单位的违法行为； （八）其他应由业务主管单位履行的职责。"},{"i":5,"n":"第五条","txt":"申请设立体育类民办非企业单位应当具备以下条件： （一）业务和活动范围必须符合发展体育事业的相关政策、法规，并遵守国家规定的行业标准； （二）有与业务范围和业务量相当的体育专业技术人员，关键业务岗位的主要负责人应由体育专业技术人员担任； （三）有与所从事的业务范围相适应的体育场所和条件； （四）法律、法规规定的其他条件。"},{"i":6,"n":"第六条","txt":"体育类民办非企业单位可以从事以下业务： （一）体育健身的技术指导与服务； （二）体育娱乐与休闲的技术指导、组织、服务； （三）体育竞赛的表演、组织、服务； （四）体育人才的培养与技术培训； （五）其他体育活动。"},{"i":7,"n":"第七条","txt":"申请设立体育类民办非企业单位，必须向体育行政部门提交以下材料： （一）从业人员中体育专业技术人员的专业技术资格证明材料，包括学历证明、工作简历、在体育运动中获得成绩证明、体现运动技术水平的其他证明材料等。 （二）体育场所使用权证明材料和从事业务所必需的器材清单。 （三）体育行政部门要求提供的其他材料。"},{"i":8,"n":"第八条","txt":"体育行政部门自收到全部有效文件之日起40个工作日内，应作出审查同意或不同意的决定。审查同意的，向申请人出具批准文件；审查不同意的，书面通知申请人，并说明理由。"},{"i":9,"n":"第九条","txt":"体育类民办非企业单位变更登记事项，应向体育行政部门提出书面申请，载明变更事项、原因和方案等。 体育类民办非企业单位修改章程的，应提交原章程、修改说明以及修改后的新章程；变更住所的，应出具新住所的产权或使用权证明；变更法定代表人或负责人的，应出具变更后法定代表人或身份证明及相关材料；变更业务主管单位的，应提交变更业务单位申请书；变更资金的，应提交有关资产变更证明文件等材料。"},{"i":10,"n":"第十条","txt":"体育类民办非企业单位所从事的业务活动超出本办法第六条规定范围，或改变其设立宗旨的，应办理业务主管单位变更手续，体育行政部门不再承担业务主管单位的职责，并以书面形式通知该民办非企业单位和相应登记管理机关。"},{"i":11,"n":"第十一条","txt":"体育行政部门自收到全部有效文件之日起20个工作日内，应作出同意变更或不同意变更的批复。同意变更法定代表人或负责人的，对该体育类民办非企业单位进行财务审计。"},{"i":12,"n":"第十二条","txt":"体育类民办非企业单位申请注销登记的，应向体育行政部门提交以下文件： （一）注销申请书； （二）登记证书副本； （三）依法成立的清算组织出具的清算报告； （四）法律、法规规定的其他文件。"},{"i":13,"n":"第十三条","txt":"体育行政部门应自收到注销申请书及全部有效文件之日起20个工作日内出具审查意见。体育类民办非企业单位申请变更业务主管单位，但在90日内未找到新的业务主管单位的，原体育行政部门应继续履行职责，直至该民办非企业单位完成注销登记手续。"},{"i":14,"n":"第十四条","txt":"县级以上地方各级人民政府体育行政部门应将所辖范围内体育类民办非企业单位登记、注销的审查结果报上一级体育行政部门备案。"},{"i":15,"n":"第十五条","txt":"体育类民办非企业单位可以依法通过以下方式获得发展资金： （一）接受捐赠、资助； （二）接受政府、企事业单位、社会团体、其他社会组织和个人的委托项目资金； （三）为社会提供与业务相关的有偿服务所获得的报酬； （四）其他合法收入。"},{"i":16,"n":"第十六条","txt":"体育类民办非企业单位接受、使用捐赠、资助时，在实际占有、使用前向体育行政部门报告接受和使用捐赠、资助是否符合章程规定；捐赠和资助主体的基本情况；与捐赠、资助主体约定的期限、方式和合法用途；向社会公布的内容和方式等情况。"},{"i":17,"n":"第十七条","txt":"体育类民办非企业单位应参照执行体育事业单位财务制度。"},{"i":18,"n":"第十八条","txt":"体育类民办非企业单位应在每年3月31日前向体育行政部门提交上一年度的工作报告。体育行政部门自收到该工作报告之日起30个工作日内作出初审意见。 截止到3月31日成立时间未超过六个月的体育类民办非企业单位，可不参加当年的年检工作，一并参加下一年度的年检工作。"},{"i":19,"n":"第十九条","txt":"体育类民办非企业单位出现下列情形之一，情节严重的，体育行政部门有权撤销已出具的登记审查批准文件，并以书面形式通知该民办非企业单位和相应的登记管理机关。 （一）涂改、出租、出借民办非企业单位登记证书，或者出租、出借民办非企业单位印章的； （二）超出其章程规定的宗旨和业务范围进行活动的； （三）拒不接受或者不按照规定接受监督检查的； （四）不按照规定办理变更登记的； （五）设立分支机构的； （六）从事营利性的经营活动的； （七）侵占、私分、挪用民办非企业单位的资产或者所接受的捐赠、资助的； （八）违反国家有关规定收取费用、筹集资金或者接受使用捐赠、资助的。"},{"i":20,"n":"第二十条","txt":"本办法由国家体育总局和民政部负责解释。"},{"i":21,"n":"第二十一条","txt":"本办法自发布之日起施行。"}],"ertongfulijigouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强儿童福利机构管理，维护儿童的合法权益，根据《中华人民共和国民法总则》、《中华人民共和国未成年人保护法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称儿童福利机构是指民政部门设立的，主要收留抚养由民政部门担任监护人的未满18周岁儿童的机构。 儿童福利机构包括按照事业单位法人登记的儿童福利院、设有儿童部的社会福利院等。"},{"i":3,"n":"第三条","txt":"国务院民政部门负责指导、监督全国儿童福利机构管理工作。 县级以上地方人民政府民政部门负责本行政区域内儿童福利机构管理工作，依照有关法律法规和本办法的规定，对儿童福利机构进行监督和检查。"},{"i":4,"n":"第四条","txt":"儿童福利机构应当坚持儿童利益最大化，依法保障儿童的生存权、发展权、受保护权、参与权等权利，不断提高儿童生活、医疗、康复和教育水平。 儿童福利机构及其工作人员不得歧视、侮辱、虐待儿童。"},{"i":5,"n":"第五条","txt":"儿童福利机构的建设应当纳入县级以上地方人民政府国民经济和社会发展规划，建设水平应当与当地经济和社会发展相适应。"},{"i":6,"n":"第六条","txt":"儿童福利机构所需经费由县级以上地方人民政府财政部门按照规定予以保障。"},{"i":7,"n":"第七条","txt":"鼓励自然人、法人或者其他组织通过捐赠、设立公益慈善项目、提供志愿服务等方式，参与儿童福利机构相关服务。"},{"i":8,"n":"第八条","txt":"对在儿童福利机构服务和管理工作中做出突出成绩的单位和个人，依照国家有关规定给予表彰和奖励。"},{"i":9,"n":"第九条","txt":"儿童福利机构应当收留抚养下列儿童： （一）无法查明父母或者其他监护人的儿童； （二）父母死亡或者宣告失踪且没有其他依法具有监护资格的人的儿童； （三）父母没有监护能力且没有其他依法具有监护资格的人的儿童； （四）人民法院指定由民政部门担任监护人的儿童； （五）法律规定应当由民政部门担任监护人的其他儿童。"},{"i":10,"n":"第十条","txt":"儿童福利机构收留抚养本办法第九条第（一）项规定的儿童的，应当区分情况登记保存以下材料： （一）属于无法查明父母或者其他监护人的被遗弃儿童的，登记保存公安机关出具的经相关程序确认查找不到父母或者其他监护人的捡拾报案证明、儿童福利机构发布的寻亲公告、民政部门接收意见等材料。 （二）属于无法查明父母或者其他监护人的打拐解救儿童的，登记保存公安机关出具的打拐解救儿童临时照料通知书、DNA信息比对结果、暂时未查找到生父母或者其他监护人的证明，儿童福利机构发布的寻亲公告，民政部门接收意见以及其他与儿童有关的材料。 （三）属于超过3个月仍无法查明父母或者其他监护人的流浪乞讨儿童的，登记保存公安机关出具的DNA信息比对结果、未成年人救助保护机构发布的寻亲公告、民政部门接收意见以及其他与儿童有关的材料。"},{"i":11,"n":"第十一条","txt":"儿童福利机构收留抚养本办法第九条第（二）项规定的儿童的，应当登记保存儿童户籍所在地乡镇人民政府（街道办事处）提交的儿童父母死亡证明或者宣告死亡、宣告失踪的判决书以及没有其他依法具有监护资格的人的情况报告，民政部门接收意见等材料。"},{"i":12,"n":"第十二条","txt":"儿童福利机构收留抚养本办法第九条第（三）项规定的儿童的，应当登记保存儿童户籍所在地乡镇人民政府（街道办事处）提交的父母没有监护能力的情况报告、没有其他依法具有监护资格的人的情况报告，民政部门接收意见等材料。 父母一方死亡或者失踪的，还应当登记保存死亡或者失踪一方的死亡证明或者宣告死亡、宣告失踪的判决书。"},{"i":13,"n":"第十三条","txt":"儿童福利机构收留抚养本办法第九条第（四）项规定的儿童的，应当登记保存人民法院生效判决书、民政部门接收意见等材料。"},{"i":14,"n":"第十四条","txt":"儿童福利机构可以接受未成年人救助保护机构委托，收留抚养民政部门承担临时监护责任的儿童。儿童福利机构应当与未成年人救助保护机构签订委托协议。 儿童福利机构应当接收需要集中供养的未满16周岁的特困人员。"},{"i":15,"n":"第十五条","txt":"儿童福利机构接收儿童后，应当及时送医疗机构进行体检和传染病检查。确实无法送医疗机构的，应当先行隔离照料。"},{"i":16,"n":"第十六条","txt":"儿童福利机构收留抚养本办法第九条第（一）项规定的儿童的，应当保存儿童随身携带的能够标识其身份或者具有纪念价值的物品。"},{"i":17,"n":"第十七条","txt":"儿童福利机构收留抚养本办法第九条规定的儿童，应当及时到当地公安机关申请办理户口登记。"},{"i":18,"n":"第十八条","txt":"儿童福利机构应当根据《儿童福利机构基本规范》等国家标准、行业标准，提供日常生活照料、基本医疗、基本康复等服务，依法保障儿童受教育的权利。"},{"i":19,"n":"第十九条","txt":"儿童福利机构应当设置起居室、活动室、医疗室、隔离室、康复室、厨房、餐厅、值班室、卫生间、储藏室等功能区域，配备符合儿童安全保护要求的设施设备。"},{"i":20,"n":"第二十条","txt":"儿童福利机构应当考虑儿童个体差异，组织专业人员进行评估，并制定个性化抚养方案。"},{"i":21,"n":"第二十一条","txt":"儿童福利机构应当提供吃饭、穿衣、如厕、洗澡等生活照料服务。 除重度残疾儿童外，对于6周岁以上儿童，儿童福利机构应当按照性别区分生活区域。女童应当由女性工作人员提供前款规定的生活照料服务。 儿童福利机构提供的饮食应当符合卫生要求，有利于儿童营养平衡。"},{"i":22,"n":"第二十二条","txt":"儿童福利机构应当保障儿童参加基本医疗保险，安排儿童定期体检、免疫接种，做好日常医疗护理、疾病预防控制等工作。 儿童福利机构可以通过设立医疗机构或者采取与定点医疗机构合作的方式，为儿童提供基本医疗服务。 发现儿童为疑似传染病病人或者精神障碍患者时，儿童福利机构应当依照传染病防治、精神卫生等相关法律法规的规定处理。"},{"i":23,"n":"第二十三条","txt":"儿童福利机构应当根据儿童的残疾状况提供有针对性的康复服务。暂不具备条件的，可以与有资质的康复服务机构合作开展康复服务。"},{"i":24,"n":"第二十四条","txt":"对符合入学条件的儿童，儿童福利机构应当依法保障其接受普通教育；对符合特殊教育学校入学条件的儿童，应当依法保障其接受特殊教育。 鼓励具备条件的儿童福利机构开展特殊教育服务。"},{"i":25,"n":"第二十五条","txt":"儿童确需跨省级行政区域接受手术医治、康复训练、特殊教育的，儿童福利机构应当选择具备相应资质的机构，并经所属民政部门批准同意。 儿童福利机构应当动态掌握儿童情况，并定期实地探望。"},{"i":26,"n":"第二十六条","txt":"对于符合条件、适合送养的儿童，儿童福利机构依法安排送养。送养儿童前，儿童福利机构应当将儿童的智力、精神健康、患病及残疾状况等重要事项如实告知收养申请人。 对于符合家庭寄养条件的儿童，儿童福利机构按照《家庭寄养管理办法》的规定办理。"},{"i":27,"n":"第二十七条","txt":"出现下列情形，儿童福利机构应当为儿童办理离院手续： （一）儿童父母或者其他监护人出现的； （二）儿童父母恢复监护能力或者有其他依法具有监护资格的人的； （三）儿童父母或者其他监护人恢复监护人资格的； （四）儿童被依法收养的； （五）儿童福利机构和未成年人救助保护机构签订的委托协议期满或者被解除的； （六）其他情形应当离院的。"},{"i":28,"n":"第二十八条","txt":"出现本办法第二十七条第（一）项情形的，儿童福利机构应当根据情况登记保存公安机关出具的打拐解救儿童送还通知书，儿童确属于走失、被盗抢或者被拐骗的结案证明，人民法院撤销宣告失踪或者宣告死亡的判决书，以及能够反映原监护关系的材料等。 出现本办法第二十七条第（二）项情形的，儿童福利机构应当登记保存儿童原户籍所在地乡镇人民政府（街道办事处）提交的父母恢复监护能力或者有其他依法具有监护资格的人的情况报告。 出现本办法第二十七条第（三）项情形的，儿童福利机构应当登记保存人民法院恢复监护人资格的判决书。 出现本办法第二十七条第（一）项至第（三）项情形的，儿童福利机构还应当登记保存父母、其他监护人或者其他依法具有监护资格的人提交的户口簿、居民身份证复印件等证明身份的材料以及民政部门离院意见等材料。 出现本办法第二十七条第（四）项情形的，儿童福利机构应当登记保存收养登记证复印件、民政部门离院意见等材料。"},{"i":29,"n":"第二十九条","txt":"儿童离院的，儿童福利机构应当出具儿童离院确认书。"},{"i":30,"n":"第三十条","txt":"由民政部门担任监护人的儿童年满18周岁后，儿童福利机构应当报请所属民政部门提请本级人民政府解决其户籍、就学、就业、住房、社会保障等安置问题，并及时办理离院手续。"},{"i":31,"n":"第三十一条","txt":"儿童福利机构收留抚养的儿童正常死亡或者经医疗卫生机构救治非正常死亡的，儿童福利机构应当取得负责救治或者正常死亡调查的医疗卫生机构签发的《居民死亡医学证明（推断）书》；儿童未经医疗卫生机构救治非正常死亡的，儿童福利机构应当取得由公安司法部门按照规定及程序出具的死亡证明。 儿童福利机构应当及时将儿童死亡情况报告所属民政部门，并依法做好遗体处理、户口注销等工作。"},{"i":32,"n":"第三十二条","txt":"儿童福利机构应当按照国家有关规定建立健全安全、食品、应急、财务、档案管理、信息化等制度。"},{"i":33,"n":"第三十三条","txt":"儿童福利机构应当落实岗位安全责任，在各出入口、接待大厅、楼道、食堂、观察室以及儿童康复、教育等区域安装具有存储功能的视频监控系统。监控录像资料保存期不少于3个月，载有特殊、重要资料的存储介质应当归档保存。"},{"i":34,"n":"第三十四条","txt":"儿童福利机构应当实行24小时值班巡查制度。值班人员应当熟知机构内抚养儿童情况，做好巡查记录，在交接班时重点交接患病等特殊状况儿童。"},{"i":35,"n":"第三十五条","txt":"儿童福利机构应当依法建立并落实逐级消防安全责任制，健全消防安全管理制度，按照国家标准、行业标准配置消防设施、器材，对消防设施、器材进行维护保养和检测，保障疏散通道、安全出口、消防车通道畅通，开展日常防火巡查、检查，定期组织消防安全教育培训和灭火、应急疏散演练。"},{"i":36,"n":"第三十六条","txt":"儿童福利机构应当加强食品安全管理，保障儿童用餐安全卫生、营养健康。 儿童福利机构内设食堂的，应当取得市场监管部门的食品经营许可；儿童福利机构从供餐单位订餐以及外购预包装食品的，应当从取得食品生产经营许可的企业订购，并按照要求对订购的食品进行查验。 儿童福利机构应当按照有关规定对食品留样备查。"},{"i":37,"n":"第三十七条","txt":"儿童福利机构应当制定疫情、火灾、食物中毒等突发事件应急预案。 突发事件发生后，儿童福利机构应当立即启动应急处理程序，根据突发事件应对管理职责分工向有关部门报告。"},{"i":38,"n":"第三十八条","txt":"儿童福利机构应当执行国家统一的会计制度，依法使用资金，专款专用，不得挪用、截留孤儿基本生活费等专项经费。"},{"i":39,"n":"第三十九条","txt":"儿童福利机构应当建立儿童个人档案，做到一人一档。"},{"i":40,"n":"第四十条","txt":"儿童福利机构应当依托全国儿童福利信息管理系统，及时采集并录入儿童的基本情况及重要医疗、康复、教育等信息，并定期更新数据。"},{"i":41,"n":"第四十一条","txt":"儿童福利机构应当根据工作需要设置岗位。从事医疗卫生等准入类职业的专业技术人员，应当持相关的国家职业资格证书上岗。鼓励其他专业人员接受职业技能培训。"},{"i":42,"n":"第四十二条","txt":"儿童福利机构应当鼓励、支持工作人员参加职业资格考试或者职称评定，按照国家有关政策妥善解决医疗、康复、教育、社会工作等专业技术人员的职称、工资及福利待遇。 儿童福利机构工作人员着装应当整洁、统一。"},{"i":43,"n":"第四十三条","txt":"儿童福利机构与境外组织开展活动和合作项目的，应当按照国家有关规定办理相关手续。"},{"i":44,"n":"第四十四条","txt":"县级以上地方人民政府民政部门应当支持儿童福利机构发展，协调落实相关政策和保障措施。"},{"i":45,"n":"第四十五条","txt":"鼓励县级以上地方人民政府民政部门通过引入专业社会工作机构、公益慈善项目等多种方式提高儿童福利机构专业服务水平。"},{"i":46,"n":"第四十六条","txt":"县级以上地方人民政府民政部门应当加强儿童福利机构人员队伍建设，定期培训儿童福利机构相关人员。"},{"i":47,"n":"第四十七条","txt":"县级以上地方人民政府民政部门应当建立健全日常监管制度，对其设立的儿童福利机构及工作人员履行下列监督管理职责： （一）负责对儿童福利机构建立健全内部管理制度、规范服务流程、加强风险防控等情况进行监督检查； （二）负责对执行儿童福利机构管理相关法律法规及本办法情况进行监督检查； （三）负责对违反儿童福利机构管理相关法律法规及本办法行为，依法给予处分； （四）负责儿童福利机构监督管理的其他事项。 上级民政部门应当加强对下级民政部门的指导和监督检查，及时处理儿童福利机构管理中的违法违规行为。"},{"i":48,"n":"第四十八条","txt":"对私自收留抚养无法查明父母或者其他监护人的儿童的社会服务机构、宗教活动场所等组织，县级以上地方人民政府民政部门应当会同公安、宗教事务等有关部门责令其停止收留抚养活动，并将收留抚养的儿童送交儿童福利机构。 对现存的与民政部门签订委托代养协议的组织，民政部门应当加强监督管理。"},{"i":49,"n":"第四十九条","txt":"儿童福利机构及其工作人员不依法履行收留抚养职责，或者歧视、侮辱、虐待儿童的，由所属民政部门责令改正，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":50,"n":"第五十条","txt":"民政部门及其工作人员在儿童福利机构管理工作中滥用职权、玩忽职守、徇私舞弊的，由有权机关责令改正，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":51,"n":"第五十一条","txt":"本办法所称未成年人救助保护机构是指未成年人（救助）保护中心和设有未成年人救助保护科（室）的救助管理站。"},{"i":52,"n":"第五十二条","txt":"本办法自2019年1月1日起施行。"}],"gongmuguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为加强公墓管理，根据《国务院关于殡葬管理的暂行规定》和有关规定制定本办法。"},{"i":2,"n":"第二条","txt":"在火葬区，要提倡骨灰深埋、撒放等一次性处理，也可经批准有计划地建立骨灰公墓。在土葬改革区，应有计划地建立遗体公墓或骨灰公墓。"},{"i":3,"n":"第三条","txt":"公墓是为城乡居民提供安葬骨灰和遗体的公共设施。公墓分为公益性公墓和经营性公墓。公益性公墓是为农村村民提供遗体或骨灰安葬服务的公共墓地。经营性公墓是为城镇居民提供骨灰或遗体安葬实行有偿服务的公共墓地，属于第三产业。"},{"i":4,"n":"第四条","txt":"建立公墓应当选用荒山瘠地，不得占用耕地，不得建在风景名胜区和水库、湖泊、河流的堤坝以及铁路、公路两侧。"},{"i":5,"n":"第五条","txt":"公益性公墓由村民委员会建立。经营性公墓由殡葬事业单位建立。"},{"i":6,"n":"第六条","txt":"民政部是全国公墓的主管部门，负责制定公墓建设的政策法规和总体规划，进行宏观指导。县级以上各级民政部门是本行政区域内的公墓主管部门，负责贯彻执行国家公墓政策法规，对本行政区域内的公墓建设和发展进行具体指导。"},{"i":7,"n":"第七条","txt":"建立公墓，需向公墓主管部门提出申请。"},{"i":8,"n":"第八条","txt":"申请时，应向公墓主管部门提交下列材料： (一)建立公墓的申请报告； (二)城乡建设、土地管理部门的审查意见； (三)建立公墓的可行性报告； (四)其他有关材料。"},{"i":9,"n":"第九条","txt":"建立公益性公墓，由村民委员会提出申请，报县级民政部门批准。"},{"i":10,"n":"第十条","txt":"建立经营性公墓，由建墓单位向县级民政部门提出申请，经同级人民政府审核同意，报省、自治区、直辖市民政厅(局)批准。"},{"i":11,"n":"第十一条","txt":"与外国、港澳台人士合作、合资或利用外资建立经营性公墓，经同级人民政府和省、自治区、直辖市民政厅(局)审核同意，报民政部批准。"},{"i":12,"n":"第十二条","txt":"经营性公墓，由建墓单位持批准文件，向当地工商行政管理部门领取营业执照，方可正式营业。"},{"i":13,"n":"第十三条","txt":"公墓墓区土地所有权依法归国家或集体所有，丧主不得自行转让或买卖。"},{"i":14,"n":"第十四条","txt":"公墓单位应视墓区范围的大小设置公墓管理机构或聘用专职管理人员，负责墓地的建设、管理和维护。 墓地应当保持整洁、肃穆。"},{"i":15,"n":"第十五条","txt":"公墓墓志要小型多样，墓区要合理规划，因地制宜进行绿化美化，逐步实行园林化。"},{"i":16,"n":"第十六条","txt":"未经批准，公益性公墓不得对外经营殡仪业务。经营性公墓的墓穴管理费一次性收取最长不得超过二十年。墓穴用地要节约。"},{"i":17,"n":"第十七条","txt":"凡在经营性公墓内安葬骨灰或遗体的，丧主应按规定交纳墓穴租用费、建墓工料费、安葬费和护墓管理费。"},{"i":18,"n":"第十八条","txt":"严禁在公墓内建家族、宗族、活人坟和搞封建迷信活动。"},{"i":19,"n":"第十九条","txt":"严禁在土葬改革区经营火化区死亡人员的遗体安葬业务。"},{"i":20,"n":"第二十条","txt":"本办法实施后，凡违反本办法有关规定，由公墓主管部门区别情况，予以处罚，或没收其非法所得，或处以罚款。具体处罚办法，由各省、自治区、直辖市民政厅(局)制定。"},{"i":21,"n":"第二十一条","txt":"本办法实施前建立的各类公墓，凡符合本办法有关规定但未办理审批手续的，应按本办法第二章的规定补办审批手续；不符合本办法规定的，由公墓单位报公墓主管部门，根据不同情况妥善处理；对城市现有的墓地、坟岗，除另有法律法规规定外，一律由当地殡葬事业单位负责接管和改造。"},{"i":22,"n":"第二十二条","txt":"革命烈士公墓、知名人士墓、华侨祖墓、具有历史艺术科学价值的古墓和回民公墓以及外国人在华墓地的管理，按原有规定执行。"},{"i":23,"n":"第二十三条","txt":"各省、自治区、直辖市可根据本办法制定本地区的实施细则。"},{"i":24,"n":"第二十四条","txt":"本办法自发布之日起实行。原内务部、民政部过去有关公墓管理的规定，凡与本办法有抵触的，均按本办法执行。"}],"yanglaojigouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范对养老机构的管理，促进养老服务健康发展，根据《中华人民共和国老年人权益保障法》和有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称养老机构是指依法办理登记，为老年人提供全日集中住宿和照料护理服务，床位数在10张以上的机构。 养老机构包括营利性养老机构和非营利性养老机构。"},{"i":3,"n":"第三条","txt":"县级以上人民政府民政部门负责养老机构的指导、监督和管理。其他有关部门依照职责分工对养老机构实施监督。"},{"i":4,"n":"第四条","txt":"养老机构应当按照建筑、消防、食品安全、医疗卫生、特种设备等法律、法规和强制性标准开展服务活动。 养老机构及其工作人员应当依法保障收住老年人的人身权、财产权等合法权益。"},{"i":5,"n":"第五条","txt":"入住养老机构的老年人及其代理人应当遵守养老机构的规章制度，维护养老机构正常服务秩序。"},{"i":6,"n":"第六条","txt":"政府投资兴办的养老机构在满足特困人员集中供养需求的前提下，优先保障经济困难的孤寡、失能、高龄、计划生育特殊家庭等老年人的服务需求。 政府投资兴办的养老机构，可以采取委托管理、租赁经营等方式，交由社会力量运营管理。"},{"i":7,"n":"第七条","txt":"民政部门应当会同有关部门采取措施，鼓励、支持企业事业单位、社会组织或者个人兴办、运营养老机构。 鼓励自然人、法人或者其他组织依法为养老机构提供捐赠和志愿服务。"},{"i":8,"n":"第八条","txt":"鼓励养老机构加入养老服务行业组织，加强行业自律和诚信建设，促进行业规范有序发展。"},{"i":9,"n":"第九条","txt":"设立营利性养老机构，应当在市场监督管理部门办理登记。设立非营利性养老机构，应当依法办理相应的登记。 养老机构登记后即可开展服务活动。"},{"i":10,"n":"第十条","txt":"营利性养老机构办理备案，应当在收住老年人后10个工作日以内向服务场所所在地的县级人民政府民政部门提出。非营利性养老机构办理备案，应当在收住老年人后10个工作日以内向登记管理机关同级的人民政府民政部门提出。"},{"i":11,"n":"第十一条","txt":"养老机构办理备案，应当向民政部门提交备案申请书、养老机构登记证书、符合本办法第四条要求的承诺书等材料，并对真实性负责。 备案申请书应当包括下列内容： （一）养老机构基本情况，包括名称、住所、法定代表人或者主要负责人信息等； （二）服务场所权属； （三）养老床位数量； （四）服务设施面积； （五）联系人和联系方式。 民政部门应当加强信息化建设，逐步实现网上备案。"},{"i":12,"n":"第十二条","txt":"民政部门收到养老机构备案材料后，对材料齐全的，应当出具备案回执；材料不齐全的，应当指导养老机构补正。"},{"i":13,"n":"第十三条","txt":"已经备案的养老机构变更名称、法定代表人或者主要负责人等登记事项，或者变更服务场所权属、养老床位数量、服务设施面积等事项的，应当及时向原备案民政部门办理变更备案。 养老机构在原备案机关辖区内变更服务场所的，应当及时向原备案民政部门办理变更备案。营利性养老机构跨原备案机关辖区变更服务场所的，应当及时向变更后的服务场所所在地县级人民政府民政部门办理备案。"},{"i":14,"n":"第十四条","txt":"民政部门应当通过政府网站、政务新媒体、办事大厅公示栏、服务窗口等途径向社会公开备案事项及流程、材料清单等信息。 民政部门应当依托全国一体化在线政务服务平台，推进登记管理机关、备案机关信息系统互联互通、数据共享。"},{"i":15,"n":"第十五条","txt":"养老机构应当建立入院评估制度，对老年人的身心状况进行评估，并根据评估结果确定照料护理等级。 老年人身心状况发生变化，需要变更照料护理等级的，养老机构应当重新进行评估。 养老机构确定或者变更老年人照料护理等级，应当经老年人或者其代理人同意。"},{"i":16,"n":"第十六条","txt":"养老机构应当与老年人或者其代理人签订服务协议，明确当事人的权利和义务。 服务协议一般包括下列条款： （一）养老机构的名称、住所、法定代表人或者主要负责人、联系方式； （二）老年人或者其代理人和紧急联系人的姓名、住址、身份证明、联系方式； （三）照料护理等级和服务内容、服务方式； （四）收费标准和费用支付方式； （五）服务期限和场所； （六）协议变更、解除与终止的条件； （七）暂停或者终止服务时老年人安置方式； （八）违约责任和争议解决方式； （九）当事人协商一致的其他内容。"},{"i":17,"n":"第十七条","txt":"养老机构按照服务协议为老年人提供生活照料、康复护理、精神慰藉、文化娱乐等服务。"},{"i":18,"n":"第十八条","txt":"养老机构应当为老年人提供饮食、起居、清洁、卫生等生活照料服务。 养老机构应当提供符合老年人住宿条件的居住用房，并配备适合老年人安全保护要求的设施、设备及用具，定期对老年人的活动场所和物品进行消毒和清洗。 养老机构提供的饮食应当符合食品安全要求、适宜老年人食用、有利于老年人营养平衡、符合民族风俗习惯。"},{"i":19,"n":"第十九条","txt":"养老机构应当为老年人建立健康档案，开展日常保健知识宣传，做好疾病预防工作。养老机构在老年人突发危重疾病时，应当及时转送医疗机构救治并通知其紧急联系人。 养老机构可以通过设立医疗机构或者采取与周边医疗机构合作的方式，为老年人提供医疗服务。养老机构设立医疗机构的，应当按照医疗机构管理相关法律法规进行管理。"},{"i":20,"n":"第二十条","txt":"养老机构发现老年人为传染病病人或者疑似传染病病人的，应当及时向附近的疾病预防控制机构或者医疗机构报告，配合实施卫生处理、隔离等预防控制措施。 养老机构发现老年人为疑似精神障碍患者的，应当依照精神卫生相关法律法规的规定处理。"},{"i":21,"n":"第二十一条","txt":"养老机构应当根据需要为老年人提供情绪疏导、心理咨询、危机干预等精神慰藉服务。"},{"i":22,"n":"第二十二条","txt":"养老机构应当开展适合老年人的文化、教育、体育、娱乐活动，丰富老年人的精神文化生活。 养老机构开展文化、教育、体育、娱乐活动时，应当为老年人提供必要的安全防护措施。"},{"i":23,"n":"第二十三条","txt":"养老机构应当为老年人家庭成员看望或者问候老年人提供便利，为老年人联系家庭成员提供帮助。"},{"i":24,"n":"第二十四条","txt":"鼓励养老机构运营社区养老服务设施，或者上门为居家老年人提供助餐、助浴、助洁等服务。"},{"i":25,"n":"第二十五条","txt":"养老机构应当按照国家有关规定建立健全安全、消防、食品、卫生、财务、档案管理等规章制度，制定服务标准和工作流程，并予以公开。"},{"i":26,"n":"第二十六条","txt":"养老机构应当配备与服务和运营相适应的工作人员，并依法与其签订聘用合同或者劳动合同，定期开展职业道德教育和业务培训。 养老机构中从事医疗、康复、消防等服务的人员，应当具备相应的职业资格。 养老机构应当加强对养老护理人员的职业技能培训，建立健全体现职业技能等级等因素的薪酬制度。"},{"i":27,"n":"第二十七条","txt":"养老机构应当依照其登记类型、经营性质、运营方式、设施设备条件、管理水平、服务质量、照料护理等级等因素合理确定服务项目的收费标准，并遵守国家和地方政府价格管理有关规定。 养老机构应当在醒目位置公示各类服务项目收费标准和收费依据，接受社会监督。"},{"i":28,"n":"第二十八条","txt":"养老机构应当实行24小时值班，做好老年人安全保障工作。 养老机构应当在各出入口、接待大厅、值班室、楼道、食堂等公共场所安装视频监控设施，并妥善保管视频监控记录。"},{"i":29,"n":"第二十九条","txt":"养老机构内设食堂的，应当取得市场监督管理部门颁发的食品经营许可证，严格遵守相关法律、法规和食品安全标准，执行原料控制、餐具饮具清洗消毒、食品留样等制度，并依法开展食堂食品安全自查。 养老机构从供餐单位订餐的，应当从取得食品生产经营许可的供餐单位订购，并按照要求对订购的食品进行查验。"},{"i":30,"n":"第三十条","txt":"养老机构应当依法履行消防安全职责，健全消防安全管理制度，实行消防工作责任制，配置消防设施、器材并定期检测、维修，开展日常防火巡查、检查，定期组织灭火和应急疏散消防安全培训。 养老机构的法定代表人或者主要负责人对本单位消防安全工作全面负责，属于消防安全重点单位的养老机构应当确定消防安全管理人，负责组织实施本单位消防安全管理工作，并报告当地消防救援机构。"},{"i":31,"n":"第三十一条","txt":"养老机构应当依法制定自然灾害、事故灾难、公共卫生事件、社会安全事件等突发事件应急预案，在场所内配备报警装置和必要的应急救援设备、设施，定期开展突发事件应急演练。 突发事件发生后，养老机构应当立即启动应急预案，采取防止危害扩大的必要处置措施，同时根据突发事件应对管理职责分工向有关部门和民政部门报告。"},{"i":32,"n":"第三十二条","txt":"养老机构应当建立老年人信息档案，收集和妥善保管服务协议等相关资料。档案的保管期限不少于服务协议期满后五年。 养老机构及其工作人员应当保护老年人的个人信息和隐私。"},{"i":33,"n":"第三十三条","txt":"养老机构应当按照国家有关规定接受、使用捐赠、资助。 鼓励养老机构为社会工作者、志愿者在机构内开展服务提供便利。"},{"i":34,"n":"第三十四条","txt":"鼓励养老机构投保责任保险，降低机构运营风险。"},{"i":35,"n":"第三十五条","txt":"养老机构因变更或者终止等原因暂停、终止服务的，应当在合理期限内提前书面通知老年人或者其代理人，并书面告知民政部门。 老年人需要安置的，养老机构应当根据服务协议约定与老年人或者其代理人协商确定安置事宜。民政部门应当为养老机构妥善安置老年人提供帮助。 养老机构终止服务后，应当依法清算并办理注销登记。"},{"i":36,"n":"第三十六条","txt":"民政部门应当加强对养老机构服务和运营的监督检查，发现违反本办法规定的，及时依法予以处理并向社会公布。 民政部门在监督检查中发现养老机构存在应当由其他部门查处的违法违规行为的，及时通报有关部门处理。"},{"i":37,"n":"第三十七条","txt":"民政部门依法履行监督检查职责，可以采取以下措施： （一）向养老机构和个人了解情况； （二）进入涉嫌违法的养老机构进行现场检查； （三）查阅或者复制有关合同、票据、账簿及其他有关资料； （四）发现养老机构存在可能危及人身健康和生命财产安全风险的，责令限期改正，逾期不改正的，责令停业整顿。 民政部门实施监督检查时，监督检查人员不得少于2人，应当出示执法证件。 对民政部门依法进行的监督检查，养老机构应当配合，如实提供相关资料和信息，不得隐瞒、拒绝、阻碍。"},{"i":38,"n":"第三十八条","txt":"对已经备案的养老机构，备案民政部门应当自备案之日起20个工作日以内进行现场检查，并核实备案信息；对未备案的养老机构，服务场所所在地的县级人民政府民政部门应当自发现其收住老年人之日起20个工作日以内进行现场检查，并督促及时备案。 民政部门应当每年对养老机构服务安全和质量进行不少于一次的现场检查。"},{"i":39,"n":"第三十九条","txt":"民政部门应当采取随机抽取检查对象、随机选派检查人员的方式对养老机构实施监督检查。抽查情况及查处结果应当及时向社会公布。 民政部门应当结合养老机构的服务规模、信用记录、风险程度等情况，确定抽查比例和频次。对违法失信、风险高的养老机构，适当提高抽查比例和频次，依法依规实施严管和惩戒。"},{"i":40,"n":"第四十条","txt":"民政部门应当加强对养老机构非法集资的防范、监测和预警工作，发现养老机构涉嫌非法集资的，按照有关规定及时移交相关部门。"},{"i":41,"n":"第四十一条","txt":"民政部门应当充分利用信息技术手段，加强对养老机构的监督检查，提高监管能力和水平。"},{"i":42,"n":"第四十二条","txt":"民政部门应当定期开展养老服务行业统计工作，养老机构应当及时准确报送相关信息。"},{"i":43,"n":"第四十三条","txt":"养老机构应当听取老年人或者其代理人的意见和建议，发挥其对养老机构服务和运营的监督促进作用。"},{"i":44,"n":"第四十四条","txt":"民政部门应当畅通对养老机构的举报投诉渠道，依法及时处理有关举报投诉。"},{"i":45,"n":"第四十五条","txt":"民政部门发现个人或者组织未经登记以养老机构名义开展活动的，应当书面通报相关登记管理机关，并配合做好查处工作。"},{"i":46,"n":"第四十六条","txt":"养老机构有下列行为之一的，由民政部门责令改正，给予警告；情节严重的，处以3万元以下的罚款： （一）未建立入院评估制度或者未按照规定开展评估活动的； （二）未与老年人或者其代理人签订服务协议，或者未按照协议约定提供服务的； （三）未按照有关强制性国家标准提供服务的； （四）工作人员的资格不符合规定的； （五）利用养老机构的房屋、场地、设施开展与养老服务宗旨无关的活动的； （六）未依照本办法规定预防和处置突发事件的； （七）歧视、侮辱、虐待老年人以及其他侵害老年人人身和财产权益行为的； （八）向负责监督检查的民政部门隐瞒有关情况、提供虚假材料或者拒绝提供反映其活动情况真实材料的； （九）法律、法规、规章规定的其他违法行为。 养老机构及其工作人员违反本办法有关规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"民政部门及其工作人员在监督管理工作中滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他责任人员依法依规给予处分；构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"国家对农村五保供养服务机构的管理有特别规定的，依照其规定办理。"},{"i":49,"n":"第四十九条","txt":"本办法自2020年11月1日起施行。2013年6月28日民政部发布的《养老机构管理办法》同时废止。"}],"junduiwujunjituixiutuizhizhigongfuwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了做好军队无军籍退休退职职工服务管理工作，根据国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称军队无军籍退休退职职工，是指已移交政府安置的中国人民解放军和中国人民武装警察部队无军籍退休退职职工（以下简称无军籍职工）。"},{"i":3,"n":"第三条","txt":"无军籍职工服务管理应当从维护无军籍职工的合法权益出发，贯彻执行国家关于无军籍职工的政策，完善无军籍职工服务管理机制，落实无军籍职工生活待遇。 无军籍职工服务管理应当与经济社会发展水平相适应，坚持国家保障与社会化服务相结合原则。"},{"i":4,"n":"第四条","txt":"无军籍职工服务管理实行政府领导、民政部门主管。按照属地原则，无军籍职工安置地乡镇人民政府、街道办事处，民政部门指定机构是无军籍职工的服务管理单位，承担无军籍职工服务管理具体工作。 民政部门应当及时将无军籍职工接收安置计划和方案报请本级人民政府同意，协调有关部门研究解决无军籍职工服务管理重大问题，加强对无军籍职工服务管理的指导。"},{"i":5,"n":"第五条","txt":"服务管理单位应当按照规定办理或者协助办理无军籍职工党员组织关系转接事宜，保障无军籍职工党员参加党组织生活。"},{"i":6,"n":"第六条","txt":"服务管理单位应当做好以下服务管理工作： （一）发放无军籍职工退休退职费和津贴补贴； （二）按规定协助落实无军籍职工医疗待遇； （三）定期了解无军籍职工情况和需求，提供必要的关心照顾； （四）宣传解释无军籍职工相关政策； （五）按规定做好其他服务管理工作。 县级以上人民政府民政部门应当根据本级人民政府有关部门对事业单位退休人员待遇调整情况，提出无军籍职工待遇调整方案，经本级人民政府同意后，按规定通知服务管理单位执行。"},{"i":7,"n":"第七条","txt":"服务管理单位应当建立健全工作制度，协调利用为老服务资源，为无军籍职工老有所养、老有所医、老有所学、老有所为、老有所乐创造条件。 服务管理单位可以通过政府购买服务方式聘用工作人员、租用场地设施。"},{"i":8,"n":"第八条","txt":"服务管理单位应当加强无军籍职工思想政治工作，提高无军籍职工遵纪守法和遵守服务管理单位规章制度的自觉性。"},{"i":9,"n":"第九条","txt":"服务管理单位应当引导无军籍职工保持和发扬优良传统，发挥专业特长，积极参与社区建设和社会公益活动。"},{"i":10,"n":"第十条","txt":"服务管理单位应当引导无军籍职工参加社区组织开展的有益身心健康的文体活动。"},{"i":11,"n":"第十一条","txt":"鼓励社会组织、专业社会工作者、志愿者等社会力量为无军籍职工及其家庭提供形式多样的个性化服务。 鼓励身体健康、乐于奉献的无军籍职工参与服务管理，增强无军籍职工自我管理、自我教育、自我服务能力。"},{"i":12,"n":"第十二条","txt":"服务管理单位应当配备档案管理设施，妥善保管无军籍职工档案，提供必要的档案利用服务。"},{"i":13,"n":"第十三条","txt":"服务管理单位应当定期开展教育培训、岗位练兵，提高工作人员思想政治素质、政策理论水平和服务管理能力。"},{"i":14,"n":"第十四条","txt":"对在无军籍职工服务管理中做出显著成绩的单位和个人，纳入军休干部安置管理表彰范围。"},{"i":15,"n":"第十五条","txt":"对已移交政府安置的军队无军籍离休干部的服务管理，可以参照本办法执行。国家对军队无军籍离休干部服务管理另有规定的，从其规定。"},{"i":16,"n":"第十六条","txt":"本办法自2016年2月1日起施行。"}],"nongcunwubaogongyangfuwujigouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强农村五保供养服务机构管理，提高供养服务能力和水平，保障农村五保供养对象的正常生活，根据《农村五保供养工作条例》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称农村五保供养服务机构，是指县级人民政府民政部门或者乡、民族乡、镇人民政府（以下简称主办机关）举办的，为农村五保供养对象提供供养服务的公益性机构。 符合条件的农村五保供养服务机构，应当依法办理事业单位法人登记。"},{"i":3,"n":"第三条","txt":"县级以上人民政府民政部门负责本行政区域内的农村五保供养服务机构管理工作。 乡、民族乡、镇人民政府管理其举办的农村五保供养服务机构，并接受县级人民政府民政部门的业务指导。"},{"i":4,"n":"第四条","txt":"农村五保供养服务机构实行等级评定，具体评定办法另行规定。"},{"i":5,"n":"第五条","txt":"县级以上人民政府民政部门对在农村五保供养服务机构建设、管理和服务工作中作出显著成绩的单位和个人，给予表彰和奖励。"},{"i":6,"n":"第六条","txt":"县级以上人民政府民政部门应当根据本级人民政府经济社会发展规划，会同有关部门编制农村五保供养服务机构建设专项规划，并组织实施。"},{"i":7,"n":"第七条","txt":"农村人口规模较大、农村五保供养对象较多的乡、民族乡、镇，应当建设能够满足当地农村五保供养对象集中供养需要的农村五保供养服务机构。 县级人民政府民政部门根据实际需要，可以建设能够满足若干乡、民族乡、镇农村五保供养对象集中供养需要的农村五保供养服务机构。"},{"i":8,"n":"第八条","txt":"农村五保供养服务机构建设应当符合国家有关的建筑设计规范和标准，坚持改建、扩建、新建相结合，充分利用闲置的设施。 农村五保供养服务机构的建设规模原则上不少于40张床位。"},{"i":9,"n":"第九条","txt":"农村五保供养服务机构应当为每名农村五保供养对象提供使用面积不少于6平方米的居住用房。 农村五保供养服务机构应当建有厨房、餐厅、活动室、浴室、卫生间、办公室等辅助用房。"},{"i":10,"n":"第十条","txt":"农村五保供养服务机构应当配置基本生活设施，配备必要的膳食制作、医疗保健、文体娱乐、供暖降温、办公管理等设备。 有条件的农村五保供养服务机构应当具备开展农副业生产所必需的场地和设施。"},{"i":11,"n":"第十一条","txt":"对自愿选择集中供养的农村五保供养对象，经县级人民政府民政部门安排，有供养能力的农村五保供养服务机构不得拒绝接收。 农村五保供养服务机构应当优先供养生活不能自理的农村五保供养对象。"},{"i":12,"n":"第十二条","txt":"接收患有精神病、传染病农村五保供养对象的农村五保供养服务机构应当具备相应的治疗护理能力。"},{"i":13,"n":"第十三条","txt":"乡、民族乡、镇人民政府应当与农村五保供养服务机构签订供养服务协议，委托其为农村五保供养对象提供供养服务。协议范本由县级人民政府民政部门制定，并报上一级民政部门备案。"},{"i":14,"n":"第十四条","txt":"农村五保供养服务机构在满足当地农村五保供养对象集中供养需要的基础上，可以开展社会养老服务。 开展社会养老服务的农村五保供养服务机构应当与服务对象或者其赡养人签订协议，约定双方的权利和义务。 农村五保供养服务机构不得因开展社会养老服务降低对农村五保供养对象的集中供养条件和服务水平。"},{"i":15,"n":"第十五条","txt":"农村五保供养对象和社会养老服务对象应当遵守农村五保供养服务机构的规章制度，爱护公共财物，文明礼貌，团结互助。"},{"i":16,"n":"第十六条","txt":"农村五保供养服务机构应当向农村五保供养对象提供下列服务： （一）提供符合食品卫生要求、适合农村五保供养对象需要的膳食； （二）提供服装、被褥等生活用品和零用钱； （三）提供符合居住条件的住房； （四）提供日常诊疗服务，对生活不能自理的给予护理照料； （五）妥善办理丧葬事宜。 集中供养的农村五保供养对象未满16周岁或者已满16周岁仍在接受义务教育的，农村五保供养服务机构应当依法保证其接受并完成义务教育，保障所需费用。 有条件的农村五保供养服务机构应当为集中供养的重度残疾五保供养对象适配基本型辅助器具。"},{"i":17,"n":"第十七条","txt":"农村五保供养服务机构的实际供养水平不得低于当地公布的农村五保集中供养标准。"},{"i":18,"n":"第十八条","txt":"农村五保供养服务机构提供的供养服务，应当符合有关法律法规和规章的规定，符合国家的标准规范，尊重少数民族习惯。"},{"i":19,"n":"第十九条","txt":"农村五保供养服务机构应当协同驻地乡镇卫生院或者其他医疗机构为农村五保供养对象提供日常诊疗服务。 经卫生行政部门许可，有条件的农村五保供养服务机构可以设立医务室，为农村五保供养对象提供日常诊疗服务。 农村五保供养服务机构应当协助有关部门保障农村五保供养对象享受农村合作医疗和农村医疗救助待遇。"},{"i":20,"n":"第二十条","txt":"农村五保供养服务机构应当提供亲情化服务，组织文化娱乐、体育健身等活动，丰富农村五保供养对象的精神生活。"},{"i":21,"n":"第二十一条","txt":"农村五保供养服务机构可以向分散供养的农村五保供养对象提供服务，具体服务方式由县级人民政府民政部门规定。"},{"i":22,"n":"第二十二条","txt":"农村五保供养服务机构应当建立健全财务管理、档案管理、环境卫生、安全保卫等规章制度，并向农村五保供养对象公开。"},{"i":23,"n":"第二十三条","txt":"农村五保供养服务机构实行院长负责制，主办机关应当定期对院长履行职责的情况进行考核。 农村五保供养服务机构应当根据实际需要科学设定岗位，明确岗位要求和工作流程，实行岗位责任制。"},{"i":24,"n":"第二十四条","txt":"农村五保供养服务机构应当设立院务管理委员会，实行院务公开。院务管理委员会由主办机关代表、农村五保供养对象代表和工作人员代表组成，其中农村五保供养对象代表应当达到1/2以上。 院务管理委员会由农村五保供养服务机构全体人员民主选举产生，履行以下职责： （一）监督本机构各项规章制度的执行情况； （二）监督本机构财务收支和管理情况； （三）监督院长和工作人员的工作； （四）调解农村五保供养对象之间的矛盾纠纷； （五）组织协调农村五保供养对象开展自我服务和自我管理； （六）其他院务管理职责。"},{"i":25,"n":"第二十五条","txt":"农村五保供养服务机构可以采取多种形式开展农副业生产，其收入应当用于改善农村五保供养对象的生活，任何单位和个人不得侵占、挪用。 农村五保供养服务机构可以鼓励农村五保供养对象参加有益身心健康和力所能及的生产活动，并给予适当报酬。"},{"i":26,"n":"第二十六条","txt":"农村五保供养服务机构管理和使用的资产，任何单位和个人不得侵占，需要办理登记的应当依据有关规定办理登记手续。"},{"i":27,"n":"第二十七条","txt":"农村五保供养服务机构应当根据服务对象的数量和需求，配备工作人员。 有条件的农村五保供养服务机构应当配备专业社会工作者。"},{"i":28,"n":"第二十八条","txt":"农村五保供养服务机构负责人由主办机关聘任，其他工作人员由农村五保供养服务机构聘用。"},{"i":29,"n":"第二十九条","txt":"农村五保供养服务机构或者其主办机关应当与工作人员订立聘用合同或者劳动合同。 农村五保供养服务机构或者其主办机关应当保障工作人员的工资待遇不低于当地最低工资标准，并为其办理相应的养老、医疗、工伤等社会保险。"},{"i":30,"n":"第三十条","txt":"县级人民政府民政部门应当对农村五保供养服务机构工作人员进行业务培训，考核合格的，准予上岗服务。"},{"i":31,"n":"第三十一条","txt":"农村五保供养服务机构的建设资金和管理资金应当按照财政预算管理程序申报，经审核后从财政预算中安排。 管理资金是指维持农村五保供养服务机构正常运转必需支出的各项费用，主要包括工作人员工资、办公经费、设备设施购置维护经费和水电燃料费等。"},{"i":32,"n":"第三十二条","txt":"农村五保供养对象的集中供养资金应当按照当地人民政府公布的集中供养标准，纳入县乡财政专项保障，并按时拨付到农村五保供养服务机构。 农村五保供养服务机构应当将集中供养资金全部用于为农村五保供养对象提供供养服务，不得挪作他用。"},{"i":33,"n":"第三十三条","txt":"县级以上人民政府民政部门应当每年从本级福利彩票公益金中安排一定数量，用于支持农村五保供养服务机构建设和维护。"},{"i":34,"n":"第三十四条","txt":"鼓励机关、企业、事业单位、社会组织、个人向农村五保供养服务机构提供捐赠，帮助改善农村五保供养对象的生活条件。"},{"i":35,"n":"第三十五条","txt":"农村五保供养服务机构有下列行为之一的，由县级人民政府民政部门或者乡、民族乡、镇人民政府责令限期改正；逾期不改正的，县级人民政府民政部门或者乡、民族乡、镇人民政府应当终止供养服务协议；造成损失的，依法承担赔偿责任： （一）歧视、虐待农村五保供养对象的； （二）未尽到管理和服务义务致使农村五保供养对象合法权益遭受侵害的； （三）侵占农村五保供养对象财产的； （四）其他违反规定的行为。"},{"i":36,"n":"第三十六条","txt":"农村五保供养服务机构工作人员有下列行为之一的，予以批评教育；情节严重的，予以辞退；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任： （一）私分、挪用、截留农村五保供养款物的； （二）私分、挪用农副业生产经营收入的； （三）辱骂、殴打、虐待农村五保供养对象的； （四）盗窃、侵占农村五保供养对象或者农村五保供养服务机构财产的； （五）其他违反规定的行为。"},{"i":37,"n":"第三十七条","txt":"农村五保供养对象有下列行为之一的，予以批评教育；情节严重的，停止集中供养；构成犯罪的，依法追究刑事责任： （一）违反农村五保供养服务机构的规定，扰乱正常生活秩序的； （二）打架、斗殴，造成他人身体伤害的； （三）损毁、盗窃、侵占农村五保供养服务机构或者其他农村五保供养对象财产的； （四）其他违反规定的行为。"},{"i":38,"n":"第三十八条","txt":"鼓励其他社会福利机构为农村五保供养对象提供供养服务，相关管理和服务参照本办法执行。"},{"i":39,"n":"第三十九条","txt":"本办法自2011年1月1日起施行。1997年3月18日民政部发布的《农村敬老院管理暂行办法》同时废止。"}],"huaqiaoyijijuzhuzaigangaotaidiqudezhongguogongminbae8233":[{"i":1,"n":"第一条","txt":"根据《中国公民收养子女登记办法》，制定本规定。"},{"i":2,"n":"第二条","txt":"华侨以及居住在香港、澳门、台湾地区的中国公民在内地收养子女的，应当到被收养人常住户口所在地的直辖市、设区的市、自治州人民政府民政部门或者地 区(盟)行政公署民政部门申请办理收养登记。"},{"i":3,"n":"第三条","txt":"居住在已与中国建立外交关系国家的华侨申请办理成立收养关系的登记时，应当提交收养申请书和下列证件、证明材料： (一)护照； (二)收养人居住国有权机构出具的收养人的年龄、婚姻、有无子女、职业、财产、健康、有无受过刑事处罚等状况的证明材料，该证明材料应当经其居住国外交机关或者外交机关授权 的机构认证，并经中国驻该国使领馆认证。"},{"i":4,"n":"第四条","txt":"居住在未与中国建立外交关系国家的华侨申请办理成立收养关系的登记时，应当提交收养申请书和下列证件、证明材料： (一)护照； (二)收养人居住国有权机构出具的收养人的年龄、婚姻、有无子女、职业、财产、健康、有无受过刑事处罚等状况的证明材料，该证明材料应当经其居住国外交机关或者外交机关授权 的机构认证，并经已与中国建立外交关系的国家驻该国使领馆认证。"},{"i":5,"n":"第五条","txt":"香港居民中的中国公民申请办理成立收养关系的登记时，应当提交收养申请书和下列证件、证明材料： (一)香港居民身份证、香港居民来往内地通行证或者香港同胞回乡证； (二)经国家主管机关委托的香港委托公证人证明的收养人的年龄、婚姻、有无子女、职业、财产、健康、有无受过刑事处罚等状况的证明材料。"},{"i":6,"n":"第六条","txt":"澳门居民中的中国公民申请办理成立收养关系的登记时，应当提交收养申请书和下列证件、证明材料： (一)澳门居民身份证、澳门居民来往内地通行证或者澳门同胞回乡证； (二)澳门地区有权机构出具的收养人的年龄、婚姻、有无子女、职业、财产、健康、有无受过刑事处罚等状况的证明材料。"},{"i":7,"n":"第七条","txt":"台湾居民申请办理成立收养关系的登记时，应当提交收养申请书和下列证件、证明材料： (一)在台湾地区居住的有效证明； (二)中华人民共和国主管机关签发或签注的在有效期内的旅行证件； (三)经台湾地区公证机构公证的收养人的年龄、婚姻、有无子女、职业、财产、健康、有无受过刑事处罚等状况的证明材料。"},{"i":8,"n":"第八条","txt":"本规定自发布之日起施行。"}],"qudifeifaminjianzuzhizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了维护社会稳定和国家安全，根据《社会团体登记管理条例》和《民办非企业单位登记管理暂行条例》及有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"具有下列情形之一的属于非法民间组织： (一)未经批准，擅自开展社会团体筹备活动的； (二)未经登记，擅自以社会团体或者民办非企业单位名义进行活动的； (三)被撤销登记后继续以社会团体或者民办非企业单位名义进行活动的。"},{"i":3,"n":"第三条","txt":"社会团体和民办非企业单位登记管理机关(以下统称登记管理机关)负责对非法民间组织进行调查，收集有关证据，依法作出取缔决定，没收其非法财产。"},{"i":4,"n":"第四条","txt":"取缔非法民间组织，由违法行为发生地的登记管理机关负责。 涉及两个以上同级登记管理机关的非法民间组织的取缔，由他们的共同上级登记管理机关负责，或者指定相关登记管理机关予以取缔。 对跨省(自治区、直辖市)活动的非法民间组织，由国务院民政部门负责取缔，或者指定相关登记管理机关予以取缔。"},{"i":5,"n":"第五条","txt":"对非法民间组织，登记管理机关一经发现，应当及时进行调查，涉及有关部门职能的，应当及时向有关部门通报。"},{"i":6,"n":"第六条","txt":"登记管理机关对非法民间组织进行调查时，执法人员不得少于两人，并应当出示证件。"},{"i":7,"n":"第七条","txt":"登记管理机关对非法民间组织进行调查时，有关单位和个人应当如实反映情况，提供有关资料，不得拒绝、隐瞒、出具伪证。"},{"i":8,"n":"第八条","txt":"登记管理机关依法调查非法民间组织时，对与案件有关的情况和资料，可以采取记录、复制、录音、录像、照相等手段取得证据。 在证据可能灭失或者以后难以取得的情况下，经登记管理机关负责人批准可以先行登记保存，并应当在七日内及时作出处理决定，在此期间，当事人或者有关人员不得销毁或者转移证据。"},{"i":9,"n":"第九条","txt":"对经调查认定的非法民间组织，登记管理机关应当依法作出取缔决定，宣布该组织为非法，并予以公告。"},{"i":10,"n":"第十条","txt":"非法民间组织被取缔后，登记管理机关依法没收的非法财物必须按照国家规定公开拍卖或者按照国家有关规定处理。 登记管理机关依法没收的违法所得和没收非法财物拍卖的款项，必须全部上缴国库。"},{"i":11,"n":"第十一条","txt":"对被取缔的非法民间组织，登记管理机关应当收缴其印章、标识、资料、财务凭证等，并登记造册。 需要销毁的印章、资料等，应当经登记管理机关负责人批准，由两名以上执法人员监督销毁，并填写销毁清单。"},{"i":12,"n":"第十二条","txt":"登记管理机关取缔非法民间组织后，应当按照档案管理的有关规定及时将有关档案材料立卷归档。"},{"i":13,"n":"第十三条","txt":"非法民间组织被取缔后，继续开展活动的，登记管理机关应当及时通报有关部门共同查处。"},{"i":14,"n":"第十四条","txt":"本办法自发布之日起施行。"}],"dimingguanlitiaolishishibanfa":[{"i":1,"n":"第一条","txt":"根据《地名管理条例》（以下简称条例），制定本办法。"},{"i":2,"n":"第二条","txt":"条例第八条规定的地名方案应当以地名命名为重点，统筹规划地名标志设置、地名文化保护等内容。 经依法批准的地名方案由县级以上地方人民政府地名行政主管部门会同有关部门组织实施，不得擅自变更；确需变更的，应当按照规定的程序重新报送批准。"},{"i":3,"n":"第三条","txt":"条例第九条第一款规定的人名应当包括： （一）本名以及其别名、化名等； （二）文艺作品中的人物角色名称。 但是地名命名所用的字、词与人名不存在特定联系的除外。"},{"i":4,"n":"第四条","txt":"不以企业名称或者商标名称作地名，但是地名命名所用的字、词与企业名称或者商标名称不存在特定联系的除外。"},{"i":5,"n":"第五条","txt":"条例第十一条第二款规定的综合评估报告应当包括地名命名、更名的合法性、可行性、可控性，可能产生的社会影响、风险以及应对措施等内容；专家论证报告应当包括地名命名、更名的必要性、科学性、合理性，可能存在的风险，对地名命名、更名方案以及组织实施的意见建议等内容；征求意见报告应当包括征求意见的过程和范围，主要意见建议及处理情况等内容。 地名命名、更名由地名批准机关在批准其他事项时一并批准的，相关事项申请材料应当包括条例第十一条规定的内容。"},{"i":6,"n":"第六条","txt":"地名命名、更名备案应当通过国家地名信息库填写备案登记表，并提交下列材料的电子文本： （一）备案报告； （二）地名命名、更名批复文件； （三）条例第十一条规定的申请书以及相关报告。"},{"i":7,"n":"第七条","txt":"县级以上人民政府地名行政主管部门收到备案材料后，应当对备案主体和备案材料进行审查。备案主体不符合规定的，应当指导地名批准机关重新报送；备案材料不齐全或者不符合规定的，应当指导地名批准机关补正。"},{"i":8,"n":"第八条","txt":"地名命名、更名后，县级以上人民政府地名行政主管部门应当按照条例第十四条规定向社会公告。 对于需要重新报送备案或者补正备案材料的，公告时限自收到重新报送备案或者补正备案材料之日起计算。"},{"i":9,"n":"第九条","txt":"地名命名、更名公告应当包括标准地名及其罗马字母拼写、所属政区、位置描述、批准机关、批准时间等内容。 地名命名、更名公告通过政府网站、政务新媒体以及报刊、广播、电视等途径发布，并在国家地名信息库发布。"},{"i":10,"n":"第十条","txt":"地名专名和通名的罗马字母拼写以《汉语拼音方案》作为统一规范。"},{"i":11,"n":"第十一条","txt":"一地多名的地名应当确定一个标准地名，一名多写、一字多音的地名应当确定统一的用字和读音。 地名中的异读音和特殊字应当按照地名的用字读音审定规范审定。地名的用字读音审定规范由国务院地名行政主管部门会同国务院语言文字工作部门制定。"},{"i":12,"n":"第十二条","txt":"少数民族语地名的汉字译名应当符合国务院有关部门制定的少数民族语地名汉字译写规范。"},{"i":13,"n":"第十三条","txt":"外国语地名的汉字译名应当符合国务院地名行政主管部门制定的外国语地名汉字译写规范，由国务院地名行政主管部门会同有关部门审定。 不得直接引用或者擅自转译可能损害我国领土主张和主权权益的外国语地名。"},{"i":14,"n":"第十四条","txt":"少数民族语地名、外国语地名的标准汉字译名的使用应当遵守标准地名使用的有关规定。 少数民族语地名、外国语地名的标准汉字译名通过地名公告、国家地名信息库、标准地名出版物等向社会公布。"},{"i":15,"n":"第十五条","txt":"国务院地名行政主管部门应当加强国家地名信息管理，制定统一的地名信息数据和系统建设规范，推进各地区、各部门间地名信息数据整合、共享和运用，提升地名公共服务水平。 县级以上人民政府地名行政主管部门和其他有关部门应当按照职责权限，及时对国家地名信息库地名信息数据进行更新和维护，确保地名信息数据的完整性、准确性、规范性和现势性。 县级以上地方人民政府地名行政主管部门已有的本级国家地名信息库，应当与国家级国家地名信息库互联互通，实现地名信息及时汇集公布。"},{"i":16,"n":"第十六条","txt":"县级以上地方人民政府地名行政主管部门应当建立健全地名信息资源共建共享机制，强化部门间信息共享和业务协同，依托国家地名信息库促进地名信息广泛应用。"},{"i":17,"n":"第十七条","txt":"县级以上人民政府地名行政主管部门应当会同有关部门依法加强地名信息数据采集、存储、传输、应用等管理，确保地名信息数据安全。"},{"i":18,"n":"第十八条","txt":"地名标志的设置应当布局合理、位置明显、安全可靠，标示的相关信息应当准确规范。"},{"i":19,"n":"第十九条","txt":"地名标志有下列情形之一的，地名标志设置、维护和管理部门应当及时进行更正、维护： （一）标示的标准地名或者其罗马字母拼写等信息错误的； （二）安装位置、指位错误的； （三）版面褪色、被涂改、遮挡，字迹模糊、残缺不全的； （四）破损、污损、存在安全隐患的； （五）其他应当予以更正、维护的情形。"},{"i":20,"n":"第二十条","txt":"条例第二十五条规定的地名保护名录应当包括地名文化遗产、历史地名以及其他类别，同一地名可以列入不同类别。 列入地名保护名录的地名信息应当包括标准地名以及罗马字母拼写，含义、来历、沿革，历史文化价值等内容。 地名保护名录应当及时向社会公布，并抄送上一级人民政府地名行政主管部门。"},{"i":21,"n":"第二十一条","txt":"县级以上地方人民政府地名行政主管部门可以采取设立标志、派生命名、活化使用、制作文化产品、开展宣传活动等方式，优先对列入地名保护名录的地名进行保护和合理利用。"},{"i":22,"n":"第二十二条","txt":"条例第二十九条第二款规定的地名管理能力包括制度体系、人才队伍、科技创新、工作条件等。"},{"i":23,"n":"第二十三条","txt":"有权受理备案的地名行政主管部门发现地名批准机关未按时报送备案的，应当进行督促。经督促仍不报送备案的，由国务院地名行政主管部门或者地名批准机关的上一级人民政府地名行政主管部门通知该地名批准机关，限期报送。 地名批准机关为其他有关部门的，有权受理备案的地名行政主管部门应当及时报告上一级人民政府地名行政主管部门。"},{"i":24,"n":"第二十四条","txt":"具有重要地理方位意义的住宅区、楼宇名称和交通运输、水利、电力、通信、气象等设施名称的范围，由有关主管部门结合实际根据职责权限确定。"},{"i":25,"n":"第二十五条","txt":"条例所称的具有重要地理方位意义，是指在一定区域范围内同类地理实体中指位作用相对突出，其名称可供社会公众使用。 条例第九条第一款所称的专名是指地名中为个体地理实体所专有的语词部分，通名是指地名中为同类地理实体所通用的语词部分。 条例第二十四条所称的地名文化遗产，是指具有历史文化价值、体现中华历史文脉并传承使用至今的地名及其相关的文化表现形式。 本办法第二十条所称的历史地名，是指曾经使用但目前已不再使用的地名。"},{"i":26,"n":"第二十六条","txt":"本办法自2024年5月1日起施行。1996年6月18日民政部发布、2010年12月27日民政部令第38号修订的《地名管理条例实施细则》同时废止。"}],"dimingguanlitiaolishishixize":[{"i":1,"n":"第一条","txt":"根据《地名管理条例》(以下简称《条例》)的规定，制定本实施细则。"},{"i":2,"n":"第二条","txt":"凡涉及地名的命名与更名、地名的标准化处理、标准地名的使用、地名标志的设置、地名档案的管理等行为，均适用本细则。"},{"i":3,"n":"第三条","txt":"《条例》所称自然地理实体名称，包括山、河、湖、海、岛礁、沙滩、岬角、海湾、水道、地形区等名称；行政区划名称，包括各级行政区域和各级人民政府派出机构所辖区域名称；居民地名称，包括城镇、区片、开发区、自然村、片村、农林牧渔点及街、巷、居民区、楼群(含楼、门号码)、建筑物等名称；各专业部门使用的具有地名意义的台、站、港、场等名称，还包括名胜古迹、纪念地、游览地等名称。"},{"i":4,"n":"第四条","txt":"地名管理的任务是：依据国家关于地名管理的方针、政策和法规，通过地名管理的各项行政职能和技术手段，逐步实现国家地名标准化和国内外地名译写规范化，为社会主义建设和国际交往服务。"},{"i":5,"n":"第五条","txt":"国家对地名实行统一管理、分级负责制。"},{"i":6,"n":"第六条","txt":"民政部是全国地名管理的主管部门。其职责是：指导和协调全国地名管理工作；制定全国地名工作规划；审核地名的命名和更名；审定并组织编纂全国性标准地名资料和工具图书；指导、监督标准地名的推广使用；管理地名标志和地名档案；对专业部门使用的地名实行监督和协调管理。"},{"i":7,"n":"第七条","txt":"县级以上民政管理部门(或地名委员会)主管本行政区域的地名工作。其职责是：贯彻执行国家关于地名工作的方针、政策、法律、法规；落实全国地名工作规划；审核、承办本辖区地名的命名、更名；推行地名的标准化、规范化；设置地名标志；管理地名档案；完成国家其他地名工作任务。"},{"i":8,"n":"第八条","txt":"地名的命名除应遵循《条例》第四条的规定外，还应遵循下列原则： (一)有利于国家统一、主权和领土完整。 (二)反映当地人文或自然地理特征。 (三)使用规范的汉字或少数民族文字。 (四)不以外国人名、地名命名我国地名。 (五)人民政府不驻在同一城镇的县级以上行政区域名称，其专名不应相同。一个县(市、区)内的乡、镇、街道办事处名称，一个乡、镇内自然村名称，一个城镇内的街、巷、居民区名称，不应重名；国内著名的自然地理实体名称不应重名；一个省、自治区、直辖市行政区域内，较重要的自然地理实体名称不应重名；上述不应重名范围内的地名避免使用同音字。 (六)不以著名的山脉、河流等自然地理实体名称作行政区域专名；自然地理实体的范围超出本行政区域的，亦不以其名称作本行政区域专名。 (七)县、市、市辖区不以本辖区内人民政府非驻地村镇专名命名。 (八)乡、镇、街道办事处一般应以乡、镇人民政府驻地居民点和街道办事"},{"i":9,"n":"第九条","txt":"地名的更名除应遵循《条例》第五条的规定外，凡不符合本细则第八条(四)、(五)、(七)、(八)项规定的地名，原则上也应予以更名。需要更改的地名，应随着城乡发展的需要，逐步进行调整。"},{"i":10,"n":"第十条","txt":"地名命名、更名的审批权限按照《地名管理条例》第六条(一)至(七)项规定办理。"},{"i":11,"n":"第十一条","txt":"申报地名的命名、更名时，应将命名、更名的理由及拟废止的旧名、拟采用的新名的含义、来源等一并加以说明。"},{"i":12,"n":"第十二条","txt":"地名的命名、更名由地名管理部门负责承办。行政区划名称的命名、更名，由民政部门承办。 专业部门使用的具有地名意义的名称，其命名、更名由该专业部门负责承办，但应事先征得当地地名管理部门的同意。"},{"i":13,"n":"第十三条","txt":"凡符合《地名管理条例》规定，并经县级以上人民政府或专业主管部门批准的地名为标准地名。"},{"i":14,"n":"第十四条","txt":"标准地名原则上由专名和通名两部分组成。通名用字应反映所称地理实体的地理属性(类别)。不单独使用通名词组作地名。具体技术要求，以民政部制定的技术规范为准。"},{"i":15,"n":"第十五条","txt":"汉语地名中的方言俗字，一般用字音(或字义)相同或相近的通用字代替。对原有地名中带有一定区域性或特殊含义的通名俗字，经国家语言文字工作委员会审音定字后，可以保留。"},{"i":16,"n":"第十六条","txt":"少数民族自治地方及民族乡名称，一般由地域专名、民族全称(包括“族”字)和相应自治区域通名组成。由多个少数民族组成的民族自治地方名称，少数民族的称谓至多列举三个。"},{"i":17,"n":"第十七条","txt":"少数民族语地名的译写 (一)少数民族语地名，在各自民族语言、文字的基础上，按其标准(通用)语音，依据汉语普通话读音进行汉字译写。对约定俗成的汉字译名，一般不更改。 (二)多民族聚居区的地名，如不同民族有不同的称谓并无惯用汉语名称时，经当地地名管理部门征得有关少数民族的意见后，选择当地使用范围较广的某一语种称谓进行汉字译写。 (三)少数民族语地名的汉字译写，应尽可能采用常用字，避免使用多音、贬义和容易产生歧义的字词。 (四)有文字的少数民族语地名之间的相互译写，以本民族和他民族规范化的语言文字为依据，或者以汉语拼音字母拼写的地名为依据。 (五)少数民族语地名译写的具体技术要求，以民政部商同国务院有关部门制定的或经民政部审定的有关规范为依据。"},{"i":18,"n":"第十八条","txt":"国外地名的汉字译写 (一)国外地名的汉字译写，除少数惯用译名外，以该国官方语言文字和标准音为依据；有两种以上官方语言文字的国家，以该地名所属语区的语言文字为依据。国际公共领域的地理实体名称的汉字译写，以联合国有关组织或国际有关组织颁布的标准名称为依据。 (二)国外地名的汉字译写，以汉语普通话读音为准，不用方言读音。尽量避免使用多音字、生僻字、贬义字。 (三)国外地名专名实行音译，通名一般实行意译。 (四)对国外地名原有的汉译惯用名采取“约定俗成”的原则予以保留。 (五)国外地名译写的具体技术要求，以国家地名管理部门制定的外国地名译名规范为依据。国外地名的译名以国家地名管理部门编纂或审定的地名译名手册中的地名为标准化译名。"},{"i":19,"n":"第十九条","txt":"中国地名的罗马字母拼写 (一)《汉语拼音方案》是使用罗马字母拼写中国地名的统一规范。它不仅适用于汉语和国内其他少数民族语，同时也适用于英语、法语、德语、西班牙语、世界语等罗马字母书写的各种语文。 (二)汉语地名按《中国地名汉语拼音字母拼写规则(汉语地名部分)》拼写。 (三)少数民族的族称按国家技术监督局制定的《中国各民族名称的罗马字母拼写法和代码》的规定拼写。 (四)蒙、维、藏语地名以及惯用蒙、维、藏语文书写的少数民族语地名，按《少数民族语地名汉语拼音字母音译转写法》拼写。 (五)其他少数民族语地名，原则上以汉译名称按《中国地名汉语拼音字母拼写规则(汉语地名部分)》拼写。 (六)台湾省和香港、澳门地区的地名，依据国家有关规定进行拼写。 (七)地名罗马字母拼写具体规范由民政部商同国务院有关部门负责修订。"},{"i":20,"n":"第二十条","txt":"各级地名管理部门和专业主管部门，应当将批准的标准地名及时向社会公布，推广使用。"},{"i":21,"n":"第二十一条","txt":"各级地名管理部门和专业主管部门，负责编纂本行政区域或本系统的各种标准化地名出版物，及时向社会提供法定地名。其他部门不得编纂标准化地名工具图书。"},{"i":22,"n":"第二十二条","txt":"机关、部队、团体、企业、事业单位的公告、文件、证件、影视、商标、广告、牌匾、地图以及出版物等方面所使用的地名，均应以正式公布的标准地名(包括规范化译名)为准，不得擅自更改。"},{"i":23,"n":"第二十三条","txt":"对尚未公布规范汉字译写的外国地名，地名使用单位应根据国家地名管理部门制定的译名规则进行汉字译写。"},{"i":24,"n":"第二十四条","txt":"行政区域界位、城镇街巷、居民区、楼、院、自然村屯、主要道路和桥梁、纪念地、文物古迹、风景名胜、台、站、港、场和重要自然地理实体等地方应当设置地名标志。一定区域内的同类地名标志应当力求统一。"},{"i":25,"n":"第二十五条","txt":"地名标志的主要内容包括：标准地名汉字的规范书写形式； 标准地名汉语拼音字母的规范拼写形式。在习惯于用本民族文字书写地名的民族自治区域， 可依据民族区域自治法有关文字书写规定，并列该民族文字规范书写形式。"},{"i":26,"n":"第二十六条","txt":"地名标志的设置和管理，由当地地名管理部门负责。其中街、巷、楼、门牌统一由地名主管部门管理，条件尚不成熟的地方，地名主管部门应积极取得有关部门的配合，共同做好标志的管理工作，逐步实现统一管理。专业部门使用的具有地名意义的名称标志，由地名管理部门协调有关专业部门设置和管理。"},{"i":27,"n":"第二十七条","txt":"地名标志的设置和管理所需费用，当地人民政府根据具体情况，可由财政拨款，也可采取受益单位出资或工程预算费列支等方式筹措。"},{"i":28,"n":"第二十八条","txt":"全国地名档案工作由民政部统一指导，各级地名档案管理部门分级管理。地名档案工作在业务上接受档案管理部门的指导、监督。"},{"i":29,"n":"第二十九条","txt":"各级地名档案管理部门保管的地名档案资料，应不少于本级人民政府审批权限规定的地名数量。"},{"i":30,"n":"第三十条","txt":"地名档案的管理规范，应执行民政部和国家档案局制定的有关规定。"},{"i":31,"n":"第三十一条","txt":"各级地名档案管理部门，要在遵守国家保密规定原则下，积极开展地名信息咨询服务。"},{"i":32,"n":"第三十二条","txt":"各级地名管理部门应当加强地名工作的管理、监督和检查。对擅自命名、更名或使用不规范地名的单位和个人，由地名主管部门按照国家有关规定处理。"},{"i":33,"n":"第三十三条","txt":"地名标志为国家法定的标志物。对损坏地名标志的，地名管理部门应责令其赔偿；对偷窃、故意损毁或擅自移动地名标志的，地名管理部门报请有关部门，依据《中华人民共和国治安管理处罚法》的规定予以处罚；情节恶劣、后果严重构成犯罪的的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"当地人民政府对推广使用标准地名和保护地名标志作出贡献的单位和个人，应当给予表彰或奖励。"},{"i":35,"n":"第三十五条","txt":"各省、自治区、直辖市人民政府可根据本细则，制定本行政区域的地名管理办法。"},{"i":36,"n":"第三十六条","txt":"本细则由民政部负责解释。"},{"i":37,"n":"第三十七条","txt":"本细则自发布之日起施行。"}],"chengshishenghuowuzhuodeliulangqitaorenyuanjiuzhug8f44d6":[{"i":1,"n":"第一条","txt":"根据《城市生活无着的流浪乞讨人员救助管理办法》（以下简称《救助管理办法》）的规定，制定本实施细则。"},{"i":2,"n":"第二条","txt":"《救助管理办法》规定的“城市生活无着的流浪乞讨人员”是指因自身无力解决食宿，无亲友投靠，又不享受城市最低生活保障或者农村五保供养，正在城市流浪乞讨度日的人员。 虽有流浪乞讨行为，但不具备前款规定情形的，不属于救助对象。"},{"i":3,"n":"第三条","txt":"流浪乞讨人员向救助站求助时，应当如实提供本人的下列情况： （一）姓名、年龄、性别、居民身份证或者能够证明身份的其他证件、本人户口所在地、住所地； （二）是否享受城市最低生活保障或者农村五保供养; （三）流浪乞讨的原因、时间、经过; （四）近亲属和其他关系密切亲戚的姓名、住址、联系方式； （五）随身物品的情况。"},{"i":4,"n":"第四条","txt":"救助站应当向求助的流浪乞讨人员告知救助对象的范围和实施救助的内容，询问与求助需求有关的情况，并对其个人情况予以登记。"},{"i":5,"n":"第五条","txt":"救助站对属于救助对象的，应当及时安排救助；不属于救助对象的，不予救助并告知其理由。 对因年老、年幼、残疾等原因无法提供个人情况的，救助站应当先提供救助，再查明情况。 对拒不如实提供个人情况的，不予救助。"},{"i":6,"n":"第六条","txt":"受助人员不得携带危险物品进入救助站，随身携带的物品，除生活必需品外，由救助站保管，待该受助人员离站时归还。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市人民政府民政部门应当制定救助站受助人员的作息、卫生、学习等制度。受助人员应当遵守救助站的规章制度。"},{"i":8,"n":"第八条","txt":"救助站为受助人员提供的食物和住处，应当能够满足受助人员的基本健康和安全需要。受助人员食宿定额定量的标准，由省级人民政府民政部门商财政部门具体规定。"},{"i":9,"n":"第九条","txt":"受助人员在站内突发急病的，救助站应当及时送医疗机构治疗。救助站发现受助人员在站内患传染病或者为疑似传染病病人的，救助站应当送当地具有传染病收治条件的医疗机构治疗，并向当地疾病预防控制机构报告，采取必要的消毒隔离措施。"},{"i":10,"n":"第十条","txt":"救助站应当根据受助人员提供的有关情况，及时与受助人员的家属以及受助人员常住户口所在地或者住所地的乡（镇）人民政府、城市街道办事处、该地的公安、民政部门取得联系，核实情况。 救助站发现受助人员故意提供虚假个人情况的，应当终止救助。"},{"i":11,"n":"第十一条","txt":"受助人员返回常住户口所在地、住所地或者所在单位时没有交通费的，由救助站发给乘车（船）凭证，铁道、公路、水运等运输单位验证后准予搭乘相应的公共交通工具。救助站应当将有关情况通知受助人员的亲属及前往地的有关组织、所在单位。"},{"i":12,"n":"第十二条","txt":"救助站应当根据受助人员的情况确定救助期限，一般不超过10天；因特殊情况需要延长的，报上级民政主管部门备案。"},{"i":13,"n":"第十三条","txt":"对受助人员中的残疾人、未成年人或者其他行动不便的人，救助站应当通知其亲属或者所在单位接回；亲属或者所在单位拒不接回的，省内的由流入地人民政府民政部门通知流出地人民政府民政部门接回，送其亲属或者所在单位；跨省的由流入地省级人民政府民政部门通知流出地省级人民政府民政部门接回，送其亲属或者所在单位。"},{"i":14,"n":"第十四条","txt":"对无法查明其亲属或者所在单位，但可以查明其户口所在地、住所地的受助残疾人、未成年人及其他行动不便的人，省内的由流入地人民政府民政部门通知流出地人民政府民政部门接回，送户口所在地、住所地安置；跨省的由流入地省级人民政府民政部门通知流出地省级人民政府民政部门接回，送户口所在地、住所地安置。"},{"i":15,"n":"第十五条","txt":"对因年老、年幼或者残疾无法认知自己行为、无表达能力，因而无法查明其亲属或者所在单位，也无法查明其户口所在地或者住所地的，由救助站上级民政主管部门提出安置方案，报同级人民政府给予安置。"},{"i":16,"n":"第十六条","txt":"受助人员自愿放弃救助离开救助站的，应当事先告知，救助站不得限制。未成年人及其他无民事行为能力人和限制民事行为能力人离开救助站，须经救助站同意。 受助人员擅自离开救助站的，视同放弃救助，救助站应当终止救助。"},{"i":17,"n":"第十七条","txt":"救助站已经实施救助或者救助期满，受助人员应当离开救助站。对无正当理由不愿离站的受助人员，救助站应当终止救助。"},{"i":18,"n":"第十八条","txt":"受助人员户口所在地、住所地的乡级、县级人民政府应当帮助返回的受助人员解决生产、生活困难，避免其再次外出流浪乞讨；对遗弃残疾人、未成年人、老年人的近亲属或者其他监护人，责令其履行抚养、赡养义务；对确实无家可归的残疾人、未成年人、老年人应当给予安置。"},{"i":19,"n":"第十九条","txt":"受助人员在救助站期间应当遵纪守法，不得辱骂、殴打救助站工作人员或者其他受助人员，不得破坏救助设施，不得毁坏、盗窃公私财物，不得无理取闹、扰乱救助工作秩序。 对受助人员的违法行为，救助站工作人员应当及时制止；受助人员违规违纪情节严重的，或者发现受助人员有犯罪嫌疑的，应当及时报请公安机关依法处理。"},{"i":20,"n":"第二十条","txt":"救助站应当建立健全岗位责任制、安全责任制、工作人员行为规范等规章制度，实行规范化管理。 救助站应当将受助人员入站、离站、获得救助等情况如实记载，制作档案妥善保管。"},{"i":21,"n":"第二十一条","txt":"救助站及其工作人员应当严格遵守《救助管理办法》第十条、第十四条第二款规定。对违反规定的，由该救助站的上级民政主管部门责令改正；情节较重的，对直接负责的主管人员和其他直接责任人给予纪律处分；构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"县级以上地方人民政府民政部门应当加强对救助站的领导和监督管理，履行以下职责： （一）监督救助站落实救助措施和规章制度； （二）指导检查救助工作情况; （三）对救助站工作人员进行教育、培训; （四）调查、处理救助站及其工作人员违法违纪问题； （五）帮助救助站解决困难，提供工作条件。"},{"i":23,"n":"第二十三条","txt":"救助站的上级民政主管部门不及时受理救助对象举报，不及时责令救助站履行职责，或者对应当安置的受助人员不报请当地人民政府予以安置的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。"},{"i":24,"n":"第二十四条","txt":"本实施细则自2003年8月1日起施行。"}],"chengshishequdanganguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为规范城市社区档案（以下简称社区档案）管理，根据《中华人民共和国档案法》《中华人民共和国城市居民委员会组织法》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称社区档案，是指城市社区党组织、居民委员会、社区服务机构、社区社会组织（以下简称社区各类组织）和居民在社区建设中形成的具有保存价值的各种文字、图表、声像、电子数据等不同形式和载体的历史记录。"},{"i":3,"n":"第三条","txt":"社区档案工作在业务上接受街道办事处（乡镇人民政府）以及档案行政管理部门和民政部门的监督和指导。"},{"i":4,"n":"第四条","txt":"社区党组织和居民委员会应当重视档案工作，加强组织领导，将档案工作纳入社区建设内容，促进档案工作与社区其他各项工作同步协调发展。"},{"i":5,"n":"第五条","txt":"社区档案工作经费从社区的办公经费中列支，并应当满足实际工作的需要。"},{"i":6,"n":"第六条","txt":"社区党组织或者居民委员会应当配备专门人员管理本社区各类档案,有条件的地方可以设立综合档案室。 档案管理人员应当经过档案专业知识培训，调离工作岗位时应当在离职前办理档案交接手续。"},{"i":7,"n":"第七条","txt":"社区综合档案室或者档案管理人员负责宣传、贯彻和执行党和国家有关档案工作的法律法规和标准规范，指导、监督本社区文件材料的归档、整理和移交工作。"},{"i":8,"n":"第八条","txt":"社区档案由社区综合档案室或者档案管理人员集中统一管理，任何单位和个人不得据为己有或者擅自销毁。"},{"i":9,"n":"第九条","txt":"社区建设中形成的文件材料可以分为文书类、科技类、会计类等三个大类，具体的归档范围和保管期限参照本办法附件。"},{"i":10,"n":"第十条","txt":"社区文件材料的归档，应当符合以下要求： （一）归档的文件材料应当齐全、完整、排列有序；装订结实、整齐；备考表填写真实、清楚；归档文件目录或者卷内文件目录明晰、准确； （二）归档的文件材料中有照片或者复印件的，应当图文清晰； （三）归档时间： 文书材料于次年6月底前归档； 科技文件材料在科技活动结束后1个月内归档； 会计材料由会计部门在会计年度终了后保管1年，于次年3月底前归档； 声像材料在活动结束或者办理完毕后随时归档； 实物材料及时归档； 电子文件按照《电子文件归档与管理规范》（GB/T18894）和《电子文件归档光盘技术要求和应用规范》(DA/T38)的要求整理。"},{"i":11,"n":"第十一条","txt":"社区档案按照下列规则进行分类编号： （一）文书档案按照年度——问题（社区党建、居民自治、社区管理、社区服务、社区治安等）进行分类，参照《归档文件整理规则》，以件为单位，按年度——问题——保管期限排列编号； （二）科技档案中的基建档案按照工程项目分类整理，按照项目——时间排列编号；设备仪器档案按照型号分类整理，按照型号——时间排列编号； （三）会计档案按照年度——类别（报表、账簿、凭证、其他）分类整理并排列编号；"},{"i":12,"n":"第十二条","txt":"社区综合档案室或者档案管理人员应当设立专室或者专柜保管档案，采取有效的防火、防盗、防高温、防潮、防光、防尘、防鼠、防虫、防磁等措施，确保档案的完整与安全。"},{"i":13,"n":"第十三条","txt":"档案管理人员应当定期对档案及其保管状况进行全面检查，并形成安全检查记录；如有破损、霉变、虫蛀、褪色等现象时，应当及时修补、复制或者进行其他技术处理。 对声像档案和电子档案，要定期检查信息记录的安全性，确保档案可读可用；有条件的地方要及时对声像档案进行数字化转化，以利于长期使用。"},{"i":14,"n":"第十四条","txt":"社区综合档案室或者档案管理人员应当建立档案统计制度，对档案的收进和移出、保管数量、借阅和利用效果、销毁等情况，进行及时、准确的统计。"},{"i":15,"n":"第十五条","txt":"社区综合档案室或者档案管理人员应当建立健全档案利用制度，为档案利用创造条件，简化手续，提供方便。 利用档案时应当按照规定办理手续，并及时做好利用效果登记。 档案管理人员应当认真检查归还档案，如发现有短缺、涂改、污损情况，要及时报告并追查。"},{"i":16,"n":"第十六条","txt":"社区应当组织成立档案鉴定工作小组，对已到期档案及时进行鉴定。 鉴定工作小组由社区档案管理人员和形成档案的组织的人员（或者居民代表）组成，鉴定后应当形成档案鉴定报告。对失去保存价值的档案，应当清点核对并编制档案销毁清册，经过必要的审批手续后按照规定销毁。 禁止擅自销毁档案。档案销毁清册应当永久保存。"},{"i":17,"n":"第十七条","txt":"社区档案应当依法保持齐全完整，不得随意将社区档案拆散、重新组合。"},{"i":18,"n":"第十八条","txt":"社区综合档案室或者档案管理人员应当围绕社区中心工作和居民利用需求，加强档案信息资源的开发利用，积极开展档案编研工作。"},{"i":19,"n":"第十九条","txt":"社区档案管理应当积极采用计算机等先进技术，逐步实现档案管理的信息化、现代化。"},{"i":20,"n":"第二十条","txt":"涉及国家秘密、商业秘密和个人隐私等内容的档案的保管、利用，应当按照国家有关法律法规规定办理。"},{"i":21,"n":"第二十一条","txt":"违反国家有关规定，对档案有损毁、丢失以及出卖、涂改、伪造、泄密等情况的，应当依法追究相关人员责任。构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"各省（自治区、直辖市）、新疆生产建设兵团档案行政管理部门商同级民政部门，可以结合当地实际情况制定本办法的实施细则。"},{"i":23,"n":"第二十三条","txt":"本办法由国家档案局和民政部负责解释。"},{"i":24,"n":"第二十四条","txt":"本办法自2016年1月1日起实施。 附件："}],"jijinhuixinxigongbubanfa":[{"i":1,"n":"第一条","txt":"为了规范基金会、境外基金会代表机构信息公布活动，保护捐赠人及相关当事人的合法权益，促进公益事业发展，根据《基金会管理条例》（以下简称《条例》）的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称信息公布，是指基金会、境外基金会代表机构按照《条例》和本办法的规定，将其内部信息和业务活动信息通过媒体向社会公布的活动。 基金会、境外基金会代表机构是信息公布义务人。"},{"i":3,"n":"第三条","txt":"信息公布义务人公布的信息资料应当真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。 信息公布义务人应当保证捐赠人和社会公众能够快捷、方便地查阅或者复制公布的信息资料。"},{"i":4,"n":"第四条","txt":"信息公布义务人应当向社会公布的信息包括： （一）基金会、境外基金会代表机构的年度工作报告； （二）公募基金会组织募捐活动的信息； （三）基金会开展公益资助项目的信息。 基金会、境外基金会代表机构在遵守本办法规定的基础上可以自行决定公布更多的信息。"},{"i":5,"n":"第五条","txt":"信息公布义务人应当在每年3月31日前，向登记管理机关报送上一年度的年度工作报告。登记管理机关审查通过后30日内，信息公布义务人按照统一的格式要求，在登记管理机关指定的媒体上公布年度工作报告的全文和摘要。 信息公布义务人的财务会计报告未经审计不得对外公布。"},{"i":6,"n":"第六条","txt":"公募基金会组织募捐活动，应当公布募得资金后拟开展的公益活动和资金的详细使用计划。在募捐活动持续期间内，应当及时公布募捐活动所取得的收入和用于开展公益活动的成本支出情况。募捐活动结束后，应当公布募捐活动取得的总收入及其使用情况。"},{"i":7,"n":"第七条","txt":"基金会开展公益资助项目，应当公布所开展的公益项目种类以及申请、评审程序。评审结束后，应当公布评审结果并通知申请人。公益资助项目完成后，应当公布有关的资金使用情况。事后对项目进行评估的，应当同时公布评估结果。"},{"i":8,"n":"第八条","txt":"对于公共媒体上出现的对信息公布义务人造成或者可能造成不利影响的消息，信息公布义务人应当公开说明或者澄清。"},{"i":9,"n":"第九条","txt":"除年度工作报告外，信息公布义务人公布信息时，可以选择报刊、广播、电视或者互联网作为公布信息的媒体。"},{"i":10,"n":"第十条","txt":"信息公布所使用的媒体应当能够覆盖信息公布义务人的活动地域。公布的信息内容中应当注明信息公布义务人的基本情况和联系、咨询方式。"},{"i":11,"n":"第十一条","txt":"信息公布义务人应当建立健全信息公布活动的内部管理制度，并指定专人负责处理信息公布活动的有关事务。对于已经公布的信息，应当制作信息公布档案，妥善保管。"},{"i":12,"n":"第十二条","txt":"信息公布义务人公布有关活动或者项目的信息，应当持续至活动结束或者项目完成。 信息一经公布，信息公布义务人不得任意修改，确需修改的，应当严格履行内部管理制度的程序在修改后重新公布，并说明理由，声明原信息作废。"},{"i":13,"n":"第十三条","txt":"信息公布义务人应当将信息公布活动的情况如实反映在年度工作报告中，接受登记管理机关监督检查。"},{"i":14,"n":"第十四条","txt":"登记管理机关依法对信息公布活动进行监督管理，建立信息公布义务人诚信记录。 信息公布义务人不履行信息公布义务或者公布虚假信息的，由登记管理机关责令改正，并依据《条例》第四十二条规定给予行政处罚。"},{"i":15,"n":"第十五条","txt":"年度工作报告的信息公布格式文本，由国务院民政部门制定。"},{"i":16,"n":"第十六条","txt":"本办法自公布之日起施行。"}],"jijinhuimingchengguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范对基金会名称的管理，保护基金会的合法权益，根据《基金会管理条例》及有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于按照《基金会管理条例》设立的基金会。"},{"i":3,"n":"第三条","txt":"基金会名称应当反映公益活动的业务范围。 基金会的名称应当依次包括字号、公益活动的业务范围，并以“基金会”字样结束。 公募基金会的名称可以不使用字号。"},{"i":4,"n":"第四条","txt":"全国性公募基金会应当在名称中使用“中国”、“中华”、“全国”、“国家”等字样。非公募基金会不得使用上述字样。 地方性公募基金会和省、自治区、直辖市人民政府民政部 门登记的非公募基金会应当冠以所在地的县级或县级以上行政区划名称。冠以省级以下行政区划名称的，可以同时冠以所在省、自治区、直辖市的名称。冠以市辖区名称的，应当同时冠以市的名称。"},{"i":5,"n":"第五条","txt":"基金会的字号应当由2个以上的字组成。 基金会不得使用姓氏、县或县以上行政区划名称作为字号。"},{"i":6,"n":"第六条","txt":"公募基金会的字号不得使用自然人姓名、法人或者其他组织的名称或者字号。"},{"i":7,"n":"第七条","txt":"非公募基金会的字号可以使用自然人姓名、法人或其他组织的名称或者字号，但应当符合以下规定： (一)使用自然人姓名、法人或者其他组织的名称或者字号，需经该自然人、法人或其他组织同意； (二)不得使用曾因犯罪被判处剥夺政治权利的自然人的姓名； (三)一般不使用党和国家领导人、老一辈革命家的姓名。"},{"i":8,"n":"第八条","txt":"基金会使用已故名人的姓名作为字号，该名人必须是在相关公益领域内有重大贡献、在国际国内享有盛誉的杰出人物。"},{"i":9,"n":"第九条","txt":"基金会名称应当使用符合国家规范的汉字。 在自治区人民政府民政部门登记的基金会，其名称可以同时使用本民族自治地方通用的民族文字。 基金会名称需译成外文使用的，应当按照文字翻译的原则翻译使用，不需报登记管理机关核准。"},{"i":10,"n":"第十条","txt":"基金会名称不得含有下列内容和文字： (一)有损于国家、社会公共利益的； (二)可能对公众造成欺骗或者引起公众误解的； (三)有迷信色彩的； (四)外国国家(地区)名称、国际组织名称； (五)政党名称、国家机关名称及部队番号； (六)其他基金会的名称； (七)外国文字、汉语拼音字母、数字； (八)其他法律、行政法规规定禁止的。"},{"i":11,"n":"第十一条","txt":"基金会不得使用下列名称： (一)已被登记管理机关撤销登记，自撤销登记之日起未满3年的基金会的名称； (二)已注销登记，自注销登记之日起未满3年的基金会的名称； (三)已变更名称，自变更登记之日起未满1年的基金会的原名称。"},{"i":12,"n":"第十二条","txt":"登记管理机关可以纠正已登记的不适宜的基金会名称。"},{"i":13,"n":"第十三条","txt":"2个及2个以上申请人向同一登记管理机关申请登记相同的基金会名称，登记管理机关依照申请在先原则核定。"},{"i":14,"n":"第十四条","txt":"基金会的分支机构、代表机构的名称应当冠以其所从属的基金会名称。"},{"i":15,"n":"第十五条","txt":"境外基金会代表机构的名称应当依次由“基金会名称”、“驻在地名称”、“代表处(或办事处、联络处等)”组成。 “驻在地名称”是指境外基金会代表机构驻在地的县或县以上行政区划名称。 境外基金会名称中未表明其原始登记地(国家或地区)的，应在其代表机构名称前冠以原始登记地(国家或地区)的名称。"},{"i":16,"n":"第十六条","txt":"本规定自2004年6月7日起施行。"}],"jijinhuiniandujianchabanfa":[{"i":1,"n":"第一条","txt":"为加强对基金会和境外基金会代表机构的管理，促进公益事业发展，根据《基金会管理条例》（以下简称《条例》）第三十四条第一项、第三十六条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"基金会年度检查，是指基金会登记管理机关依法按年度对基金会、境外基金会代表机构遵守法律、法规、规章和章程开展活动的情况实施监督管理的制度。"},{"i":3,"n":"第三条","txt":"基金会、境外基金会代表机构应当于每年3月31日前向登记管理机关报送经业务主管单位审查同意的上一年度的年度工作报告，接受登记管理机关检查。"},{"i":4,"n":"第四条","txt":"年度工作报告的内容应当包括：财务会计报告、注册会计师审计报告，开展募捐、接受捐赠、提供资助等活动的情况以及人员和机构的变动情况等。 财务会计报告应当符合《民间非营利组织会计制度》规定的内容和要求；注册会计师审计报告，应当有注册会计师事务所统一受理并与被审计的基金会、境外基金会代表机构签订委托合同的证明；开展募捐、接受捐赠、提供资助等活动情况应当有基金会履行信息公布义务的情况；人员和机构变动情况应当有按照规定办理变更登记情况以及基金会换届的会议纪要和更换法定代表人之前进行财务审计的情况等。"},{"i":5,"n":"第五条","txt":"年度检查过程中，登记管理机关可以要求基金会、境外基金会代表机构或者有关人员就年度工作报告中涉及的有关问题进行补充说明，必要时可以进行实地检查。"},{"i":6,"n":"第六条","txt":"经登记管理机关审查，基金会、境外基金会代表机构在上一年度遵守法律、法规、规章和章程的情况良好，没有违法违规情形的，认定为年检合格。"},{"i":7,"n":"第七条","txt":"基金会、境外基金会代表机构有下列情形之一的，登记管理机关应当视情节轻重分别作出年检基本合格、年检不合格的结论： （一）违反《条例》第三十九条第二款规定，不按照捐赠协议使用捐赠财产的； （二）违反《条例》第四十条规定，擅自设立基金会分支机构、代表机构的； （三）具有《条例》第四十二条规定的应当给予行政处罚的情形之一的； （四）违反《条例》第四十三条第二款规定，基金会理事、监事及专职工作人员私分、侵占、挪用基金会财产的； （五）违反《条例》关于基金会组织机构管理方面有关规定的。 登记管理机关作出基本合格或者不合格年检结论后，应当责令该基金会或者境外基金会代表机构限期整改，并视情况依据《条例》有关规定给予行政处罚。"},{"i":8,"n":"第八条","txt":"年度检查不合格的基金会、境外基金会代表机构在整改期间，登记管理机关不准予变更名称或者业务范围，不准予设立分支机构或者代表机构。登记管理机关应当提请税务机关责令补交违法行为存续期间所享受的税收减免。"},{"i":9,"n":"第九条","txt":"通过年度检查发现基金会、基金会分支机构、基金会代表机构或者境外基金会代表机构有《条例》第四十一条规定的情形之一的，登记管理机关应当依法撤销登记。"},{"i":10,"n":"第十条","txt":"基金会、境外基金会代表机构无正当理由不参加年检的，由登记管理机关责令停止活动，并向社会公告。"},{"i":11,"n":"第十一条","txt":"基金会、境外基金会代表机构连续两年不接受年检的，由登记管理机关依法撤销登记。"},{"i":12,"n":"第十二条","txt":"完成年度检查后，登记管理机关应当向社会公告年度检查结果，并向业务主管单位通报。 基金会、境外基金会代表机构应当在通过登记管理机关的年度检查后，将年度工作报告在登记管理机关指定的媒体上公布，接受社会公众的查询、监督。"},{"i":13,"n":"第十三条","txt":"年度工作报告的格式文本由国务院民政部门制定。"},{"i":14,"n":"第十四条","txt":"本办法自公布之日起施行。"}],"hunyindengjidanganguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范婚姻登记档案管理，维护婚姻当事人的合法权益，根据《中华人民共和国档案法》和《婚姻登记条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"婚姻登记档案是婚姻登记机关在办理结婚登记、撤销婚姻、离婚登记、补发婚姻登记证的过程中形成的具有凭证作用的各种记录。"},{"i":3,"n":"第三条","txt":"婚姻登记主管部门对婚姻登记档案工作实行统一领导，分级管理，并接受同级地方档案行政管理部门的监督和指导。"},{"i":4,"n":"第四条","txt":"婚姻登记机关应当履行下列档案工作职责： （一）及时将办理完毕的婚姻登记材料收集、整理、归档； （二）建立健全各项规章制度，确保婚姻登记档案的齐全完整； （三）采用科学的管理方法，提高婚姻登记档案的保管水平； （四）办理查档服务，出具婚姻登记记录证明，告知婚姻登记档案的存放地； （五）办理婚姻登记档案的移交工作。"},{"i":5,"n":"第五条","txt":"办理结婚登记（含复婚、补办结婚登记，下同）形成的下列材料应当归档： （一）《结婚登记审查处理表》； （二）《申请结婚登记声明书》或者《申请补办结婚登记声明书》； （三）香港特别行政区居民、澳门特别行政区居民、台湾地区居民、出国人员、华侨以及外国人提交的《婚姻登记条例》第五条规定的各种证明材料（含翻译材料）； （四）当事人身份证件（从《婚姻登记条例》第五条规定，下同）复印件； （五）其他有关材料。"},{"i":6,"n":"第六条","txt":"办理撤销婚姻形成的下列材料应当归档： （一）婚姻登记机关关于撤销婚姻的决定； （二）《撤销婚姻申请书》； （三）当事人的结婚证原件； （四）公安机关出具的当事人被拐卖、解救证明，或人民法院作出的能够证明当事人被胁迫结婚的判决书； （五）当事人身份证件复印件； （六）其他有关材料。"},{"i":7,"n":"第七条","txt":"办理离婚登记形成的下列材料应当归档： （一）《离婚登记审查处理表》； （二）《申请离婚登记声明书》； （三）当事人结婚证复印件； （四）当事人离婚协议书； （五）当事人身份证件复印件； （六）其他有关材料。"},{"i":8,"n":"第八条","txt":"办理补发婚姻登记证形成的下列材料应当归档： （一）《补发婚姻登记证审查处理表》； （二）《申请补领婚姻登记证声明书》； （三）婚姻登记档案保管部门出具的婚姻登记档案记录证明或其他有关婚姻状况的证明； （四）当事人身份证件复印件； （五）当事人委托办理时提交的经公证机关公证的当事人身份证件复印件和委托书，受委托人本人的身份证件复印件； （六）其他有关材料。"},{"i":9,"n":"第九条","txt":"婚姻登记档案按照年度—婚姻登记性质分类。婚姻登记性质分为结婚登记类、撤销婚姻类、离婚登记类和补发婚姻登记证类四类。 人民法院宣告婚姻无效或者撤销婚姻的判决书副本归入撤销婚姻类档案。 婚姻无效或者撤销婚姻的，应当在当事人原婚姻登记档案的《结婚登记审查处理表》的“备注”栏中注明有关情况及相应的撤销婚姻类档案的档号。"},{"i":10,"n":"第十条","txt":"婚姻登记材料的立卷归档应当遵循下列原则与方法： （一）婚姻登记材料按照年度归档。 （二）一对当事人婚姻登记材料组成一卷。 （三）卷内材料分别按照本办法第五、六、七、八条规定的顺序排列。 （四）以有利于档案保管和利用的方法固定案卷。 （五）按本办法第九条的规定对案卷进行分类，并按照办理婚姻登记的时间顺序排列。 （六）在卷内文件首页上端的空白处加盖归档章（见附件1），并填写有关内容。归档章设置全宗号、年度、室编卷号、馆编卷号和页数等项目。 全宗号：档案馆给立档单位编制的代号。 年度：案卷的所属年度。 室编卷号：案卷排列的顺序号，每年每个类别分别从“1”开始标注。 馆编卷号：档案移交时按进馆要求编制。 页数：卷内材料有文字的页面数。 （七）按室编卷号的顺序将婚姻登记档案装入档案盒，并填写档案盒封面、盒脊和备考表的项目。 档案盒封面应标明全宗名称和婚姻登记处名称（见附件2）。 档案盒盒脊设置全"},{"i":11,"n":"第十一条","txt":"婚姻登记材料的归档要求： （一）当年的婚姻登记材料应当在次年的 3月31日前 完成立卷归档； （二）归档的婚姻登记材料必须齐全完整，案卷规范、整齐，复印件一律使用A4规格的复印纸，复印件和照片应当图像清晰； （三）归档章、档案盒封面、盒脊、备考表等项目，使用蓝黑墨水或碳素墨水钢笔填写；婚姻登记档案目录应当打印；备考表和档案目录一律使用A4规格纸张。"},{"i":12,"n":"第十二条","txt":"使用计算机办理婚姻登记所形成的电子文件，应当与纸质文件一并归档，归档要求参照《电子文件归档与管理规范》（GB/T18894-2002）。"},{"i":13,"n":"第十三条","txt":"婚姻登记档案的保管期限为100年。对有继续保存价值的可以延长保管期限直至永久。"},{"i":14,"n":"第十四条","txt":"婚姻登记档案应当按照下列规定进行移交： （一）县级（含）以上地方人民政府民政部门形成的婚姻登记档案，应当在本单位档案部门保管一定时期后向同级国家档案馆移交，具体移交时间由双方商定。 （二）具有办理婚姻登记职能的乡（镇）人民政府形成的婚姻登记档案应当向乡（镇）档案部门移交，具体移交时间从乡（镇）的规定。 乡（镇）人民政府应当将每年的婚姻登记档案目录副本向上一级人民政府民政部门报送。 （三） 被撤销或者合并的婚姻登记机关的婚姻登记档案应当按照前两款的规定及时移交。"},{"i":15,"n":"第十五条","txt":"婚姻登记档案的利用应当遵守下列规定： （一）婚姻登记档案保管部门应当建立档案利用制度，明确办理程序，维护当事人的合法权益； （二）婚姻登记机关可以利用本机关移交的婚姻登记档案； （三）婚姻当事人持有合法身份证件，可以查阅本人的婚姻登记档案；婚姻当事人因故不能亲自前往查阅的，可以办理授权委托书，委托他人代为办理，委托书应当经公证机关公证； （四）人民法院、人民检察院、公安和安全部门为确认当事人的婚姻关系，持单位介绍信可以查阅婚姻登记档案；律师及其他诉讼代理人在诉讼过程中，持受理案件的法院出具的证明材料及本人有效证件可以查阅与诉讼有关的婚姻登记档案； （五）其他单位、组织和个人要求查阅婚姻登记档案的，婚姻登记档案保管部门在确认其利用目的合理的情况下，经主管领导审核，可以利用； （六）利用婚姻登记档案的单位、组织和个人，不得公开婚姻登记档案的内容，不得损害婚姻登记当事人的合法权益； （七）婚"},{"i":16,"n":"第十六条","txt":"婚姻登记档案的鉴定销毁应当符合下列要求： （一）婚姻登记档案保管部门对保管期限到期的档案要进行价值鉴定，对无保存价值的予以销毁，但婚姻登记档案目录应当永久保存。 （二）对销毁的婚姻登记档案应当建立销毁清册，载明销毁档案的时间、种类和数量，并永久保存。 （三）婚姻登记档案保管部门应当派人监督婚姻登记档案的销毁过程，确保销毁档案没有漏销或者流失，并在销毁清册上签字。"},{"i":17,"n":"第十七条","txt":"本办法由民政部负责解释。"},{"i":18,"n":"第十八条","txt":"本办法自公布之日起施行。"}],"jiatingjiyangguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范家庭寄养工作，促进寄养儿童身心健康成长，根据《中华人民共和国未成年人保护法》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称家庭寄养，是指经过规定的程序，将民政部门监护的儿童委托在符合条件的家庭中养育的照料模式。"},{"i":3,"n":"第三条","txt":"家庭寄养应当有利于寄养儿童的抚育、成长，保障寄养儿童的合法权益不受侵犯。"},{"i":4,"n":"第四条","txt":"国务院民政部门负责全国家庭寄养监督管理工作。 县级以上地方人民政府民政部门负责本行政区域内家庭寄养监督管理工作。"},{"i":5,"n":"第五条","txt":"县级以上地方人民政府民政部门设立的儿童福利机构负责家庭寄养工作的组织实施。"},{"i":6,"n":"第六条","txt":"县级以上人民政府民政部门应当会同有关部门采取措施，鼓励、支持符合条件的家庭参与家庭寄养工作。"},{"i":7,"n":"第七条","txt":"未满十八周岁、监护权在县级以上地方人民政府民政部门的孤儿、查找不到生父母的弃婴和儿童，可以被寄养。 需要长期依靠医疗康复、特殊教育等专业技术照料的重度残疾儿童，不宜安排家庭寄养。"},{"i":8,"n":"第八条","txt":"寄养家庭应当同时具备下列条件： （一）有儿童福利机构所在地的常住户口和固定住所。寄养儿童入住后，人均居住面积不低于当地人均居住水平； （二）有稳定的经济收入，家庭成员人均收入在当地处于中等水平以上； （三）家庭成员未患有传染病或者精神疾病，以及其他不利于寄养儿童抚育、成长的疾病； （四）家庭成员无犯罪记录，无不良生活嗜好，关系和睦，与邻里关系融洽； （五）主要照料人的年龄在三十周岁以上六十五周岁以下，身体健康，具有照料儿童的能力、经验，初中以上文化程度。 具有社会工作、医疗康复、心理健康、文化教育等专业知识的家庭和自愿无偿奉献爱心的家庭，同等条件下优先考虑。"},{"i":9,"n":"第九条","txt":"每个寄养家庭寄养儿童的人数不得超过二人，且该家庭无未满六周岁的儿童。"},{"i":10,"n":"第十条","txt":"寄养残疾儿童，应当优先在具备医疗、特殊教育、康复训练条件的社区中为其选择寄养家庭。"},{"i":11,"n":"第十一条","txt":"寄养年满十周岁以上儿童的，应当征得寄养儿童的同意。"},{"i":12,"n":"第十二条","txt":"确立家庭寄养关系，应当经过以下程序： （一）申请。拟开展寄养的家庭应当向儿童福利机构提出书面申请，并提供户口簿、身份证复印件，家庭经济收入和住房情况、家庭成员健康状况以及一致同意申请等证明材料； （二）评估。儿童福利机构应当组织专业人员或者委托社会工作服务机构等第三方专业机构对提出申请的家庭进行实地调查，核实申请家庭是否具备寄养条件和抚育能力，了解其邻里关系、社会交往、有无犯罪记录、社区环境等情况，并根据调查结果提出评估意见； （三）审核。儿童福利机构应当根据评估意见对申请家庭进行审核，确定后报主管民政部门备案； （四）培训。儿童福利机构应当对寄养家庭主要照料人进行培训； （五）签约。儿童福利机构应当与寄养家庭主要照料人签订寄养协议，明确寄养期限、寄养双方的权利义务、寄养家庭的主要照料人、寄养融合期限、违约责任及处理等事项。家庭寄养协议自双方签字（盖章）之日起生效。"},{"i":13,"n":"第十三条","txt":"寄养家庭应当履行下列义务： （一）保障寄养儿童人身安全，尊重寄养儿童人格尊严； （二）为寄养儿童提供生活照料，满足日常营养需要，帮助其提高生活自理能力； （三）培养寄养儿童健康的心理素质，树立良好的思想道德观念； （四）按照国家规定安排寄养儿童接受学龄前教育和义务教育。负责与学校沟通，配合学校做好寄养儿童的学校教育； （五）对患病的寄养儿童及时安排医治。寄养儿童发生急症、重症等情况时，应当及时进行医治，并向儿童福利机构报告； （六）配合儿童福利机构为寄养的残疾儿童提供辅助矫治、肢体功能康复训练、聋儿语言康复训练等方面的服务； （七）配合儿童福利机构做好寄养儿童的送养工作； （八）定期向儿童福利机构反映寄养儿童的成长状况，并接受其探访、培训、监督和指导； （九）及时向儿童福利机构报告家庭住所变更情况； （十）保障寄养儿童应予保障的其他权益。"},{"i":14,"n":"第十四条","txt":"儿童福利机构主要承担以下职责： （一）制定家庭寄养工作计划并组织实施； （二）负责寄养家庭的招募、调查、审核和签约； （三）培训寄养家庭中的主要照料人，组织寄养工作经验交流活动； （四）定期探访寄养儿童，及时处理存在的问题； （五）监督、评估寄养家庭的养育工作； （六）建立家庭寄养服务档案并妥善保管； （七）根据协议规定发放寄养儿童所需款物； （八）向主管民政部门及时反映家庭寄养工作情况并提出建议。"},{"i":15,"n":"第十五条","txt":"寄养协议约定的主要照料人不得随意变更。确需变更的，应当经儿童福利机构同意，经培训后在家庭寄养协议主要照料人一栏中变更。"},{"i":16,"n":"第十六条","txt":"寄养融合期的时间不得少于六十日。"},{"i":17,"n":"第十七条","txt":"寄养家庭有协议约定的事由在短期内不能照料寄养儿童的，儿童福利机构应当为寄养儿童提供短期养育服务。短期养育服务时间一般不超过三十日。"},{"i":18,"n":"第十八条","txt":"寄养儿童在寄养期间不办理户口迁移手续，不改变与民政部门的监护关系。"},{"i":19,"n":"第十九条","txt":"寄养家庭提出解除寄养关系的，应当提前一个月向儿童福利机构书面提出解除寄养关系的申请，儿童福利机构应当予以解除。但在融合期内提出解除寄养关系的除外。"},{"i":20,"n":"第二十条","txt":"寄养家庭有下列情形之一的，儿童福利机构应当解除寄养关系： （一）寄养家庭及其成员有歧视、虐待寄养儿童行为的； （二）寄养家庭成员的健康、品行不符合本办法第八条第（三）和（四）项规定的； （三）寄养家庭发生重大变故，导致无法履行寄养义务的； （四）寄养家庭变更住所后不符合本办法第八条规定的； （五）寄养家庭借机对外募款敛财的； （六）寄养家庭不履行协议约定的其他情形。"},{"i":21,"n":"第二十一条","txt":"寄养儿童有下列情形之一的，儿童福利机构应当解除寄养关系： （一）寄养儿童与寄养家庭关系恶化，确实无法共同生活的； （二）寄养儿童依法被收养、被亲生父母或者其他监护人认领的； （三）寄养儿童因就医、就学等特殊原因需要解除寄养关系的。"},{"i":22,"n":"第二十二条","txt":"解除家庭寄养关系，儿童福利机构应当以书面形式通知寄养家庭，并报其主管民政部门备案。家庭寄养关系的解除以儿童福利机构批准时间为准。"},{"i":23,"n":"第二十三条","txt":"儿童福利机构拟送养寄养儿童时，应当在报送被送养人材料的同时通知寄养家庭。"},{"i":24,"n":"第二十四条","txt":"家庭寄养关系解除后，儿童福利机构应当妥善安置寄养儿童，并安排社会工作、医疗康复、心理健康教育等专业技术人员对其进行辅导、照料。"},{"i":25,"n":"第二十五条","txt":"符合收养条件、有收养意愿的寄养家庭，可以依法优先收养被寄养儿童。"},{"i":26,"n":"第二十六条","txt":"县级以上地方人民政府民政部门对家庭寄养工作负有以下监督管理职责： （一）制定本地区家庭寄养工作政策； （二）指导、检查本地区家庭寄养工作； （三）负责寄养协议的备案，监督寄养协议的履行； （四）协调解决儿童福利机构与寄养家庭之间的争议； （五）与有关部门协商，及时处理家庭寄养工作中存在的问题。"},{"i":27,"n":"第二十七条","txt":"开展跨县级或者设区的市级行政区域的家庭寄养，应当经过共同上一级人民政府民政部门同意。 不得跨省、自治区、直辖市开展家庭寄养。"},{"i":28,"n":"第二十八条","txt":"儿童福利机构应当聘用具有社会工作、医疗康复、心理健康教育等专业知识的专职工作人员。"},{"i":29,"n":"第二十九条","txt":"家庭寄养经费，包括寄养儿童的养育费用补贴、寄养家庭的劳务补贴和寄养工作经费等。 寄养儿童养育费用补贴按照国家有关规定列支。寄养家庭劳务补贴、寄养工作经费等由当地人民政府予以保障。"},{"i":30,"n":"第三十条","txt":"家庭寄养经费必须专款专用，儿童福利机构不得截留或者挪用。"},{"i":31,"n":"第三十一条","txt":"儿童福利机构可以依法通过与社会组织合作、通过接受社会捐赠获得资助。 与境外社会组织或者个人开展同家庭寄养有关的合作项目，应当按照有关规定办理手续。"},{"i":32,"n":"第三十二条","txt":"寄养家庭不履行本办法规定的义务，或者未经同意变更主要照料人的，儿童福利机构可以督促其改正，情节严重的，可以解除寄养协议。 寄养家庭成员侵害寄养儿童的合法权益，造成人身财产损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"儿童福利机构有下列情形之一的，由设立该机构的民政部门进行批评教育，并责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）不按照本办法的规定承担职责的； （二）在办理家庭寄养工作中牟取利益，损害寄养儿童权益的； （三）玩忽职守导致寄养协议不能正常履行的； （四）跨省、自治区、直辖市开展家庭寄养，或者未经上级部门同意擅自开展跨县级或者设区的市级行政区域家庭寄养的； （五）未按照有关规定办理手续，擅自与境外社会组织或者个人开展家庭寄养合作项目的。"},{"i":34,"n":"第三十四条","txt":"县级以上地方人民政府民政部门不履行家庭寄养工作职责，由上一级人民政府民政部门责令其改正。情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":35,"n":"第三十五条","txt":"对流浪乞讨等生活无着未成年人承担临时监护责任的未成年人救助保护机构开展家庭寄养，参照本办法执行。"},{"i":36,"n":"第三十六条","txt":"尚未设立儿童福利机构的，由县级以上地方人民政府民政部门负责本行政区域内家庭寄养的组织实施，具体工作参照本办法执行。"},{"i":37,"n":"第三十七条","txt":"本办法自2014年12月1日起施行，2003年颁布的《家庭寄养管理暂行办法》（民发〔2003〕144号）同时废止。"}],"shitichurujingheshitichulideguanliguiding-3":[{"i":1,"n":"第一条","txt":"为保护社会公共利益，维护社会公共道德，防止传染病由境外传入或者由境内传出，根据《中华人民共和国国境卫生检疫法》、《中华人民共和国海关法》和《殡葬管理条例》等有关法律法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称尸体，是指人去世后的遗体及其标本（含人体器官组织、人体骨骼及其标本）。"},{"i":3,"n":"第三条","txt":"需要入境或者出境对遗体进行殡葬的，应当按照民政部、公安部、外交部、铁道部、交通部、卫生部、海关总署、民用航空局《关于尸体运输管理的若干规定》（民事发〔1993〕2号）和民政部、海关总署、国家出入境检验检疫局《关于遗体运输入出境事宜有关问题的通知》（民事发〔1998〕11号）以及国家其他有关规定，向民政部门、海关、出入境检验检疫机构办理有关殡葬和出入境手续。"},{"i":4,"n":"第四条","txt":"因医学科研需要，由境内运出或者由境外运进尸体，应当按照国务院办公厅转发的《人类遗传资源管理暂行办法》和卫生部、质检总局《关于加强医用特殊物品出入境卫生检疫管理的通知》（卫科教发〔2003〕230号）的规定，办理相关审批手续。"},{"i":5,"n":"第五条","txt":"除第三条、第四条规定情形外，尸体不得由境内运出或者由境外运进。"},{"i":6,"n":"第六条","txt":"对属于殡葬遗体出入境的，出入境检验检疫机构应当对申报资料进行认真核查，并对承运物进行卫生监管，合格者签发《尸体／棺柩／骸骨／骨灰入／出境许可证》。对因医学科研原因出入境的尸体，出入境检验检疫机构凭中国人类遗传资源管理办公室核发的《人类遗传资源材料出口、出境证明》或者卫生部和省、自治区、直辖市卫生行政部门出具的《医用特殊物品准出入境证明》，按照规定实施卫生检疫审批，并依法实施卫生检疫查验和卫生处理；对符合条件的，签发《出入境货物通关单》。"},{"i":7,"n":"第七条","txt":"申请办理尸体出入境的单位和个人应主动、如实地向海关申报进出口尸体的相关情况，包括尸体来源等，并提交有关进出口证件。对属于殡葬遗体出入境的，海关凭出入境检验检疫机构签发的《尸体／棺柩／骸骨／骨灰入／出境许可证》办理验放手续。对属医学科研原因出入境的，海关凭出入境检验检疫机构签发的《出入境货物通关单》办理验放手续；对涉及我国人类遗传资源的出境尸体，海关加验中国人类遗传资源管理办公室核发的《人类遗传资源材料出口、出境证明》。对经海关查验可能为尸体的，无论是否列入《出入境检验检疫机构实施检验检疫的进出境商品目录》，海关一律验凭出入境检验检疫机构签发的《出入境货物通关单》或者《尸体／棺柩／骸骨／骨灰入／出境许可证》放行。"},{"i":8,"n":"第八条","txt":"严禁进行尸体买卖，严禁利用尸体进行商业性活动。"},{"i":9,"n":"第九条","txt":"除医疗机构、医学院校、医学科研机构以及法医鉴定科研机构因临床、医学教学和科研需要外，任何单位和个人不得接受尸体捐赠。前款规定情况下使用完毕的尸体，由接受尸体的单位负责对尸体进行殡葬意义上的最终处理。"},{"i":10,"n":"第十条","txt":"违反上述规定的，由有关主管部门按照相关规定查处；构成犯罪的，依法追究刑事责任。"},{"i":11,"n":"第十一条","txt":"本规定由各部门按照各自职责进行解释。"},{"i":12,"n":"第十二条","txt":"本规定自2006年8月1日起施行。"}],"gongshangbaoxianfuzhuqijupeizhiguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了规范工伤保险辅助器具配置管理，维护工伤职工的合法权益，根据《工伤保险条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"工伤职工因日常生活或者就业需要，经劳动能力鉴定委员会确认，配置假肢、矫形器、假眼、假牙和轮椅等辅助器具的，适用本办法。"},{"i":3,"n":"第三条","txt":"人力资源社会保障行政部门负责工伤保险辅助器具配置的监督管理工作。民政、卫生计生等行政部门在各自职责范围内负责工伤保险辅助器具配置的有关监督管理工作。 社会保险经办机构（以下称经办机构）负责对申请承担工伤保险辅助器具配置服务的辅助器具装配机构和医疗机构（以下称工伤保险辅助器具配置机构）进行协议管理，并按照规定核付配置费用。"},{"i":4,"n":"第四条","txt":"设区的市级（含直辖市的市辖区、县）劳动能力鉴定委员会（以下称劳动能力鉴定委员会）负责工伤保险辅助器具配置的确认工作。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市人力资源社会保障行政部门负责制定工伤保险辅助器具配置机构评估确定办法。 经办机构按照评估确定办法，与工伤保险辅助器具配置机构签订服务协议，并向社会公布签订服务协议的工伤保险辅助器具配置机构（以下称协议机构）名单。"},{"i":6,"n":"第六条","txt":"人力资源社会保障部根据社会经济发展水平、工伤职工日常生活和就业需要等，组织制定国家工伤保险辅助器具配置目录，确定配置项目、适用范围、最低使用年限等内容，并适时调整。 省、自治区、直辖市人力资源社会保障行政部门可以结合本地区实际，在国家目录确定的配置项目基础上，制定省级工伤保险辅助器具配置目录，适当增加辅助器具配置项目，并确定本地区辅助器具配置最高支付限额等具体标准。"},{"i":7,"n":"第七条","txt":"工伤职工认为需要配置辅助器具的，可以向劳动能力鉴定委员会提出辅助器具配置确认申请，并提交下列材料： （一）《工伤认定决定书》原件和复印件，或者其他确认工伤的文件； （二）居民身份证或者社会保障卡等有效身份证明原件和复印件； （三）有效的诊断证明、按照医疗机构病历管理有关规定复印或者复制的检查、检验报告等完整病历材料。 工伤职工本人因身体等原因无法提出申请的，可由其近亲属或者用人单位代为申请。"},{"i":8,"n":"第八条","txt":"劳动能力鉴定委员会收到辅助器具配置确认申请后，应当及时审核；材料不完整的，应当自收到申请之日起5个工作日内一次性书面告知申请人需要补正的全部材料；材料完整的，应当在收到申请之日起60日内作出确认结论。伤情复杂、涉及医疗卫生专业较多的，作出确认结论的期限可以延长30日。"},{"i":9,"n":"第九条","txt":"劳动能力鉴定委员会专家库应当配备辅助器具配置专家，从事辅助器具配置确认工作。 劳动能力鉴定委员会应当根据配置确认申请材料，从专家库中随机抽取3名或者5名专家组成专家组，对工伤职工本人进行现场配置确认。专家组中至少包括1名辅助器具配置专家、2名与工伤职工伤情相关的专家。"},{"i":10,"n":"第十条","txt":"专家组根据工伤职工伤情，依据工伤保险辅助器具配置目录有关规定，提出是否予以配置的确认意见。专家意见不一致时，按照少数服从多数的原则确定专家组的意见。 劳动能力鉴定委员会根据专家组确认意见作出配置辅助器具确认结论。其中，确认予以配置的，应当载明确认配置的理由、依据和辅助器具名称等信息；确认不予配置的，应当说明不予配置的理由。"},{"i":11,"n":"第十一条","txt":"劳动能力鉴定委员会应当自作出确认结论之日起20日内将确认结论送达工伤职工及其用人单位，并抄送经办机构。"},{"i":12,"n":"第十二条","txt":"工伤职工收到予以配置的确认结论后，及时向经办机构进行登记，经办机构向工伤职工出具配置费用核付通知单，并告知下列事项： （一）工伤职工应当到协议机构进行配置； （二）确认配置的辅助器具最高支付限额和最低使用年限； （三）工伤职工配置辅助器具超目录或者超出限额部分的费用，工伤保险基金不予支付。"},{"i":13,"n":"第十三条","txt":"工伤职工可以持配置费用核付通知单，选择协议机构配置辅助器具。 协议机构应当根据与经办机构签订的服务协议，为工伤职工提供配置服务，并如实记录工伤职工信息、配置器具产品信息、最高支付限额、最低使用年限以及实际配置费用等配置服务事项。 前款规定的配置服务记录经工伤职工签字后，分别由工伤职工和协议机构留存。"},{"i":14,"n":"第十四条","txt":"协议机构或者工伤职工与经办机构结算配置费用时，应当出具配置服务记录。经办机构核查后，应当按照工伤保险辅助器具配置目录有关规定及时支付费用。"},{"i":15,"n":"第十五条","txt":"工伤职工配置辅助器具的费用包括安装、维修、训练等费用，按照规定由工伤保险基金支付。 经经办机构同意，工伤职工到统筹地区以外的协议机构配置辅助器具发生的交通、食宿费用，可以按照统筹地区人力资源社会保障行政部门的规定，由工伤保险基金支付。"},{"i":16,"n":"第十六条","txt":"辅助器具达到规定的最低使用年限的，工伤职工可以按照统筹地区人力资源社会保障行政部门的规定申请更换。 工伤职工因伤情发生变化，需要更换主要部件或者配置新的辅助器具的，经向劳动能力鉴定委员会重新提出确认申请并经确认后，由工伤保险基金支付配置费用。"},{"i":17,"n":"第十七条","txt":"辅助器具配置专家应当具备下列条件之一： （一）具有医疗卫生中高级专业技术职务任职资格； （二）具有假肢师或者矫形器师职业资格； （三）从事辅助器具配置专业技术工作5年以上。 辅助器具配置专家应当具有良好的职业品德。"},{"i":18,"n":"第十八条","txt":"工伤保险辅助器具配置机构的具体条件，由省、自治区、直辖市人力资源社会保障行政部门会同民政、卫生计生行政部门规定。"},{"i":19,"n":"第十九条","txt":"经办机构与工伤保险辅助器具配置机构签订的服务协议，应当包括下列内容： （一）经办机构与协议机构名称、法定代表人或者主要负责人等基本信息； （二）服务协议期限； （三）配置服务内容； （四）配置费用结算； （五）配置管理要求； （六）违约责任及争议处理； （七）法律、法规规定应当纳入服务协议的其他事项。"},{"i":20,"n":"第二十条","txt":"配置的辅助器具应当符合相关国家标准或者行业标准。统一规格的产品或者材料等辅助器具在装配前应当由国家授权的产品质量检测机构出具质量检测报告，标注生产厂家、产品品牌、型号、材料、功能、出品日期、使用期和保修期等事项。"},{"i":21,"n":"第二十一条","txt":"协议机构应当建立工伤职工配置服务档案，并至少保存至服务期限结束之日起两年。经办机构可以对配置服务档案进行抽查，并作为结算配置费用的依据之一。"},{"i":22,"n":"第二十二条","txt":"经办机构应当建立辅助器具配置工作回访制度，对辅助器具装配的质量和服务进行跟踪检查，并将检查结果作为对协议机构的评价依据。"},{"i":23,"n":"第二十三条","txt":"工伤保险辅助器具配置机构违反国家规定的辅助器具配置管理服务标准，侵害工伤职工合法权益的，由民政、卫生计生行政部门在各自监管职责范围内依法处理。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，经办机构不予支付配置费用： （一）未经劳动能力鉴定委员会确认，自行配置辅助器具的； （二）在非协议机构配置辅助器具的； （三）配置辅助器具超目录或者超出限额部分的； （四）违反规定更换辅助器具的。"},{"i":25,"n":"第二十五条","txt":"工伤职工或者其近亲属认为经办机构未依法支付辅助器具配置费用，或者协议机构认为经办机构未履行有关协议的，可以依法申请行政复议或者提起行政诉讼。"},{"i":26,"n":"第二十六条","txt":"经办机构在协议机构管理和核付配置费用过程中收受当事人财物的，由人力资源社会保障行政部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"从事工伤保险辅助器具配置确认工作的组织或者个人有下列情形之一的，由人力资源社会保障行政部门责令改正，处2000元以上1万元以下的罚款；情节严重，构成犯罪的，依法追究刑事责任： （一）提供虚假确认意见的； （二）提供虚假诊断证明或者病历的； （三）收受当事人财物的。"},{"i":28,"n":"第二十八条","txt":"协议机构不按照服务协议提供服务的，经办机构可以解除服务协议，并按照服务协议追究相应责任。 经办机构不按时足额结算配置费用的，由人力资源社会保障行政部门责令改正；协议机构可以解除服务协议。"},{"i":29,"n":"第二十九条","txt":"用人单位、工伤职工或者其近亲属骗取工伤保险待遇，辅助器具装配机构、医疗机构骗取工伤保险基金支出的，按照《工伤保险条例》第六十条的规定，由人力资源社会保障行政部门责令退还，处骗取金额2倍以上5倍以下的罚款；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"用人单位未依法参加工伤保险，工伤职工需要配置辅助器具的，按照本办法的相关规定执行，并由用人单位支付配置费用。"},{"i":31,"n":"第三十一条","txt":"本办法自2016年4 月1 日起施行。"}],"caipiaoguanlitiaolishishixize":[{"i":1,"n":"第一条","txt":"根据《彩票管理条例》（以下简称条例），制定本细则。"},{"i":2,"n":"第二条","txt":"条例第二条所称特定规则，是指经财政部批准的彩票游戏规则。 条例第二条所称凭证，是指证明彩票销售与购买关系成立的专门凭据，应当记载彩票游戏名称，购买数量和金额，数字、符号或者图案，开奖和兑奖等相关信息。"},{"i":3,"n":"第三条","txt":"财政部负责全国的彩票监督管理工作，主要职责是： （一）制定彩票监督管理制度和政策； （二）监督管理全国彩票市场以及彩票的发行和销售活动，监督彩票资金的解缴和使用； （三）会同民政部、国家体育总局等有关部门提出彩票公益金分配政策建议； （四）审批彩票品种的开设、停止和有关审批事项的变更； （五）会同民政部、国家体育总局制定彩票设备和技术服务标准； （六）审批彩票发行机构财务收支计划，监督彩票发行机构财务管理活动； （七）审批彩票发行机构的彩票销毁方案。"},{"i":4,"n":"第四条","txt":"民政部、国家体育总局按照各自的职责分别负责全国的福利彩票、体育彩票管理工作，主要职责是： （一）制定全国福利彩票、体育彩票事业的发展规划和管理制度； （二）设立福利彩票、体育彩票发行机构； （三）制定民政部门、体育行政部门彩票公益金使用管理办法，指导地方民政部门、体育行政部门彩票公益金的使用和管理； （四）审核福利彩票、体育彩票品种的开设、停止和有关审批事项的变更； （五）监督福利彩票、体育彩票发行机构的彩票销毁工作； （六）制定福利彩票、体育彩票的代销合同示范文本。"},{"i":5,"n":"第五条","txt":"省级财政部门负责本行政区域的彩票监督管理工作，主要职责是： （一）制定本行政区域的彩票监督管理具体实施办法； （二）监督管理本行政区域彩票市场以及彩票的销售活动，监督本行政区域彩票资金的解缴和使用； （三）会同省级民政部门、体育行政部门制定本行政区域的彩票公益金管理办法； （四）审批彩票销售机构财务收支计划，监督彩票销售机构财务管理活动。"},{"i":6,"n":"第六条","txt":"省级民政部门、体育行政部门按照各自的职责分别负责本行政区域的福利彩票、体育彩票管理工作，主要职责是： （一）设立本行政区域的福利彩票、体育彩票销售机构； （二）批准建立本行政区域福利彩票、体育彩票的销售网络； （三）制定本行政区域民政部门、体育行政部门彩票公益金使用管理办法，指导省以下民政部门、体育行政部门彩票公益金的使用和管理； （四）监督本行政区域彩票代销者的代销行为。"},{"i":7,"n":"第七条","txt":"条例第五条所称非法彩票，是指违反条例规定以任何方式发行、销售以下形式的彩票： （一）未经国务院特许，擅自发行、销售福利彩票、体育彩票之外的其他彩票； （二）在中华人民共和国境内，擅自发行、销售的境外彩票； （三）未经财政部批准，擅自发行、销售的福利彩票、体育彩票品种和彩票游戏； （四）未经彩票发行机构、彩票销售机构委托，擅自销售的福利彩票、体育彩票。 （五）擅自利用互联网销售的福利彩票、体育彩票。 县级以上财政部门、民政部门、体育行政部门，以及彩票发行机构、彩票销售机构，应当积极配合公安机关和市场监督管理部门依法查处非法彩票，维护彩票市场秩序。"},{"i":8,"n":"第八条","txt":"福利彩票发行机构、体育彩票发行机构，按照统一发行、统一管理、统一标准的原则，分别负责全国的福利彩票、体育彩票发行和组织销售工作，主要职责是： （一）制定全国福利彩票、体育彩票发行销售的发展规划、管理制度、工作规范和技术标准等； （二）建立全国福利彩票、体育彩票的发行销售系统、市场调控机制、激励约束机制和监督管理机制； （三）组织彩票品种的研发，申请开设、停止彩票品种或者变更彩票品种审批事项，经批准后组织实施； （四）负责组织管理全国福利彩票、体育彩票的销售系统数据、资金归集结算、设备和技术服务、销售渠道和场所规划、印制和物流、开奖兑奖、彩票销毁； （五）负责组织管理全国福利彩票、体育彩票的形象建设、彩票代销、营销宣传、业务培训、人才队伍建设等工作。"},{"i":9,"n":"第九条","txt":"福利彩票销售机构、体育彩票销售机构，在福利彩票发行机构、体育彩票发行机构的统一组织下，分别负责本行政区域的福利彩票、体育彩票销售工作，主要职责是： （一）制定本行政区域福利彩票、体育彩票销售管理办法和工作规范； （二）向彩票发行机构提出停止彩票品种或者变更彩票品种审批事项的建议； （三）制定本行政区域彩票销售实施方案，并组织实施； （四）负责本行政区域福利彩票、体育彩票销售系统的建设、运营和维护； （五）负责实施本行政区域福利彩票、体育彩票的销售系统数据管理、资金归集结算、销售渠道和场所规划、物流管理、开奖兑奖； （六）负责组织实施本行政区域福利彩票、体育彩票的形象建设、彩票代销、营销宣传、业务培训、人才队伍建设等工作。"},{"i":10,"n":"第十条","txt":"各省、自治区、直辖市福利彩票、体育彩票的销售网络，由福利彩票销售机构、体育彩票销售机构提出方案，分别报省级民政部门、体育行政部门批准后建立。"},{"i":11,"n":"第十一条","txt":"条例第七条所称彩票品种，是指按照彩票游戏机理和特征划分的彩票类型，包括乐透型、数字型、竞猜型、传统型、即开型、视频型、基诺型等。 条例第七条所称开设，是指在已发行销售的彩票品种之外，增加新的品种。 条例第七条所称变更，是指在已发行销售的彩票品种之内，对彩票游戏规则、发行方式、发行范围等事项进行调整。"},{"i":12,"n":"第十二条","txt":"彩票发行机构拟开设彩票品种或者拟变更彩票品种涉及对技术方案进行重大调整的，可以根据需要委托专业检测机构进行技术检测。"},{"i":13,"n":"第十三条","txt":"对彩票发行机构申请开设彩票品种的审查，按照以下程序办理： （一）彩票发行机构将拟开设彩票品种的申请材料报民政部或者国家体育总局进行审核； （二）民政部或者国家体育总局审核同意后，彩票发行机构向财政部提交申请材料； （三）财政部自收到申请材料之日起10个工作日之内，对申请材料进行初步审核，并出具受理或者不予受理意见书； （四）受理申请后，财政部通过专家评审、听证会等方式听取社会意见； （五）财政部自受理申请之日起90个工作日内，根据条例、有关彩票管理的制度规定以及社会意见作出书面决定。"},{"i":14,"n":"第十四条","txt":"彩票发行机构申请变更彩票品种审批事项的，应当向财政部提交下列申请材料： （一）申请书； （二）拟变更彩票品种审批事项的具体内容，包括对彩票游戏规则、发行方式、发行范围等的具体调整方案； （三）对变更彩票品种审批事项的市场分析报告； （四）财政部要求报送的其他材料。"},{"i":15,"n":"第十五条","txt":"对彩票发行机构申请变更彩票品种审批事项的审查，按照以下程序办理： （一）彩票发行机构将拟变更彩票品种审批事项的申请材料报民政部或者国家体育总局进行审核； （二）民政部或者国家体育总局审核同意后，彩票发行机构向财政部提交申请材料； （三）财政部自收到申请材料之日起10个工作日之内，对申请材料进行初步审核，并出具受理或者不予受理意见书； （四）财政部自受理申请之日起45个工作日内，根据条例、有关彩票管理的制度规定作出书面决定。"},{"i":16,"n":"第十六条","txt":"彩票发行机构申请停止彩票品种或者彩票游戏，应当向财政部报送拟停止彩票品种或者彩票游戏上市以来的销售情况、奖池和调节基金余额、停止发行销售的理由等相关材料。"},{"i":17,"n":"第十七条","txt":"对彩票发行机构申请停止彩票品种或者彩票游戏的审查，按照以下程序办理： （一）彩票发行机构将拟停止彩票品种或者彩票游戏的申请材料报民政部或者国家体育总局进行审核； （二）民政部或者国家体育总局审核同意后，彩票发行机构向财政部提交申请材料； （三）财政部自收到申请材料之日起5个工作日之内，对申请材料进行初步审核，并出具受理或者不予受理意见书； （四）财政部自受理申请之日起10个工作日内，根据条例、有关彩票管理的制度规定作出书面决定。"},{"i":18,"n":"第十八条","txt":"彩票销售机构认为本行政区域内需要停止彩票品种或者彩票游戏、变更彩票品种审批事项的，经省级财政部门提出意见后可以向彩票发行机构提出书面申请建议。"},{"i":19,"n":"第十九条","txt":"条例第十三条所称彩票设备和技术服务，根据彩票发行销售业务的专业性、市场性特点和彩票市场发展需要，分为专用的彩票设备和技术服务与通用的彩票设备和技术服务。 专用的彩票设备和技术服务包括：彩票投注专用设备，彩票开奖设备和服务，彩票发行销售信息技术系统的开发、集成、测试、运营及维护，彩票印制、仓储和运输，彩票营销策划和广告宣传，以及彩票技术和管理咨询等。 通用的彩票设备和技术服务包括：计算机、网络设备、打印机、复印机等通用硬件产品，数据库系统、软件工具等商业软件产品，以及工程建设等。"},{"i":20,"n":"第二十条","txt":"彩票发行机构、彩票销售机构采购彩票设备和技术服务，依照政府采购法及相关规定，以公开招标作为主要采购方式。经同级财政部门批准，彩票发行机构、彩票销售机构采购专用的彩票设备和技术服务，可以采用邀请招标、竞争性谈判、单一来源采购、询价或者国务院政府采购监督管理部门认定的其他采购方式。"},{"i":21,"n":"第二十一条","txt":"彩票代销者应当具备以下条件： （一）年满18周岁且具有完全民事行为能力的个人，或者具有独立法人资格的单位； （二）有与从事彩票代销业务相适应的资金； （三）有满足彩票销售需要的场所； （四）近五年内无刑事处罚记录和不良商业信用记录； （五）彩票发行机构、彩票销售机构规定的其他条件。"},{"i":22,"n":"第二十二条","txt":"彩票发行机构、彩票销售机构向社会征召彩票代销者和设置彩票销售场所，应当遵循以下原则： （一）统筹规划，合理布局； （二）公开公正，规范透明； （三）从优选择，兼顾公益。"},{"i":23,"n":"第二十三条","txt":"彩票发行机构、彩票销售机构应当根据民政部、国家体育总局制定的彩票代销合同示范文本，与彩票代销者签订彩票代销合同。彩票代销合同应当包括以下内容： （一）委托方与受托方的姓名或者名称、住所及法定代表人姓名； （二）合同订立时间、地点、生效时间和有效期限； （三）委托方与受托方的权利和义务； （四）彩票销售场所的设立、迁移、暂停销售、撤销； （五）彩票投注专用设备的提供与管理； （六）彩票资金的结算，以及销售费用、押金或者保证金的管理； （七）不得向未成年人销售彩票和兑奖的约定； （八）监督和违约责任； （九）其他内容。 委托方与受托方应当遵守法律法规、规章制度和有关彩票管理政策，严格履行彩票代销合同。"},{"i":24,"n":"第二十四条","txt":"签订彩票代销合同后，彩票发行机构、彩票销售机构应当向彩票代销者发放彩票代销证。福利彩票代销证、体育彩票代销证的格式分别由福利彩票发行机构、体育彩票发行机构制定。 彩票代销证应当置于彩票销售场所的显著位置。 彩票代销证是彩票代销者代理销售彩票的合法资格证明，不得转借、出租、出售。"},{"i":25,"n":"第二十五条","txt":"彩票代销证应当记载以下事项： （一）彩票代销证编号； （二）彩票代销者的姓名或者名称、住所及法定代表人姓名； （三）彩票销售场所地址； （四）彩票代销证的有效期限； （五）彩票发行机构规定的其他事项。"},{"i":26,"n":"第二十六条","txt":"彩票发行机构、彩票销售机构应当对从事彩票代销业务的人员进行专业培训。"},{"i":27,"n":"第二十七条","txt":"纸质即开型彩票的废票、尾票，应当定期销毁。 销毁彩票应当采用粉碎、打浆等方式。"},{"i":28,"n":"第二十八条","txt":"彩票发行机构申请销毁纸质即开型彩票的废票、尾票的，应当向财政部提出书面申请并提交拟销毁彩票的名称、面值、数量、金额，以及销毁时间、地点、方式等材料。 财政部应当自受理申请之日起10个工作日内，对申请进行审查并作出书面决定。 彩票发行机构应当自财政部作出书面决定之日起30个工作日内分别在民政部、国家体育总局的监督下销毁彩票，并于销毁后20个工作日内向财政部报送销毁情况报告。"},{"i":29,"n":"第二十九条","txt":"彩票发行机构、彩票销售机构、彩票代销者在难以判断彩票购买者或者兑奖者是否为未成年人的情况下，可以要求彩票购买者或者兑奖者出示能够证明其年龄的有效身份证件。"},{"i":30,"n":"第三十条","txt":"彩票市场实行休市制度。休市期间，停止彩票的销售、开奖和兑奖。休市的彩票品种和具体时间由财政部向社会公告。"},{"i":31,"n":"第三十一条","txt":"彩票发行机构、彩票销售机构应当于每年5月31日前，向社会公告上年度各彩票品种的销售量、中奖金额、奖池资金余额、调节基金余额等情况。"},{"i":32,"n":"第三十二条","txt":"彩票发行机构、彩票销售机构应当向社会公告彩票游戏的开奖方式、开奖时间、开奖地点。"},{"i":33,"n":"第三十三条","txt":"条例第二十二条所称开奖活动结束，是指彩票游戏的开奖号码全部摇出或者开奖结果全部产生。 通过专用摇奖设备确定开奖号码的，应当在当期彩票销售截止时封存彩票销售原始数据；通过专用电子摇奖设备或者根据体育比赛项目确定开奖号码的，应当定期封存彩票销售原始数据。 彩票销售原始数据保存期限，自封存之日起不得少于60个月。"},{"i":34,"n":"第三十四条","txt":"民政部、国家体育总局和省级民政部门、体育行政部门应当制定福利彩票、体育彩票的开奖监督管理办法，加强对彩票开奖活动的监督。"},{"i":35,"n":"第三十五条","txt":"彩票发行机构、彩票销售机构应当统一购置、直接管理开奖设备。 彩票发行机构、彩票销售机构不得将开奖设备转借、出租、出售。"},{"i":36,"n":"第三十六条","txt":"彩票发行机构、彩票销售机构使用专用摇奖设备或者专用电子摇奖设备开奖的，开始摇奖前，应当对摇奖设备进行检测。摇奖设备进入正式摇奖程序后，不得中途暂停或者停止运行。 因设备、设施故障等造成摇奖中断的，已摇出的号码有效。未摇出的剩余号码，应当尽快排除故障后继续摇出；设备、设施故障等无法排除的，应当启用备用摇奖设备、设施继续摇奖。 摇奖活动结束后，彩票发行机构、彩票销售机构负责摇奖的工作人员应当对摇奖结果进行签字确认。签字确认文件保存期限不得少于60个月。"},{"i":37,"n":"第三十七条","txt":"根据体育比赛结果进行开奖的彩票游戏，体育比赛裁定的比赛结果经彩票发行机构或者彩票销售机构依据彩票游戏规则确认后，作为开奖结果。 体育比赛因各种原因提前、推迟、中断、取消或者被认定为无效场次的，其开奖和兑奖按照经批准的彩票游戏规则执行。"},{"i":38,"n":"第三十八条","txt":"未按照彩票游戏规则和开奖操作规程进行的开奖活动及开奖结果无效。 因自然灾害等不可抗力事件导致不能按期开奖的，应当及时向社会公告后延期开奖；导致开奖中断的，已开出的号码有效，应当及时向社会公告后延期开出剩余号码。"},{"i":39,"n":"第三十九条","txt":"彩票发行机构、彩票销售机构应当及时、准确、完整地向社会公告当期彩票销售和开奖情况，公告内容包括： （一）彩票游戏名称，开奖日期或者期号； （二）当期彩票销售金额； （三）当期彩票开奖结果； （四）奖池资金余额； （五）兑奖期限。"},{"i":40,"n":"第四十条","txt":"彩票售出后出现下列情况的，不予兑奖： （一）彩票因受损、玷污等原因导致无法正确识别的； （二）纸质即开型彩票出现兑奖区覆盖层撕刮不开、无兑奖符号、保安区裸露等问题的。 不予兑奖的彩票如果是因印制、运输、仓储、销售原因造成的，彩票发行机构、彩票销售机构应当予以收回，并按彩票购买者意愿退还其购买该彩票所支付的款项或者更换同等金额彩票。"},{"i":41,"n":"第四十一条","txt":"彩票中奖者应当自开奖之日起60个自然日内兑奖。最后一天为《全国年节及纪念日放假办法》规定的全体公民放假的节日或者彩票市场休市的，顺延至全体公民放假的节日后或者彩票市场休市结束后的第一个工作日。"},{"i":42,"n":"第四十二条","txt":"彩票中奖奖金不得以人民币以外的其他货币兑付，不得以实物形式兑付，不得分期多次兑付。"},{"i":43,"n":"第四十三条","txt":"彩票发行机构、彩票销售机构、彩票代销者及其工作人员不得违背彩票中奖者本人意愿，以任何理由和方式要求彩票中奖者捐赠中奖奖金。"},{"i":44,"n":"第四十四条","txt":"条例第二十八条所称彩票资金，是指彩票销售实现后取得的资金，包括彩票奖金、彩票发行费、彩票公益金。 条例第二十八条所称彩票资金构成比例，是指彩票奖金、彩票发行费、彩票公益金占彩票资金的比重。 条例第二十八条所称彩票资金的具体构成比例，是指在彩票游戏规则中规定的，按照彩票销售额计提彩票奖金、彩票发行费、彩票公益金的具体比例。"},{"i":45,"n":"第四十五条","txt":"彩票发行机构、彩票销售机构应当开设彩票资金专用账户，包括彩票资金归集结算账户、彩票投注设备押金或者保证金账户。"},{"i":46,"n":"第四十六条","txt":"彩票奖金应当按照彩票游戏规则的规定支付给彩票中奖者。 彩票游戏单注奖金的最高限额，由财政部根据彩票市场发展情况在彩票游戏规则中规定。"},{"i":47,"n":"第四十七条","txt":"彩票发行机构、彩票销售机构应当按照彩票游戏规则的规定设置奖池和调节基金。奖池和调节基金应当按照彩票游戏规则的规定分别核算和使用。 彩票发行机构、彩票销售机构应当设置一般调节基金。彩票游戏经批准停止销售后的奖池和调节基金结余，转入一般调节基金。"},{"i":48,"n":"第四十八条","txt":"经同级财政部门审核批准后，彩票发行机构、彩票销售机构开展彩票游戏派奖活动所需资金，可以从该彩票游戏的调节基金或者一般调节基金中支出。 不得使用奖池资金、业务费开展派奖活动。"},{"i":49,"n":"第四十九条","txt":"条例第三十二条所称业务费，是指彩票发行机构、彩票销售机构按照彩票销售额一定比例提取的，专项用于彩票发行销售活动的经费。"},{"i":50,"n":"第五十条","txt":"彩票发行机构、彩票销售机构的业务费提取比例，由彩票发行机构、彩票销售机构根据彩票市场发展需要提出方案，报同级民政部门或者体育行政部门商同级财政部门核定后执行。"},{"i":51,"n":"第五十一条","txt":"彩票发行机构、彩票销售机构的业务费由彩票发行机构、彩票销售机构按月缴入中央财政专户和省级财政专户，实行收支两条线管理。 彩票代销者的销售费用，由彩票发行机构、彩票销售机构与彩票代销者按照彩票代销合同的约定进行结算。"},{"i":52,"n":"第五十二条","txt":"彩票发行机构、彩票销售机构应当根据彩票市场发展情况和发行销售业务需要，编制年度财务收支计划，报同级财政部门审核批准后执行。 财政部和省级财政部门应当按照国家有关规定审核批准彩票发行机构、彩票销售机构的年度财务收支计划，并根据其业务开支需要和业务费缴纳情况及时拨付资金。 未拨付的彩票发行机构、彩票销售机构的业务费，用于弥补彩票发行机构、彩票销售机构的收支差额，不得用于平衡财政一般预算或者其他支出。"},{"i":53,"n":"第五十三条","txt":"彩票销售机构的业务费实行省级集中统一管理，由福利彩票销售机构、体育彩票销售机构按照省级财政部门审核批准的年度财务收支计划，分别统筹安排用于本行政区域内福利彩票、体育彩票的销售工作。"},{"i":54,"n":"第五十四条","txt":"彩票发行机构、彩票销售机构应当在业务费中提取彩票发行销售风险基金、彩票兑奖周转金。 彩票发行销售风险基金专项用于因彩票市场变化或者不可抗力事件等造成的彩票发行销售损失支出。彩票兑奖周转金专项用于向彩票中奖者兑付奖金的周转支出。"},{"i":55,"n":"第五十五条","txt":"彩票公益金按照政府性基金管理办法纳入预算，实行收支两条线管理，专项用于社会福利、体育等社会公益事业，结余结转下年继续使用，不得用于平衡财政一般预算。"},{"i":56,"n":"第五十六条","txt":"彩票公益金按照国务院批准的分配政策在中央与地方之间分配，由彩票销售机构分别上缴中央财政和省级财政。 上缴中央财政的彩票公益金，由财政部驻各省、自治区、直辖市财政监察专员办事处就地征收；上缴省级财政的彩票公益金，由省级财政部门负责征收。"},{"i":57,"n":"第五十七条","txt":"逾期未兑奖的奖金纳入彩票公益金，由彩票销售机构结算归集后上缴省级财政，全部留归地方使用。"},{"i":58,"n":"第五十八条","txt":"中央和省级彩票公益金的管理、使用单位，应当会同同级财政部门制定彩票公益金资助项目实施管理办法。 彩票公益金的管理、使用单位，应当及时向社会进行公告或者发布消息，依法接受财政部门、审计部门和社会公众的监督。 彩票公益金资助的基本建设设施、设备或者社会公益活动，应当以显著方式标明彩票公益金资助标识。"},{"i":59,"n":"第五十九条","txt":"财政部应当每年向社会公告上年度全国彩票公益金的筹集、分配和使用情况。省级财政部门应当每年向社会公告上年度本行政区域彩票公益金的筹集、分配和使用情况。 中央和地方各级彩票公益金的管理、使用单位，应当每年向社会公告上年度彩票公益金的使用规模、资助项目和执行情况等。"},{"i":60,"n":"第六十条","txt":"彩票发行机构、彩票销售机构有下列行为之一的，由财政部门责令改正；对直接负责的主管人员和其他直接责任人员，建议所在单位或者主管部门给予相应的处分： （一）违反彩票销售原始数据、彩票开奖设备管理规定的； （二）违反彩票发行销售风险基金、彩票兑奖周转金或者彩票游戏的奖池资金、调节基金以及一般调节基金管理规定的； （三）未按批准的销毁方式、期限销毁彩票的； （四）未按规定向社会公告相关信息的； （五）使用奖池资金、业务费开展派奖活动的； （六）未以人民币现金或者现金支票形式一次性兑奖的。"},{"i":61,"n":"第六十一条","txt":"彩票代销者有下列行为之一的，由民政部门、体育行政部门责令改正；情节严重的，责成彩票发行机构、彩票销售机构解除彩票代销合同： （一）转借、出租、出售彩票代销证的； （二）未以人民币现金或者现金支票形式一次性兑奖的。"},{"i":62,"n":"第六十二条","txt":"各级财政部门、民政部门、体育行政部门及其工作人员，在彩票监督管理活动中存在违反本细则规定的行为，以及滥用职权、玩忽职守、徇私舞弊等违法违纪行为的，依照《中华人民共和国行政许可法》《中华人民共和国公务员法》《中华人民共和国监察法》《财政违法行为处罚处分条例》《彩票管理条例》等国家有关规定追究相应责任；涉嫌犯罪的，依法移送司法机关处理。"},{"i":63,"n":"第六十三条","txt":"本细则自2012年3月1日起施行。"}],"zhiyuanfuwujiluyuzhengmingchujubanfa":[{"i":1,"n":"第一条","txt":"为了规范志愿服务记录和志愿服务记录证明出具工作，保障志愿者和志愿服务组织等志愿服务活动参与者的合法权益，促进志愿服务事业发展，根据《中华人民共和国慈善法》和《志愿服务条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称志愿服务记录，是指志愿服务组织和依法开展志愿服务活动的其他组织通过志愿服务信息系统或者纸质载体等形式，记录志愿者参与志愿服务活动的有关信息。 本办法所称志愿服务记录证明，是指志愿服务组织和依法开展志愿服务活动的其他组织依据志愿服务记录信息形成的、能够证明志愿者参加志愿服务有关情况的材料。"},{"i":3,"n":"第三条","txt":"记录志愿服务信息、出具志愿服务记录证明，应当遵循真实、准确、完整、无偿、及时的原则。"},{"i":4,"n":"第四条","txt":"志愿服务组织记录的志愿服务信息，包括志愿者的个人基本信息、志愿服务情况、培训情况、表彰奖励情况和评价情况。 根据工作需要，志愿服务组织还可以记录与志愿服务有关的其他信息。 志愿服务组织可以通过国务院民政部门指定的志愿服务信息系统记录志愿服务信息，也可以通过其他志愿服务信息系统或者纸质载体等形式记录。其他志愿服务信息系统或者纸质载体等形式记录的志愿者个人基本信息、志愿服务情况等信息，志愿服务组织应当按照统一的信息数据标准录入国务院民政部门指定的志愿服务信息系统，实现数据互联互通。"},{"i":5,"n":"第五条","txt":"志愿者的个人基本信息，包括姓名、性别、出生日期、身份证件号码、居住区域、联系方式、专业技能和服务类别等。"},{"i":6,"n":"第六条","txt":"志愿者的个人基本信息，可以由志愿者本人在志愿服务信息系统录入；经志愿者同意后，也可以由志愿服务组织录入。 志愿者提供的个人基本信息应当真实、准确、完整。 志愿服务组织发现志愿者的个人基本信息有明显错误、缺漏，或者与实际情况不一致的，应当要求志愿者修改、补充。"},{"i":7,"n":"第七条","txt":"志愿者的志愿服务情况，包括志愿者参加志愿服务活动的名称、日期、地点、服务内容、服务时间、活动组织单位和活动负责人。 前款的服务时间是指志愿者参与志愿服务实际付出的时间，以小时为计量单位。志愿服务组织应当根据志愿服务活动的实际情况，科学合理确定服务时间。"},{"i":8,"n":"第八条","txt":"志愿者的培训情况，包括志愿者参加志愿服务有关培训的名称、主要内容、学习时长、培训举办单位和日期等信息。 志愿服务组织应当及时、如实记录志愿者的培训情况。"},{"i":9,"n":"第九条","txt":"志愿者的表彰奖励情况，包括志愿者获得志愿服务表彰奖励的名称、日期和授予单位。 志愿服务组织应当及时记录志愿者在本组织获得表彰奖励的情况。志愿者获得县级以上人民政府或者有关部门给予志愿服务表彰奖励的，志愿服务组织应当在志愿者提供相关材料后及时、如实记录。 志愿者获得其他组织给予志愿服务表彰奖励的，可以凭相关材料申请志愿服务组织协助记录。志愿服务组织核实无误后应当协助记录。"},{"i":10,"n":"第十条","txt":"志愿者的评价情况，包括对志愿者的服务质量评价以及评价日期。 志愿服务组织可以根据志愿服务完成情况、志愿服务对象反馈情况，对志愿者的服务质量进行评价。 志愿服务组织可以基于服务时间和服务质量等，对志愿者进行星级评价。"},{"i":11,"n":"第十一条","txt":"志愿服务组织应当及时记录志愿服务信息。其中志愿服务情况和评价情况，应当在志愿服务活动结束后10个工作日内完成记录。"},{"i":12,"n":"第十二条","txt":"志愿者可以在志愿服务信息系统中查询本人的志愿服务记录信息。 志愿者需要志愿服务组织协助查询的，志愿服务组织应当给予帮助。"},{"i":13,"n":"第十三条","txt":"志愿者发现本人的志愿服务信息记录有错误、缺漏的，可以向相关志愿服务组织提出。志愿服务组织应当及时核实，确有错误、缺漏的，予以修改、补充。"},{"i":14,"n":"第十四条","txt":"志愿服务组织应当根据志愿者的需要，以志愿服务记录信息为依据，为志愿者无偿、如实出具志愿服务记录证明。 志愿者可以在志愿服务信息系统中打印本人的志愿服务记录证明。"},{"i":15,"n":"第十五条","txt":"志愿服务记录证明应当载明志愿者的志愿服务时间、服务内容和记录单位，也可以包含记录的其他信息。志愿服务记录证明的格式，可以参照国务院民政部门提供的规范样式。 根据志愿者的需要，志愿服务组织可以在志愿服务记录证明上加盖印章。"},{"i":16,"n":"第十六条","txt":"志愿服务组织应当妥善管理志愿服务记录信息，不得将志愿服务记录信息用于商业目的。 未经志愿者本人同意，不得公开或者泄露其有关信息。"},{"i":17,"n":"第十七条","txt":"志愿服务记录证明可以通过志愿服务信息系统查验。 任何单位和个人不得伪造、变造或者使用虚假志愿服务记录证明。"},{"i":18,"n":"第十八条","txt":"志愿服务组织应当在年度工作报告中如实反映开展志愿服务记录和证明出具工作情况，并依法向社会公开。"},{"i":19,"n":"第十九条","txt":"不属于志愿服务的活动，不得进行志愿服务信息记录、出具志愿服务记录证明。"},{"i":20,"n":"第二十条","txt":"任何单位和个人发现志愿服务组织不依法记录志愿服务信息、出具志愿服务记录证明，或者发现单位和个人伪造、变造、使用虚假志愿服务记录证明的，可以向民政部门投诉、举报。"},{"i":21,"n":"第二十一条","txt":"民政部门建立志愿服务信息记录和志愿服务记录证明抽查制度，重点检查志愿服务记录与证明的真实性、合法性，抽查结果向社会公开。"},{"i":22,"n":"第二十二条","txt":"民政部门进行监督检查时，可以向志愿服务有关各方了解核实情况，有权要求志愿服务组织提供相关资料，志愿服务组织不得隐瞒、阻碍或者拒绝。"},{"i":23,"n":"第二十三条","txt":"志愿服务组织泄露志愿者有关记录信息、侵害志愿服务对象个人隐私的，由民政部门依据《志愿服务条例》第三十六条的规定予以警告，责令限期改正；逾期不改正的，责令限期停止活动并进行整改；情节严重的，吊销登记证书并予以公告。"},{"i":24,"n":"第二十四条","txt":"志愿服务组织不依法记录志愿服务信息或者出具志愿服务记录证明的，由民政部门依据《志愿服务条例》第三十八条的规定予以警告，责令限期改正；逾期不改正的，责令限期停止活动，并可以向社会和有关单位通报。"},{"i":25,"n":"第二十五条","txt":"利用志愿服务记录或者志愿服务记录证明出具进行营利性活动的，民政部门可以给予警告。"},{"i":26,"n":"第二十六条","txt":"慈善组织、基层群众性自治组织、公益活动举办单位、公共服务机构开展公益活动，依法与志愿服务组织合作，由志愿服务组织招募志愿者的，应当由志愿服务组织做好志愿服务记录与证明出具工作；依法自行招募志愿者的，参照本办法关于志愿服务组织的规定做好志愿服务记录与证明出具工作。 在城乡社区、单位内部成立的开展志愿服务活动的团体，应当在对其实施管理的基层群众性自治组织或者单位指导下，记录志愿者的志愿服务信息。"},{"i":27,"n":"第二十七条","txt":"本办法自2021年2月1日起施行。"}],"cishanzuzhibaozhizengzhitouzihuodongguanlizanxingbe01dba":[{"i":1,"n":"第一条","txt":"为规范慈善组织的投资活动，防范慈善财产运用风险，促进慈善组织持续健康发展，根据《中华人民共和国慈善法》（以下简称《慈善法》）等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上人民政府民政部门（以下简称民政部门）依法登记、认定的慈善组织进行投资活动，适用本办法。"},{"i":3,"n":"第三条","txt":"慈善组织应当以面向社会开展慈善活动为宗旨，充分、高效运用慈善财产，在确保年度慈善活动支出符合法定要求和捐赠财产及时足额拨付的前提下，可以开展投资活动。 慈善组织开展投资活动应当遵循合法、安全、有效的原则，投资取得的收益应当全部用于慈善目的。"},{"i":4,"n":"第四条","txt":"本办法所称投资活动，主要包括下列情形： （一）直接购买银行、信托、证券、基金、期货、保险资产管理机构、金融资产投资公司等金融机构发行的资产管理产品； （二）通过发起设立、并购、参股等方式直接进行股权投资； （三）将财产委托给受金融监督管理部门监管的机构进行投资。"},{"i":5,"n":"第五条","txt":"慈善组织可以用于投资的财产限于非限定性资产和在投资期间暂不需要拨付的限定性资产。 慈善组织接受的政府资助的财产和捐赠协议约定不得投资的财产，不得用于投资。"},{"i":6,"n":"第六条","txt":"慈善组织在投资资产管理产品时，应当审慎选择，购买与本组织风险识别能力和风险承担能力相匹配的产品。 慈善组织直接进行股权投资的，被投资方的经营范围应当与慈善组织的宗旨和业务范围相关。 慈善组织开展委托投资的，应当选择中国境内有资质从事投资管理业务，且管理审慎、信誉较高的机构。"},{"i":7,"n":"第七条","txt":"慈善组织不得进行下列投资活动： （一）直接买卖股票； （二）直接购买商品及金融衍生品类产品； （三）投资人身保险产品； （四）以投资名义向个人、企业提供借款； （五）不符合国家产业政策的投资； （六）可能使本组织承担无限责任的投资； （七）违背本组织宗旨、可能损害信誉的投资； （八）非法集资等国家法律法规禁止的其他活动。"},{"i":8,"n":"第八条","txt":"慈善组织应当在财务和资产管理制度中规定以下内容： （一）投资遵循的基本原则； （二）投资决策程序和管理流程； （三）决策机构、执行机构、监督机构在投资活动中的相关职责； （四）投资负面清单； （五）重大投资的标准； （六）投资风险管控制度； （七）投资活动中止、终止或者退出机制； （八）违规投资责任追究制度。"},{"i":9,"n":"第九条","txt":"慈善组织的财务和资产管理制度以及重大投资方案应当经决策机构组成人员三分之二以上同意。"},{"i":10,"n":"第十条","txt":"慈善组织的发起人、主要捐赠人、负责人、理事、理事来源单位以及其他与慈善组织之间存在控制、共同控制或者重大影响关系的个人或者组织，当其利益与慈善组织投资行为关联时，不得利用关联关系损害慈善组织利益。"},{"i":11,"n":"第十一条","txt":"慈善组织应当及时回收到期的本金和收益，依法依规及时进行会计核算。"},{"i":12,"n":"第十二条","txt":"慈善组织应当为投资活动建立专项档案，完整保存投资的决策、执行、管理等资料。专项档案的保存时间不少于20年。"},{"i":13,"n":"第十三条","txt":"慈善组织应当根据投资活动的风险水平以及所能承受的损失程度，合理建立止损机制。 慈善组织可以建立风险准备金制度。"},{"i":14,"n":"第十四条","txt":"慈善组织在开展投资活动时，其负责人、理事和工作人员应当遵守法律法规和本组织章程的规定，严格履行忠实、谨慎、勤勉义务。 慈善组织在开展投资活动时有违法违规行为，致使慈善组织财产损失的，相关人员应当承担相应责任。"},{"i":15,"n":"第十五条","txt":"慈善组织的负责人和工作人员不得在慈善组织投资的企业兼职或者领取报酬，但受慈善组织委托可以作为股东代表、董事或者监事参与被投资企业的股东会、董事会。"},{"i":16,"n":"第十六条","txt":"民政部门可以要求慈善组织就投资活动、风险控制、内部管理等事项作出说明，必要时可以进行约谈。"},{"i":17,"n":"第十七条","txt":"慈善组织将不得用于投资的财产用于投资，民政部门依据《慈善法》第九十九条的有关规定进行处罚。慈善组织违反本办法规定，民政部门可以给予警告，并责令限期改正。"},{"i":18,"n":"第十八条","txt":"慈善组织的财务和资产管理制度、重大投资情况应当依法依规向社会公开，接受社会监督。"},{"i":19,"n":"第十九条","txt":"未认定为慈善组织的基金会、具有公益性捐赠税前扣除资格的社会团体和社会服务机构开展投资活动应当遵守本办法规定。"},{"i":20,"n":"第二十条","txt":"本办法自2019年1月1日起施行。"}],"cishanzuzhixinxigongkaibanfa":[{"i":1,"n":"第一条","txt":"为规范慈善组织的信息公开行为，保护捐赠人、志愿者、受益人等慈善活动参与者的合法权益，维护社会公众的知情权，促进慈善事业发展，根据《中华人民共和国慈善法》（以下简称《慈善法》）制定本办法。"},{"i":2,"n":"第二条","txt":"慈善组织应当依法履行信息公开义务，信息公开应当真实、完整、及时。 慈善组织应当建立信息公开制度，明确信息公开的范围、方式和责任。 慈善组织应当对信息的真实性负责，不得有虚假记载、误导性陈述或者重大遗漏，不得以新闻发布、广告推广等形式代替应当履行的信息公开义务。"},{"i":3,"n":"第三条","txt":"慈善组织应当依照有关法律法规和本办法规定，在民政部门提供的统一的信息平台（以下简称统一信息平台），向社会公开下列信息： （一）本办法规定的基本信息； （二）年度工作报告和财务会计报告； （三）公开募捐情况； （四）慈善项目有关情况； （五）慈善信托有关情况； （六）重大资产变动及投资、重大交换交易及资金往来、关联交易行为等情况； （七）法律法规要求公开的其他信息。"},{"i":4,"n":"第四条","txt":"慈善组织应当自下列基本信息形成之日起30日内，在统一信息平台向社会公开： （一）经民政部门核准的章程； （二）决策、执行、监督机构成员信息； （三）下设的办事机构、分支机构、代表机构、专项基金和其他机构的名称、设立时间、存续情况、业务范围或者主要职能； （四）发起人、主要捐赠人、管理人员、被投资方以及与慈善组织存在控制、共同控制或者重大影响关系的个人或者组织（以下简称重要关联方）； （五）本组织的联系人、联系方式，以本组织名义开通的门户网站、官方微博、官方微信或者移动客户端等网络平台； （六）本组织的信息公开制度、项目管理制度、财务和资产管理制度。 基本信息中属于慈善组织登记事项的，由民政部门予以公开，慈善组织可以免予公开。 慈善组织可以将基本信息制作纸质文本置于本组织的住所，方便社会公众查阅、复制。"},{"i":5,"n":"第五条","txt":"具有公开募捐资格的慈善组织应当公开的基本信息还包括： （一）按年度公开在本组织领取报酬从高到低排序前五位人员的报酬金额； （二）本组织出国（境）经费、车辆购置及运行费用、招待费用、差旅费用的标准。"},{"i":6,"n":"第六条","txt":"慈善组织应当按照有关法律法规规定的时限，将年度工作报告和财务会计报告在统一信息平台向社会公开。具有公开募捐资格的慈善组织的年度财务会计报告需经审计。 年度工作报告的具体内容和基本格式由国务院民政部门统一制定。"},{"i":7,"n":"第七条","txt":"慈善组织开展公开募捐活动，应当在募捐活动现场或者募捐活动载体的显著位置，公布组织名称、公开募捐资格证书、备案的募捐方案、联系方式、募捐信息查询方法等，并在统一信息平台向社会公开。慈善组织与其他组织或者个人合作开展公开募捐的，还应当公开合作方的有关信息。 慈善组织通过互联网开展公开募捐的，应当按照有关规定发布募捐信息。"},{"i":8,"n":"第八条","txt":"具有公开募捐资格的慈善组织开展公开募捐活动，应当在公开募捐活动结束后三个月内在统一信息平台公开下列信息： （一）募得款物情况； （二）已经使用的募得款物的用途，包括用于慈善项目和其他用途的支出情况； （三）尚未使用的募得款物的使用计划。 公开募捐周期超过六个月的，至少每三个月公开一次前款第（一）、第（二）项所规定的信息。"},{"i":9,"n":"第九条","txt":"慈善组织在设立慈善项目时，应当在统一信息平台公开该慈善项目的名称和内容，慈善项目结束的，应当公开有关情况。 具有公开募捐资格的慈善组织为慈善项目开展公开募捐活动的，还应当公开相关募捐活动的名称。 慈善项目由慈善信托支持的，还应当公开相关慈善信托的名称。"},{"i":10,"n":"第十条","txt":"具有公开募捐资格的慈善组织，应当在慈善项目终止后三个月内，在统一信息平台向社会公开慈善项目实施情况，包括：项目名称、项目内容、实施地域、受益人群、来自公开募捐和其他来源的收入、项目的支出情况，项目终止后有剩余财产的还应当公开剩余财产的处理情况。 项目实施周期超过六个月的，至少每三个月公开一次项目实施情况。"},{"i":11,"n":"第十一条","txt":"慈善组织担任慈善信托受托人的，应当每年至少一次将信托事务处理情况及财务状况在统一信息平台向社会公开。"},{"i":12,"n":"第十二条","txt":"慈善组织发生下列情形后30日内，应当在统一信息平台向社会公开具体内容和金额： （一）重大资产变动； （二）重大投资； （三）重大交易及资金往来。 前款中规定的重大资产变动、重大投资、重大交易及资金往来的具体标准，由慈善组织依据有关法律法规规章在本组织章程或者财务资产管理制度中规定。"},{"i":13,"n":"第十三条","txt":"慈善组织在下列关联交易等行为发生后30日内，应当在统一信息平台向社会公开具体内容和金额： （一）接受重要关联方捐赠； （二）对重要关联方进行资助； （三）与重要关联方共同投资； （四）委托重要关联方开展投资活动； （五）与重要关联方发生交易； （六）与重要关联方发生资金往来。"},{"i":14,"n":"第十四条","txt":"慈善组织应当在统一信息平台为每年的年度工作报告和财务会计报告、每个公开募捐活动和慈善项目建立相对独立的信息条目。 慈善组织需要对统一信息平台的信息进行更正的，应当在统一信息平台填写并公布更正说明，有独立信息条目的在相应信息条目下予以公布。基本信息发生变更的，慈善组织应当在变更后30日内在统一信息平台向社会公布。"},{"i":15,"n":"第十五条","txt":"慈善组织开展定向募捐的，应当及时向捐赠人告知募捐情况、捐赠款物管理使用情况。捐赠人要求将捐赠款物管理使用情况向社会公开的，慈善组织应当向社会公开。"},{"i":16,"n":"第十六条","txt":"慈善组织应当向受益人告知其资助标准、工作流程和工作规范等信息。 鼓励慈善组织向社会公开前款规定的信息。"},{"i":17,"n":"第十七条","txt":"慈善组织招募志愿者参与慈善服务，应当公示与慈善服务有关的全部信息，以及在服务过程中可能发生的风险。"},{"i":18,"n":"第十八条","txt":"慈善组织对外公开有关机关登记、核准、备案的事项时，应当与有关机关的信息一致。 慈善组织公布的信息相互之间应当一致。 慈善组织在其他渠道公布的信息，应当与其在统一信息平台上公布的信息一致。"},{"i":19,"n":"第十九条","txt":"涉及国家秘密、商业秘密、个人隐私的信息以及捐赠人、志愿者、受益人、慈善信托的委托人不同意公开的姓名、名称、住所、通讯方式等信息，不得公开。"},{"i":20,"n":"第二十条","txt":"慈善组织不及时公开应当公开的事项或者公开的事项不真实的，任何单位或者个人可以向民政部门投诉、举报。"},{"i":21,"n":"第二十一条","txt":"民政部门可以要求慈善组织就信息公开的相关事项作出说明，必要时可以进行约谈，并向社会公开。"},{"i":22,"n":"第二十二条","txt":"慈善组织违反本办法规定的，民政部门可以责令限期改正。"},{"i":23,"n":"第二十三条","txt":"慈善组织有下列情形的，民政部门依据《慈善法》第九十九条的有关规定进行处罚： （一）未依法履行信息公开义务的； （二）泄露捐赠人、志愿者、受益人个人隐私以及捐赠人、志愿者、受益人、慈善信托的委托人不同意公开的姓名、名称、住所、通讯方式等信息的。"},{"i":24,"n":"第二十四条","txt":"慈善组织在信息公开中违反有关法律法规规章和本办法规定的，民政部门应当进行记录，并将相关情况通报有关部门，根据有关规定实施联合惩戒。"},{"i":25,"n":"第二十五条","txt":"民政部门工作人员在工作中滥用职权、徇私舞弊、玩忽职守的，由上级机关或者监察机关依法责令改正；依法应当给予处分的，由任免机关或者监察机关对直接负责的主管人员和其他直接责任人员给予处分。"},{"i":26,"n":"第二十六条","txt":"本办法自2018年9月1日起施行。"}],"cishanzuzhigongkaimujuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范慈善组织开展公开募捐，根据《中华人民共和国慈善法》（以下简称《慈善法》），制定本办法。"},{"i":2,"n":"第二条","txt":"慈善组织公开募捐资格和公开募捐活动管理，适用本办法。"},{"i":3,"n":"第三条","txt":"依法取得公开募捐资格的慈善组织可以面向公众开展募捐。不具有公开募捐资格的组织和个人不得开展公开募捐。"},{"i":4,"n":"第四条","txt":"县级以上人民政府民政部门依法对其登记的慈善组织公开募捐资格和公开募捐活动进行监督管理，并对本行政区域内涉及公开募捐的有关活动进行监督管理。"},{"i":5,"n":"第五条","txt":"依法登记或者认定为慈善组织满二年的社会组织，申请公开募捐资格，应当符合下列条件： （一）根据法律法规和本组织章程建立规范的内部治理结构，理事会能够有效决策，负责人任职符合有关规定，理事会成员和负责人勤勉尽职，诚实守信； （二）理事会成员来自同一组织以及相互间存在关联关系组织的不超过三分之一，相互间具有近亲属关系的没有同时在理事会任职； （三）理事会成员中非内地居民不超过三分之一，法定代表人由内地居民担任; （四）秘书长为专职，理事长（会长）、秘书长不得由同一人兼任，有与本慈善组织开展活动相适应的专职工作人员； （五）在省级以上人民政府民政部门登记的慈善组织有三名以上监事组成的监事会； （六）依法办理税务登记，履行纳税义务； （七）按照规定参加社会组织评估，评估结果为3A及以上； （八）申请时未纳入异常名录； （九）申请公开募捐资格前二年，未因违反社会组织相关法律法规受到行政处罚，没有其"},{"i":6,"n":"第六条","txt":"慈善组织申请公开募捐资格，应当向其登记的民政部门提交下列材料： （一）申请书，包括本组织符合第五条各项条件的具体说明和书面承诺； （二）注册会计师出具的申请前二年的财务审计报告，包括年度慈善活动支出和年度管理费用的专项审计； （三）理事会关于申请公开募捐资格的会议纪要。 有业务主管单位的慈善组织，还应当提交经业务主管单位同意的证明材料。 评估等级在4A及以上的慈善组织免于提交第一款第二项、第三项规定的材料。"},{"i":7,"n":"第七条","txt":"民政部门收到全部有效材料后，应当依法进行审核。 情况复杂的，民政部门可以征求有关部门意见或者通过论证会、听证会等形式听取意见，也可以根据需要对该组织进行实地考察。"},{"i":8,"n":"第八条","txt":"民政部门应当自受理之日起二十日内作出决定。对符合条件的慈善组织，发给公开募捐资格证书；对不符合条件的，不发给公开募捐资格证书并书面说明理由。"},{"i":9,"n":"第九条","txt":"《慈善法》公布前登记设立的公募基金会，凭其标明慈善组织属性的登记证书向登记的民政部门申领公开募捐资格证书。"},{"i":10,"n":"第十条","txt":"开展公开募捐活动，应当依法制定募捐方案。募捐方案包括募捐目的、起止时间和地域、活动负责人姓名和办公地址、接受捐赠方式、银行账户、受益人、募得款物用途、募捐成本、剩余财产的处理等。"},{"i":11,"n":"第十一条","txt":"慈善组织应当在开展公开募捐活动的十日前将募捐方案报送登记的民政部门备案。材料齐备的，民政部门应当即时受理，对予以备案的向社会公开；对募捐方案内容不齐备的，应当即时告知慈善组织，慈善组织应当在十日内向其登记的民政部门予以补正。 为同一募捐目的开展的公开募捐活动可以合并备案。公开募捐活动进行中，募捐方案的有关事项发生变化的，慈善组织应当在事项发生变化之日起十日内向其登记的民政部门补正并说明理由。 有业务主管单位的慈善组织，还应当同时将募捐方案报送业务主管单位。 开展公开募捐活动，涉及公共安全、公共秩序、消防等事项的，还应当按照其他有关规定履行批准程序。"},{"i":12,"n":"第十二条","txt":"慈善组织为应对重大自然灾害、事故灾难和公共卫生事件等突发事件，无法在开展公开募捐活动前办理募捐方案备案的，应当在公开募捐活动开始后十日内补办备案手续。"},{"i":13,"n":"第十三条","txt":"慈善组织在其登记的民政部门管辖区域外，以《慈善法》第二十三条第一款第一项、第二项方式开展公开募捐活动的，除向其登记的民政部门备案外，还应当在开展公开募捐活动十日前，向其开展募捐活动所在地的县级人民政府民政部门备案，提交募捐方案、公开募捐资格证书复印件、确有必要在当地开展公开募捐活动的情况说明。"},{"i":14,"n":"第十四条","txt":"慈善组织开展公开募捐活动应当按照本组织章程载明的宗旨和业务范围，确定明确的募捐目的和捐赠财产使用计划；应当履行必要的内部决策程序；应当使用本组织账户，不得使用个人和其他组织的账户；应当建立公开募捐信息档案，妥善保管、方便查阅。"},{"i":15,"n":"第十五条","txt":"慈善组织开展公开募捐活动，应当在募捐活动现场或者募捐活动载体的显著位置，公布本组织名称、公开募捐资格证书、募捐方案、联系方式、募捐信息查询方法等。"},{"i":16,"n":"第十六条","txt":"慈善组织通过互联网开展公开募捐活动的，应当在民政部统一或者指定的慈善信息平台发布公开募捐信息，并可以同时在以本慈善组织名义开通的门户网站、官方微博、官方微信、移动客户端等网络平台发布公开募捐信息。"},{"i":17,"n":"第十七条","txt":"具有公开募捐资格的慈善组织与不具有公开募捐资格的组织或者个人合作开展公开募捐活动，应当依法签订书面协议，使用具有公开募捐资格的慈善组织名义开展公开募捐活动；募捐活动的全部收支应当纳入该慈善组织的账户，由该慈善组织统一进行财务核算和管理，并承担法律责任。"},{"i":18,"n":"第十八条","txt":"慈善组织为急难救助设立慈善项目，开展公开募捐活动时，应当坚持公开、公平、公正的原则，合理确定救助标准，监督受益人珍惜慈善资助，按照募捐方案的规定合理使用捐赠财产。"},{"i":19,"n":"第十九条","txt":"慈善组织应当加强对募得捐赠财产的管理，依据法律法规、章程规定和募捐方案使用捐赠财产。确需变更募捐方案规定的捐赠财产用途的，应当召开理事会进行审议，报其登记的民政部门备案，并向社会公开。"},{"i":20,"n":"第二十条","txt":"慈善组织应当依照有关规定定期将公开募捐情况和慈善项目实施情况向社会公开。"},{"i":21,"n":"第二十一条","txt":"具有公开募捐资格的慈善组织有下列情形之一的，由登记的民政部门纳入活动异常名录并向社会公告： （一）不符合本办法第五条规定条件的； （二）连续六个月不开展公开募捐活动的。"},{"i":22,"n":"第二十二条","txt":"慈善组织被依法撤销公开募捐资格的，应当立即停止公开募捐活动并将相关情况向社会公开。 出现前款规定情形的，民政部门应当及时向社会公告。"},{"i":23,"n":"第二十三条","txt":"慈善组织有下列情形之一的，民政部门可以给予警告、责令限期改正： （一）伪造、变造、出租、出借公开募捐资格证书的； （二）未依照本办法进行备案的； （三）未按照募捐方案确定的时间、期限、地域范围、方式进行募捐的； （四）开展公开募捐未在募捐活动现场或者募捐活动载体的显著位置公布募捐活动信息的； （五）开展公开募捐取得的捐赠财产未纳入慈善组织统一核算和账户管理的； （六）其他违反本办法情形的。"},{"i":24,"n":"第二十四条","txt":"公开募捐资格证书、公开募捐方案范本等格式文本，由民政部统一制定。"},{"i":25,"n":"第二十五条","txt":"本办法由民政部负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2016年9月1日起施行。"}],"cishanzuzhirendingbanfa":[{"i":1,"n":"第一条","txt":"为了规范慈善组织认定工作，根据《中华人民共和国慈善法》（以下简称《慈善法》）的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"《慈善法》公布前已经设立的基金会、社会团体、社会服务机构等非营利性组织，申请认定为慈善组织，适用本办法。"},{"i":3,"n":"第三条","txt":"县级以上人民政府民政部门对其登记的基金会、社会团体、社会服务机构进行慈善组织认定。"},{"i":4,"n":"第四条","txt":"基金会、社会团体、社会服务机构申请认定为慈善组织，应当符合下列条件： （一）申请时具备相应的社会组织法人登记条件； （二）以开展慈善活动为宗旨，业务范围符合《慈善法》第三条的规定；申请时的上一年度慈善活动的年度支出和管理费用符合国务院民政部门关于慈善组织的规定； （三）不以营利为目的，收益和营运结余全部用于章程规定的慈善目的；财产及其孳息没有在发起人、捐赠人或者本组织成员中分配；章程中有关于剩余财产转给目的相同或者相近的其他慈善组织的规定； （四）有健全的财务制度和合理的薪酬制度； （五）法律、行政法规规定的其他条件。"},{"i":5,"n":"第五条","txt":"有下列情形之一的，不予认定为慈善组织： （一）有法律法规和国家政策规定的不得担任慈善组织负责人的情形的； （二）申请前二年内受过行政处罚的； （三）申请时被民政部门列入异常名录的； （四）有其他违反法律、法规、国家政策行为的。"},{"i":6,"n":"第六条","txt":"申请认定为慈善组织，社会团体应当经会员（代表）大会表决通过，基金会、社会服务机构应当经理事会表决通过；有业务主管单位的，还应当经业务主管单位同意。"},{"i":7,"n":"第七条","txt":"申请认定慈善组织的基金会，应当向民政部门提交下列材料： （一）申请书； （二）符合本办法第四条规定以及不存在第五条所列情形的书面承诺； （三）按照本办法第六条规定召开会议形成的会议纪要。 申请认定为慈善组织的社会团体、社会服务机构，除前款规定的材料外，还应当向民政部门提交下列材料： （一）关于申请理由、慈善宗旨、开展慈善活动等情况的说明； （二）注册会计师出具的上一年度财务审计报告，含慈善活动年度支出和管理费用的专项审计。 有业务主管单位的，还应当提交业务主管单位同意的证明材料。"},{"i":8,"n":"第八条","txt":"民政部门自收到全部有效材料后，应当依法进行审核。 情况复杂的，民政部门可以征求有关部门意见或者通过论证会、听证会等形式听取意见，也可以根据需要对该组织进行实地考察。"},{"i":9,"n":"第九条","txt":"民政部门应当自受理申请之日起二十日内作出决定。符合慈善组织条件的，予以认定并向社会公告；不符合慈善组织条件的，不予认定并书面说明理由。"},{"i":10,"n":"第十条","txt":"认定为慈善组织的基金会、社会团体、社会服务机构，由民政部门换发登记证书，标明慈善组织属性。 慈善组织符合税收法律法规规定条件的，依照税法规定享受税收优惠。"},{"i":11,"n":"第十一条","txt":"基金会、社会团体、社会服务机构在申请时弄虚作假的，由民政部门撤销慈善组织的认定，将该组织及直接责任人纳入信用记录，并向社会公布。 对出具虚假审计报告的注册会计师及其所属的会计师事务所，由民政部门通报有关部门。"},{"i":12,"n":"第十二条","txt":"本办法由民政部负责解释。"},{"i":13,"n":"第十三条","txt":"本办法自2016年9月1日起施行。"}],"cunjidanganguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了加强农村档案工作, 规范村级档案管理，服务新形势下的农村工作，根据《中华人民共和国档案法》《中华人民共和国村民委员会组织法》《中华人民共和国农业法》和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称村级档案是指村党组织、村民委员会、村集体经济组织等（以下简称村级组织）在党组织建设、村民自治、生产经营等活动中形成的具有保存价值的文字、图表、音像等不同形式和载体的历史记录。"},{"i":3,"n":"第三条","txt":"村级档案工作主要包括村级组织对村级档案进行的收集、整理、保管、鉴定、利用等工作。"},{"i":4,"n":"第四条","txt":"村级档案工作实行统一领导、集中管理、安全方便的原则。 村级组织应将档案工作作为村级工作的重要事项，健全相应的工作制度，明确领导、健全机制、保障经费，确保档案的真实、完整、规范和安全。"},{"i":5,"n":"第五条","txt":"村级档案工作在业务上接受乡镇人民政府、档案行政管理部门、民政部门、农业部门和相关部门的监督和指导。"},{"i":6,"n":"第六条","txt":"村级组织应当指定专人负责档案的收集、管理和提供利用。有条件的村应当设立专用档案柜和档案库房集中管理档案。 档案管理人员应当具有良好的政治素质，遵纪守法，忠于职守，具备相应的档案管理知识，并经过一定的档案业务培训。"},{"i":7,"n":"第七条","txt":"村级组织形成的具有保存价值的文件材料，均应当按照要求规范整理后归档，任何组织和个人不得据为己有或者拒绝归档。 县级档案行政管理部门可以依据《村级文件材料归档范围和档案保管期限表》（见附件）的规定，制定符合本地实际的村级文件材料归档范围和档案保管期限表。"},{"i":8,"n":"第八条","txt":"村级档案一般包括文书、基建项目、设施设备、会计、音像、实物等类别。各类文件材料整理方法和归档时间如下： （一）文书类应当按照《文书档案案卷格式》（GB/T 9705-2008）或者《归档文件整理规则》（DA/T 22-2015）的要求进行整理，于次年上半年归档。 （二）基建项目类应当按照《科学技术档案案卷构成的一般要求》（GB/T 11822-2008），并参照《国家重大建设项目文件材料归档要求与档案整理规范》（DA/T 28-2002）的有关规定及时整理归档。 （三）设施设备类应当在开箱验收后即时归档，使用维修记录等按照《科学技术档案案卷构成的一般要求》进行收集管理。 （四）会计类应当按照《会计档案管理办法》（财政部 国家档案局令第79号）的要求进行收集整理，在会计年度终了后于次年3月底之前归档。 （五）照片应当按照《照片档案管理规范》（GB/T 11821-2002）、《数码照片归"},{"i":9,"n":"第九条","txt":"档案制成材料和装订材料应当符合档案保护的要求。"},{"i":10,"n":"第十条","txt":"档案库房应当采取防火、防盗、防水（潮）、防光、防尘、防磁、防高温、防有害生物等措施。 档案管理人员应当定期检查档案的保管状况，确保档案安全。对音像档案和电子档案，要定期检查信息记录的安全性，确保档案可读可用。"},{"i":11,"n":"第十一条","txt":"不具备档案安全保管条件的，应当将档案交由乡镇档案机构代为保管，村级组织可以保存档案目录等检索工具以方便利用。"},{"i":12,"n":"第十二条","txt":"村级组织换届选举后10日内，应当履行档案交接手续。必要时可以在选举前将档案暂存乡镇政府。村以及村民小组在设立、撤销、范围调整时，应当将档案妥善移交。 档案工作人员离任时应当进行档案移交，履行交接手续，防止档案散失。"},{"i":13,"n":"第十三条","txt":"销毁已达到保管期限的档案时，应当成立档案鉴定工作小组及时进行鉴定。 鉴定工作小组由村级档案管理人员和形成档案的村级组织的人员（或者村民代表）组成，鉴定后应当形成档案鉴定报告。对失去保存价值的档案，应当清点核对并编制档案销毁清册，经过必要的审批手续后按照规定销毁。 禁止擅自销毁档案。村级档案销毁清册应当永久保存。"},{"i":14,"n":"第十四条","txt":"村级档案工作应当积极推进档案信息化建设，配备必要的设施设备和档案管理软件，建立档案电子目录和全文数据库，逐步实现档案的信息网络共享。"},{"i":15,"n":"第十五条","txt":"村级档案工作应当建立档案查阅利用制度，为本村各类组织及其成员、村民提供服务。查阅档案要遵守利用规定、履行查阅手续，不得有涂改、损毁、调换、抽取档案等行为。 档案管理人员应当围绕村中心工作或村级组织及其成员、村民利用需求，加强档案信息资源的开发利用，积极开展档案编研工作，如编写村史、村志、大事记等。"},{"i":16,"n":"第十六条","txt":"对在村级档案工作中作出突出贡献的村干部、档案工作人员和其他组织、个人，由各级人民政府、档案行政管理部门及相关单位给予表彰和奖励。"},{"i":17,"n":"第十七条","txt":"各省（自治区、直辖市）、新疆生产建设兵团档案行政管理部门商同级民政部门和农业部门，可以结合本办法和本地实际，制定实施办法及细则。"},{"i":18,"n":"第十八条","txt":"本办法由国家档案局、民政部、农业部负责解释。"},{"i":19,"n":"第十九条","txt":"本办法自2018年1月1日起施行。 附件：村级文件材料归档范围和档案保管期限表（略）"}],"minbanfeiqiyedanweiyinzhangguanliguiding":[],"minbanfeiqiyedanweimingchengguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为了规范民办非企业单位名称管理，保护民办非企业单位的合法权益，根据《民办非企业单位登记管理暂行条例》（以下简称条例）制定本规定。"},{"i":2,"n":"第二条","txt":"民办非企业单位登记管理机关（以下简称登记管理机关）负责民办非企业单位名称的核准登记，监督管理其名称的使用，保护其名称权。经登记管理机关核准登记的民办非企业单位名称受法律保护。"},{"i":3,"n":"第三条","txt":"民办非企业单位名称应当由以下部分依次组成：字号、行（事）业或业务领域、组织形式。 民办非企业单位名称应当冠以民办非企业单位所在地省（自治区、直辖市）、市（地、州）、县（县级市、市辖区）行政区划名称或地名。"},{"i":4,"n":"第四条","txt":"民办非企业单位名称不能单独冠以市辖区的名称或地名，应当与所在市的行政区划名称或地名连用。 民政部登记的民办非企业单位，其名称一般不冠以行政区划名称或地名。"},{"i":5,"n":"第五条","txt":"民办非企业单位的字号应当由两个以上的汉字组成。可以使用本地或者异地的地名作字号，但不得使用县以上（含县）行政区划名称作字号。"},{"i":6,"n":"第六条","txt":"民办非企业单位应当根据其业务，依照国家行（事）业分类标准划分的类别，在民办非企业单位名称中标明所属行（事）业或者业务特点。"},{"i":7,"n":"第七条","txt":"民办非企业单位名称中所标明的组织形式必须明确易懂，一般称学校、学院、园、医院、中心、院、所、馆、站、社、公寓、俱乐部等。不得使用“总”字。"},{"i":8,"n":"第八条","txt":"民办非企业单位名称应当使用汉字，民族自治地方的民办非企业单位名称可以同时使用本民族自治地方通用的民族文字。"},{"i":9,"n":"第九条","txt":"民办非企业单位名称应当符合法律、法规的规定，不得含有下列文字和内容： （一）冠以“中国”“全国”“中华”等字样； （二）有损于国家、社会公共利益的，违背社会道德风尚，带有封建迷信色彩的； （三）可能对公众造成欺骗或者误解的； （四）政党名称、党政军机关名称、人民团体名称、社会团体名称、事业单位名称、企业名称及宗教界的寺、观、教堂（佛、道教的寺、观，伊斯兰教的清真寺，天主教、基督教的教堂）名称； （五）已被撤销的民办非企业单位的名称； （六）其他法律、行政法规规定禁止的。"},{"i":10,"n":"第十条","txt":"民办非企业单位只准使用一个名称，在登记管理机关管辖范围内不得与已登记的同行（事）业单位名称相同。"},{"i":11,"n":"第十一条","txt":"民办非企业单位申请成立登记、变更名称登记，业务主管单位应当将民办非企业单位拟定名称意见报登记管理机关。"},{"i":12,"n":"第十二条","txt":"两个以上民办非企业单位向同一登记管理机关申请相同的符合规定的民办非企业单位名称，登记管理机关依照申请在先原则登记。"},{"i":13,"n":"第十三条","txt":"本规定自发布之日起施行。"}],"minbanfeiqiyedanweiniandujianchabanfa":[{"i":1,"n":"第一条","txt":"为促进民办非企业单位健康发展，保障民办非企业单位的合法权益，加强对民办非企业单位的规范管理，根据《民办非企业单位登记管理暂行条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"民办非企业单位年度检查（以下简称年检），是指登记管理机关对民办非企业单位，依法按年度进行检查和监督管理的制度。"},{"i":3,"n":"第三条","txt":"经登记管理机关核准登记的民办非企业单位，应当按照本办法的规定，接受登记管理机关的年检。 截至上年度12月31日，成立登记时间未超过6个月的民办非企业单位，不参加当年的年检。"},{"i":4,"n":"第四条","txt":"民办非企业单位年检的程序是： （一）民办非企业单位领取或从互联网下载《民办非企业单位年检报告书》及其他有关材料； （二）民办非企业单位于每年3月31日前向业务主管单位报送年检材料，经业务主管单位出具初审意见后，于5月31日前报送登记管理机关； （三）登记管理机关审查年检材料； （四）登记管理机关作出年检结论，发布年检结论公告。"},{"i":5,"n":"第五条","txt":"民办非企业单位接受年检时，应当提交下列材料： （一）已填具的《民办非企业单位年检报告书》； （二）《民办非企业单位登记证书》副本； （三）财务会计报告； （四）其他需要提交的有关材料。 已经取得执业许可证的民办非企业单位，应当提交执业许可证副本。 登记管理机关在年检期间，可以根据情况，要求民办非企业单位提交注册会计师审计报告、其他补充说明材料及有关文件。登记管理机关可以要求有关人员说明情况，必要时进行实地检查。"},{"i":6,"n":"第六条","txt":"年检的主要内容包括： （一）遵守法律法规和国家政策情况； （二）登记事项变动及履行登记手续情况； （三）按照章程开展活动情况； （四）财务状况、资金来源和使用情况； （五）机构变动和人员聘用情况； （六）其他需要检查的情况。"},{"i":7,"n":"第七条","txt":"民办非企业单位年检结论，分为“年检合格”、“年检基本合格”和“年检不合格”三种。 年检结束，登记管理机关应当在《民办非企业单位登记证书》（副本）上加盖年检结论戳记。民办非企业单位更换登记证书，应当保留原有年检记录。"},{"i":8,"n":"第八条","txt":"民办非企业单位有下列情形之一，由登记管理机关责令改正，情节轻微的，确定为“年检基本合格”；情节严重的，确定为“年检不合格”： （一）违反国家法律、法规和有关政策规定的； （二）违反规定使用登记证书、印章或者财务凭证的； （三）本年度未开展业务活动，或者不按照章程的规定进行活动的； （四）无固定住所或必要的活动场所的； （五）内部管理混乱，不能正常开展活动的； （六）拒不接受或者不按照规定接受登记管理机关监督检 查或年检的； （七）不按照规定办理变更登记，修改章程未按规定核准备案的； （八）设立分支机构的； （九）财务制度不健全，资金来源和使用违反有关规定的； （十）现有净资产低于国家有关行业主管部门规定的最低标准的； （十一）侵占、私分、挪用民办非企业单位的资产或者所接受的捐赠、资助的； （十二）违反国家有关规定收取费用、筹集资金或者接受使用捐赠、资助的； （十三）年检中隐瞒真实情况，"},{"i":9,"n":"第九条","txt":"“年检基本合格”和“年检不合格”的民办非企业单位，应当进行整改，整改期限为3个月。整改期结束，民办非企业单位应当向登记管理机关报送整改报告，登记管理机关对整改结果进行评定并出具意见。 对“年检不合格”的民办非企业单位，登记管理机关根据情况，可以责令其在整改期间停止活动。民办非企业单位被限 期停止活动的，登记管理机关可以封存其登记证书、印章和财 务凭证。"},{"i":10,"n":"第十条","txt":"登记管理机关对连续两年不参加年检，或连续两年“年检不合格”的民办非企业单位，予以撤销登记并公告。"},{"i":11,"n":"第十一条","txt":"登记管理机关实施停止活动、撤销登记行政处罚的，应当按照有关法律、法规的规定办理。"},{"i":12,"n":"第十二条","txt":"登记管理机关工作人员在年检工作中，应当依法行政，不得滥用职权、徇私舞弊。"},{"i":13,"n":"第十三条","txt":"《民办非企业单位年检报告书》格式，由国务院民政部门制订。"},{"i":14,"n":"第十四条","txt":"登记管理机关可以采取网上年检的方式，对民办非企业单位进行年检。"},{"i":15,"n":"第十五条","txt":"各省、自治区、直辖市登记管理机关可以根据实际情况，制定本地区民办非企业单位年检实施办法。"},{"i":16,"n":"第十六条","txt":"本办法自2005年6月1日起施行。"}],"minbanfeiqiyedanweidengjizanxingbanfa":[{"i":1,"n":"第一条","txt":"根据《民办非企业单位登记管理暂行条例》（以下简称条例）制定本办法。"},{"i":2,"n":"第二条","txt":"民办非企业单位根据其依法承担民事责任的不同方式分为民办非企业单位（法人）、民办非企业单位（合伙）和民办非企业单位（个体）三种。 个人出资且担任民办非企业单位负责人的，可申请办理民办非企业单位（个体）登记；两人或两人以上合伙举办的，可申请办理民办非企业单位（合伙）登记； 两人或两人以上举办且具备法人条件的，可申请办理民办非企业单位（法人）登记。 由企业事业单位、社会团体和其他社会力量举办的或由上述组织与个人共同举办的，应当申请民办非企业单位（法人）登记。"},{"i":3,"n":"第三条","txt":"民办非企业单位登记管理机关（以下简称登记管理机关）审核登记的程序是受理、审查、核准、发证、公告。 （一）受理。申请登记的举办者所提交的文件、证件和填报的登记申请表齐全、有效后，方可受理。 （二）审查。审查提交的文件、证件和填报的登记申请的真实性、合法性、有效性，并核实有关登记事项和条件。 （三）核准。经审查和核实后，作出准予登记或者不予登记的决定，并及时通知申请登记的单位或个人。 （四）发证。对核准登记的民办非企业单位，分别颁发有关证书，并办理领证签字手续。 （五）公告。对核准登记的民办非企业单位，由登记管理机关发布公告。"},{"i":4,"n":"第四条","txt":"举办民办非企业单位，应按照下列所属行（事）业申请登记： （一）教育事业，如民办幼儿园，民办小学、中学、学校、学院、大学，民办专修（进修）学院或学校，民办培训（补习）学校或中心等； （二）卫生事业，如民办门诊部（所）、医院，民办健康、保健、卫生、疗养院（所）等； （三）文化事业，如民办艺术表演团体、文化馆（活动中心）、图书馆（室）、博物馆（院）、美术馆、画院、名人纪念馆、收藏馆、艺术研究院（所）等； （四）科技事业，如民办科学研究院（所、中心），民办科技传播或普及中心、科技服务中心、技术评估所（中心）等； （五）体育事业，如民办体育俱乐部，民办体育场、馆、院、社、学校等； （六）劳动事业，如民办职业培训学校中心，民办职业介绍所等； （七）民政事业，如民办福利院、敬老院、托老所、老年公寓，民办婚姻介绍所，民办社区服务中心（站）等； （八）社会中介服务业，如民办评估咨询服务中心（所），民办信"},{"i":5,"n":"第五条","txt":"申请登记民办非企业单位，应当具备条例第八条规定的条件。 民办非企业单位的名称，必须符合国务院民政部门制订的《民办非企业单位名称管理暂行规定》。 民办非企业单位必须拥有与其业务活动相适应的合法财产，且其合法财产中的非国有资产份额不得低于总财产的三分之二。开办资金必须达到本行（事）业所规定的最低限额。"},{"i":6,"n":"第六条","txt":"申请民办非企业单位成立登记，举办者应当提交条例第九条规定的文件。 民办非企业单位的登记申请书应当包括：举办者单位名称或申请人姓名；拟任法定代表人或单位负责人的基本情况；住所情况；开办资金情况；申请登记理由等。 业务主管单位的批准文件，应当包括对举办者章程草案、资金情况（特别是资产的非国有性）、拟任法定代表人或单位负责人基本情况、从业人员资格、场所设备、组织机构等内容的审查结论。 民办非企业单位的活动场所须有产权证明或一年期以上的使用权证明。 民办非企业单位的验资报告应由会计师事务所或其他有验资资格的机构出具。 拟任法定代表人或单位负责人的基本情况应当包括姓名、性别、民族、年龄、目前人事关系所在单位、有否受到剥夺政治权利的刑事处罚、个人简历等。拟任法定代表人或单位负责人的身份证明为身份证的复印件，登记管理机关认为必要时可验证身份证原件。 对合伙制的民办非企业单位，拟任单位负责人指所有合伙"},{"i":7,"n":"第七条","txt":"民办非企业单位的登记事项为：名称、住所、宗旨和业务范围、法定代表人或者单位负责人、开办资金、业务主管单位。 住所是指民办非企业单位的办公场所，须按所在市、县、乡（镇）及街道门牌号码的详细地址登记。 宗旨和业务范围必须符合法律法规及政策规定。 开办资金应当与实有资金相一致。 业务主管单位应登记其全称。"},{"i":8,"n":"第八条","txt":"经审核准予登记的，登记管理机关应当书面通知民办非企业单位，并根据其依法承担民事责任的不同方式，分别发给《民办非企业单位（法人）登记证书》《民办非企业单位（合伙）登记证书》或《民办非企业单位（个体）登记证书》。对不予登记的，登记管理机关应当书面通知申请单位或个人。 民办非企业单位可凭据登记证书依照有关规定办理组织机构代码和税务登记、刻制印章、开立银行帐户，在核准的业务范围内开展活动。"},{"i":9,"n":"第九条","txt":"按照条例第十二条第二款的规定，应当简化登记手续的民办非企业单位，办理登记时，应向登记管理机关提交下列文件： （一）登记申请书； （二）章程草案； （三）拟任法定代表人或单位负责人的基本情况、身份证明； （四）业务主管单位出具的执业许可证明文件。"},{"i":10,"n":"第十条","txt":"条例施行前已经成立的民办非企业单位，应当依照条例及本办法的规定办理申请登记。 已在各级人民政府的编制部门或工商行政管理部门注册登记的民办非企业单位办理补办登记手续，还应向登记管理机关提交编制部门或工商行政管理部门准予注销的证明文件。"},{"i":11,"n":"第十一条","txt":"民办非企业单位根据条例第十五条规定申请变更登记事项时，应向登记管理机关提交下列文件： （一）法定代表人或单位负责人签署并加盖公章的变更登记申请书。申请书应载明变更的理由，并附决定变更时依照章程履行程序的原始纪要，法定代表人或单位负责人因故不能签署变更登记申请书的，申请单位还应提交不能签署的理由的文件； （二）业务主管单位对变更登记事项审查同意文件； （三）登记管理机关要求提交的其他文件。"},{"i":12,"n":"第十二条","txt":"民办非企业单位的住所、业务范围、法定代表人或单位负责人、开办资金、业务主管单位发生变更的，除向登记管理机关提交本办法第十一条规定的文件外，还须分别提交下列材料：变更后新住所的产权或使用权证明；变更后的业务范围；变更后法定代表人或单位负责人的身份证明，及本办法第六条第六款涉及的其他材料；变更后的验资报告；原业务主管单位不再承担业务主管的文件。"},{"i":13,"n":"第十三条","txt":"登记管理机关核准变更登记的，民办非企业单位应交回民办非企业单位登记证书正副本，由登记管理机关换发新的登记证书。"},{"i":14,"n":"第十四条","txt":"民办非企业单位修改章程或合伙协议的，应当报原登记管理机关核准。报请核准时，应提交下列文件： （一）法定代表人或单位负责人签署并加盖公章的核准申请书； （二）业务主管单位审查同意的文件； （三）章程或合伙协议的修改说明及修改后的章程或合伙协议； （四）有关的文件材料。"},{"i":15,"n":"第十五条","txt":"民办非企业单位变更业务主管单位，须在原业务主管单位出具不再担任业务主管的文件之日起90日内找到新的业务主管单位，并到登记管理机关申请变更登记。 在登记管理机关作出准予变更登记决定之前，原业务主管单位应继续履行条例第二十条规定的监督管理职责。"},{"i":16,"n":"第十六条","txt":"登记管理机关应在收到民办非企业单位申请变更登记的全部有效文件后，在法定期限内作出准予变更或不准予变更的决定，并书面通知民办非企业单位。"},{"i":17,"n":"第十七条","txt":"民办非企业单位有下列情况之一的，必须申请注销登记： （一）章程规定的解散事由出现； （二）不再具备条例第八条规定条件的； （三）宗旨发生根本变化的； （四）由于其他变更原因，出现与原登记管理机关管辖范围不一致的； （五）作为分立母体的民办非企业单位因分立而解散的； （六）作为合并源的民办非企业单位因合并而解散的； （七）民办非企业单位原业务主管单位不再担当其业务主管单位，且在90日内找不到新的业务主管单位的； （八）有关行政管理机关根据法律、行政法规规定认为需要注销的； （九）其他原因需要解散的。 属于本条第一款第七项规定的情形，民办非企业单位的原业务主管单位须继续履行职责，至民办非企业单位完成注销登记。"},{"i":18,"n":"第十八条","txt":"民办非企业单位根据条例第十六条的规定申请注销登记时，应向登记管理机关提交下列文件： （一）法定代表人或单位负责人签署并加盖单位公章的注销登记申请书，法定代表人或单位负责人因故不能签署的，还应提交不能签署的理由的文件； （二）业务主管单位审查同意的文件； （三）清算组织提出的清算报告； （四）民办非企业单位登记证书（正、副本）； （五）民办非企业单位的印章和财务凭证； （六）登记管理机关认为需要提交的其他文件。"},{"i":19,"n":"第十九条","txt":"登记管理机关应在收到民办非企业单位申请注销登记的全部有效文件后，在法定期限内作出准予注销或不准予注销的决定，并书面通知民办非企业单位。 登记管理机关准予注销登记的，应发给民办非企业单位注销证明文件。"},{"i":20,"n":"第二十条","txt":"民办非企业单位登记公告分为成立登记公告、注销登记公告和变更登记公告。 登记管理机关发布的公告须刊登在公开发行的、发行范围覆盖同级政府所辖行政区域的报刊上。"},{"i":21,"n":"第二十一条","txt":"成立登记公告的内容包括：名称、住所、法定代表人或单位负责人、开办资金、宗旨和业务范围、业务主管单位、登记时间、登记证号。"},{"i":22,"n":"第二十二条","txt":"变更登记公告的内容除变更事项外，还应包括名称、登记证号、变更时间。"},{"i":23,"n":"第二十三条","txt":"注销登记公告的内容包括名称、住所、法定代表人或单位负责人、登记证号、业务主管单位、注销时间。"},{"i":24,"n":"第二十四条","txt":"民办非企业单位登记证书分为正本和副本，正本和副本具有同等法律效力。 民办非企业单位登记证书的正本应当悬挂于民办非企业单位住所的醒目位置。 民办非企业单位登记证书副本的有效期为4年。"},{"i":25,"n":"第二十五条","txt":"民办非企业单位登记证书遗失的，应当及时在公开发行的报刊上声明作废，并到登记管理机关申请办理补发证书手续。"},{"i":26,"n":"第二十六条","txt":"民办非企业单位申请补发登记证书，应当向登记管理机关提交下列文件： （一）补发登记证书申请书； （二）在报刊上刊登的原登记证书作废的声明。"},{"i":27,"n":"第二十七条","txt":"经核准登记的民办非企业单位开立银行帐户，应按照民政部、中国人民银行联合发布的《关于民办非企业单位开立银行帐户有关问题的通知》的有关规定办理。"},{"i":28,"n":"第二十八条","txt":"经核准登记的民办非企业单位刻制印章，应按照民政部、公安部联合发布的《民办非企业单位印章管理规定》的有关规定办理。"},{"i":29,"n":"第二十九条","txt":"本办法自发布之日起施行。"}],"minzhengxinfanggongzuobanfa":[{"i":1,"n":"第一条","txt":"为了加强民政信访工作，保护信访人的合法权益，维护信访秩序，促进社会和谐稳定，根据《信访条例》和国家有关规定，结合民政工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称信访，是指公民、法人或者其他组织采取书信、电话、走访、电子邮件、传真等形式，向民政部门反映情况，提出建议、意见或者投诉请求，依法由民政部门处理的活动。"},{"i":3,"n":"第三条","txt":"民政信访工作遵循下列原则： （一）属地管理、分级负责； （二）依法处理与疏导教育相结合。"},{"i":4,"n":"第四条","txt":"各级民政部门应当成立民政信访工作领导小组，建立统一领导，各负其责、分工协作、齐抓共管的信访工作格局。 各级民政部门负责人应当阅批重要来信、接待重要来访、定期听取信访工作汇报，研究解决信访工作中的突出问题。"},{"i":5,"n":"第五条","txt":"各级民政部门应当完善依法、科学、民主决策机制、重大决策社会风险评估机制、信访问题排查化解机制、信访督办工作机制，从源头上减少和预防社会矛盾的发生，及时将矛盾纠纷化解在基层。"},{"i":6,"n":"第六条","txt":"各级民政部门应当强化对信访工作的考核，实行信访工作责任制，对信访工作中失职、渎职行为，依法追究有关责任人员的责任；对在信访工作中做出突出成绩的单位和个人给予奖励。"},{"i":7,"n":"第七条","txt":"各级民政部门的信访工作机构负责落实信访工作领导小组布置的各项任务，承办日常信访工作。 地方各级民政部门在本级人民政府领导和上级民政部门指导下开展信访工作。 信访接待场所应当设置无障碍设施，方便残疾人、老年人进行信访活动。"},{"i":8,"n":"第八条","txt":"各级民政部门内设机构应当按业务分工承办职权范围内的信访事宜。对本部门信访工作机构转办的信访事项，应当认真、及时办理，并在规定时限内回复办理结果。"},{"i":9,"n":"第九条","txt":"民政信访工作机构履行下列职责： （一）受理信访人提出的信访事项； （二）向信访人宣传有关法律、法规、规章和政策，提供有关信访事项的咨询服务； （三）向本级民政部门有关内设机构、下级民政部门转送、交办信访事项； （四）承办上级民政部门和本级人民政府交办处理的信访事项； （五）督促检查、协调信访事项的处理和落实情况； （六）研究、分析信访情况，及时提出完善政策或者改进工作的建议； （七）总结交流信访工作经验，指导下级民政部门的信访工作； （八）向本级民政部门和上一级民政部门定期报送信访情况分析统计报告。"},{"i":10,"n":"第十条","txt":"民政信访工作人员遵守下列规定： （一）尊重信访人，不得刁难、歧视信访人； （二）恪尽职守，秉公办事，依法及时处理信访事项，不得推诿、敷衍、拖延； （三）妥善保管信访材料，不得丢失、隐匿或者擅自销毁； （四）遵守保密制度，不得将信访人的检举、揭发材料及有关情况透露或者转给被检举、揭发的人员或者单位； （五）与信访事项或者信访人有直接利害关系的，应当回避。"},{"i":11,"n":"第十一条","txt":"各级民政部门应当重视对信访干部的培养、使用和交流。 民政信访工作人员享受本级人民政府的信访岗位津贴。"},{"i":12,"n":"第十二条","txt":"民政部门应当在信访接待场所、本部门网站或者通过其他方式向社会公布下列事项： （一）信访工作机构的通信地址、电子信箱、投诉电话、信访接待的时间和地点； （二）本部门信访事项受理范围； （三）与民政信访工作有关的法律、法规、规章和信访事项的处理程序； （四）查询信访事项处理进展及结果的方式； （五）其他为信访人提供便利的相关事项。"},{"i":13,"n":"第十三条","txt":"建立设区的市、县两级人民政府民政部门负责人信访接待日制度，协调解决相关信访问题；对信访人反映的突出问题，可以约访信访人，并协调解决相关信访问题。"},{"i":14,"n":"第十四条","txt":"各级民政部门应当定期下访，听取群众的意见和建议，建立健全民政舆情汇集和分析机制。"},{"i":15,"n":"第十五条","txt":"各级民政部门应当充分利用现有政务信息网络资源，提高信访工作信息化水平，为信访人在当地提出信访事项、查询信访事项办理情况提供便利。"},{"i":16,"n":"第十六条","txt":"各级民政部门应当建立有利于迅速解决矛盾纠纷的工作机制，可以邀请相关社会工作服务机构、法律援助机构等参与信访工作。"},{"i":17,"n":"第十七条","txt":"民政信访工作机构收到信访事项后，应当进行登记。 登记内容包括：登记号、登记人、信访人姓名、性别、住址、收到信访事项的日期、信访事项摘要、联系方式。"},{"i":18,"n":"第十八条","txt":"民政信访工作的受理范围根据同级人民政府规定的工作职能确定。 民政信访工作机构对信访事项，按下列方式处理： （一）属于本级民政部门工作职能范围的信访事项，应当直接受理，并根据所反映问题的性质、内容确定办理机构。 （二）信访事项涉及下级民政部门的，应当转下级民政部门办理。对其中的重要信访事项，可以向下级民政部门进行交办，要求其在规定的期限内反馈结果，并提交办结报告。 （三）属于本级民政部门所属单位办理的信访事项，应当转送或者交办相关单位办理。 （四）已经或者依法应当通过诉讼、仲裁、行政复议等法定途径解决的信访事项，应当告知信访人依照有关法律、行政法规规定的程序向有关机关提出。 （五）依法不属于民政部门业务范围的事项，应当口头或者书面告知信访人向有权处理的人民政府或者部门提出。"},{"i":19,"n":"第十九条","txt":"民政信访工作机构能够当场受理信访事项的，应当当场受理并出具受理通知；不能当场受理的，应当自收到信访事项之日起15日内决定是否受理并书面告知信访人。对重复信访、信访人的姓名（名称）、住址不清楚的除外。"},{"i":20,"n":"第二十条","txt":"民政信访工作机构应当建立信访事项处理预案。对可能造成社会影响的重大、紧急信访事项和信访信息，应及时向本级人民政府和上级民政部门报告，并在职责范围内采取措施，果断处理，防止不良影响的发生、扩大。"},{"i":21,"n":"第二十一条","txt":"各级民政部门对其办理的信访事项，应当依照国务院《信访条例》第三十二条的有关规定作出信访处理意见，并书面答复信访人。"},{"i":22,"n":"第二十二条","txt":"民政信访工作机构对于以下情形，分别按照下列方式处理： （一）信访事项已经解决并且信访人接受办理结果，经信访人签字同意，可以视同书面答复； （二）多人提出共同信访事项的，可以对代表人作出答复； （三）咨询及建议、意见类信访事项，可以口头或者书面答复。"},{"i":23,"n":"第二十三条","txt":"信访事项应当自受理之日起60日内办结；情况复杂的，经本级民政部门负责人批准，可以适当延长办结期限，但延长期限不得超过30日，并应当告知信访人延期理由。"},{"i":24,"n":"第二十四条","txt":"信访人对民政部门作出的信访事项处理意见不服的，可以依照《信访条例》和国务院有关规定申请复查或者复核。 收到复查或者复核请求的民政部门应当自收到复查或者复核请求之日起30日内提出复查或者复核意见，并书面答复信访人。 信访事项的办理、复查意见作出后，信访人无正当理由未在规定期限内提出复查、复核申请的，或者信访人对复核意见不服，仍以同一事实和理由提出投诉请求的，各级民政部门不再受理。"},{"i":25,"n":"第二十五条","txt":"下级民政部门有下列情况之一的，上级民政部门应当督办，并提出改进建议： （一）应当受理而拒不受理信访事项的； （二）未按规定的办理期限办结信访事项的； （三）未按规定程序办理信访事项的； （四）未按规定反馈重要信访事项办理结果的； （五）办理信访事项推诿、敷衍、拖延的； （六）不执行信访处理意见或者复查、复核意见的； （七）其他需要督办的情形。 收到督办意见和建议的机构应当在30日内书面反馈情况；未采纳督办意见和建议的，应当说明理由。"},{"i":26,"n":"第二十六条","txt":"下级民政部门及其人员在信访工作中有推诿、敷衍、拖延、弄虚作假以及无正当理由拒不接受督办意见和建议等行为，造成严重后果的，上级民政部门可以依法建议有关部门对直接负责的主管人员和其他直接责任人员给予行政处分。"},{"i":27,"n":"第二十七条","txt":"信访工作人员在信访接待场所发现信访人不遵守信访秩序，在信访过程中采取过激行为的，应当进行劝阻、批评或者教育；对拒不听从劝阻，可能导致事态扩大的，及时报请公安机关依法进行处置。"},{"i":28,"n":"第二十八条","txt":"在信访事项办理过程中形成的文件、材料由信访工作机构按照档案管理的有关规定统一归档。"},{"i":29,"n":"第二十九条","txt":"本办法自2011年9月1日起施行。1999年12月23日民政部发布的《民政信访工作办法》同时废止。"}],"minzhengbugonganbuwaijiaobutiedaobujiaotongbuweish263ca2":[],"minzhengbulifagongzuoguiding":[{"i":1,"n":"第一条","txt":"为了规范民政部立法工作，提高立法工作科学化水平，根据《中华人民共和国立法法》、《行政法规制定程序条例》、《规章制定程序条例》、《法规规章备案条例》等有关规定，结合民政工作实际，制定本规定。"},{"i":2,"n":"第二条","txt":"民政部代行起草法律草案、行政法规草案，制定、修改和废止部门规章，适用本规定。 法律草案、行政法规草案和部门规章草案在本规定中统称为法规草案。"},{"i":3,"n":"第三条","txt":"民政部立法工作应当符合国家立法制度，依照法定的权限和程序，坚持从实际出发，反映经济社会发展要求，体现人民意愿，维护社会主义法制的统一和尊严。"},{"i":4,"n":"第四条","txt":"部政策法规司依照本规定组织、协调民政部立法工作，负责编制并督促实施立法规划和计划，组织立法协调，审查法规草案并提请部务会议讨论审议，办理其他立法工作。 部其他司（局）依照本规定，在各自职责范围内负责相关的立法工作。"},{"i":5,"n":"第五条","txt":"民政部根据民政事业发展的实际需要编制立法规划，通过制定年度立法计划逐步实施。 编制立法规划，应当依据全国人大、国务院立法工作安排和部工作部署，由政策法规司对各司（局）提出的立法建议汇总后研究拟定，提请部务会议审议。 制定年度立法计划，应当结合上一年度部立法计划完成情况，由政策法规司对司（局）提出的立法建议汇总后研究拟定，提请部长办公会议审议。"},{"i":6,"n":"第六条","txt":"编制立法规划和制定年度立法计划，应当遵循突出重点与统筹兼顾相结合的原则，坚持立、改、废并举。 立法项目需要提请列入全国人大常委会立法规划或者国务院立法工作计划的，由政策法规司按照有关规定办理。"},{"i":7,"n":"第七条","txt":"司（局）提出立法建议，应当包括立法项目名称、制定必要性、制定依据、拟确立的主要制度、报送时间和起草司（局）等内容。"},{"i":8,"n":"第八条","txt":"年度立法计划在实施过程中，可以根据实际情况进行调整。 调整年度立法计划，相关司（局）应当提出书面建议，由政策法规司组织论证，经分管业务工作和法制工作的部领导审核后报部长批准实施。"},{"i":9,"n":"第九条","txt":"列入年度立法计划的立法项目由计划明确分工的司（局）负责起草。有两个以上司（局）的，排在首位的为主办司（局），其他为会办司（局）。 根据工作需要，法规草案也可以由政策法规司起草或者组织起草。"},{"i":10,"n":"第十条","txt":"起草法规草案，应当成立起草工作小组，制定工作方案，确定一名司（局）负责同志为负责人，落实起草人员、起草任务、完成时间、保障措施等。 起草法律草案、行政法规草案，政策法规司应当派员参加起草工作小组。"},{"i":11,"n":"第十一条","txt":"起草法规草案，可以邀请部属事业单位、社会组织及有关专家学者参加，也可以委托部属事业单位、社会组织及其他机构起草。"},{"i":12,"n":"第十二条","txt":"起草法规草案，应当深入调查研究，借鉴国内外立法实践经验，充分听取各级民政部门的意见和建议。"},{"i":13,"n":"第十三条","txt":"起草法规草案，应当就涉及其他部门职责、职权的事项，同相关部门充分沟通协商。经沟通协商未能取得一致意见的，应当在报送法规草案时对有关情况作出说明。"},{"i":14,"n":"第十四条","txt":"起草法规草案，应当对现行相关法规进行清理。对同一事项，如果需要作出与现行法规不一致的规定，应当在草案中作出废止或者如何适用现行法规的规定，并在报送法规草案时说明情况和理由。"},{"i":15,"n":"第十五条","txt":"起草法规草案，应当广泛听取社会意见。听取意见可以采取召开会议、网上征询、书面征求意见等多种形式进行。 拟确立涉及公众权益、社会关注度高的制度，应当进行社会风险评估。拟设定行政许可、行政强制等规定的，应当符合相关法律规定。"},{"i":16,"n":"第十六条","txt":"法规草案起草完成后，起草司（局）应当将法规草案文本及说明材料报送政策法规司审查。 说明材料应当重点说明立法的必要性，草案所规范领域的实际情况、存在的主要问题，确立的主要制度和措施，有关方面的意见及处理情况，国外立法实践等内容。 报送审查的法规草案文本及说明材料，应当由起草司（局）主要负责人签署；司（局）共同起草的，应当由主要负责人共同签署。"},{"i":17,"n":"第十七条","txt":"政策法规司主要从以下方面对法规草案进行审查： （一）是否符合法定权限和程序； （二）是否符合国家的方针政策和重大决策； （三）是否与有关法规相协调、衔接； （四）是否妥善处理和协调有关机关、组织和公民对法规草案的意见； （五）是否符合立法技术要求； （六）需要审查的其他内容。"},{"i":18,"n":"第十八条","txt":"报送审查的法规草案有下列情形之一的，政策法规司可以缓办或者退回起草司（局）： （一）立法基本条件尚不成熟的； （二）确立的主要制度和措施存在较大争议，起草司（局）未沟通协商的； （三）不符合本规定第十六条规定的。 对法规草案作出缓办或者退回处理的，政策法规司应当书面告知起草司（局），说明理由并提出工作建议。"},{"i":19,"n":"第十九条","txt":"在审查过程中，政策法规司应当开展下列工作： （一）就法规草案涉及的主要问题发送有关部门、组织和专家书面征求意见； （二）就法规草案涉及的主要问题深入基层进行实地调研，听取基层有关机关、组织和公民意见； （三）就法规草案涉及的重大问题，召开有关单位、专家参加的座谈会、论证会，听取意见，研究论证； （四）对立法中的不同意见进行协调。 对立法中存在重大不同意见的问题，政策法规司应当主动与全国人大相关专门委员会和全国人大常委会法工委以及国务院法制机构沟通，听取意见。 对经协调仍达不成一致意见的，要列明各方理据，提出并报请部领导明确倾向性意见。"},{"i":20,"n":"第二十条","txt":"除依法需要保密的外，规章草案都要公开征求意见。具体由政策法规司依照有关规定办理。"},{"i":21,"n":"第二十一条","txt":"根据审查情况，政策法规司应当会同起草司（局）对报送审查的法规草案及草案说明进行修改。 政策法规司对法规草案予以审查修改，经分管法制工作的部领导审核并报部长确定后，提请部务会议讨论或者审议。"},{"i":22,"n":"第二十二条","txt":"部务会议讨论法律草案、行政法规草案，审议规章草案，由政策法规司作起草说明，起草司（局）作补充说明。 根据部务会议所提意见，政策法规司应当会同起草司(局)对法规草案进行修改，并按照相关程序报请审定。"},{"i":23,"n":"第二十三条","txt":"部务会议讨论后决定上报国务院的法律草案、行政法规草案，以民政部名义发文，由部长签署。"},{"i":24,"n":"第二十四条","txt":"部务会议审议通过的规章草案，由部长签署命令公布。部门联合规章由联合制定的部门首长共同署名公布，使用主办机关的命令序号。 规章公布前需要报请国务院批准的，由政策法规司按照相关规定办理。"},{"i":25,"n":"第二十五条","txt":"规章公布后，民政部网站、《民政部文告》应当及时全文刊登。需要发布新闻消息的，由民政部新闻发言人发布。 《民政部文告》上刊登的规章文本为标准文本。"},{"i":26,"n":"第二十六条","txt":"使用民政部命令序号的规章，由政策法规司按照《法规规章备案条例》的规定，统一向国务院备案。"},{"i":27,"n":"第二十七条","txt":"使用民政部命令序号的规章由民政部负责解释。 规章的解释由原起草司（局）起草，送政策法规司审查，经分管法制工作的部领导审核并报部长确定后，提请部务会议审议。 联合规章的解释参照本规定执行。 规章解释与规章具有同等效力。"},{"i":28,"n":"第二十八条","txt":"使用民政部命令序号的规章实施后，由民政部负责对执行情况、实施效果开展评估。 规章的评估由政策法规司组织实施，相关司（局）按照职责做好配合工作。 联合规章的评估参照本规定执行。"},{"i":29,"n":"第二十九条","txt":"使用民政部命令序号的规章由民政部负责清理，根据清理情况及时作出修改、废止等相应处理。 规章的清理由原起草司（局）组织实施，政策法规司做好配合工作。集中清理按照国务院的相关规定由部统一部署。 规章清理结果应当提请部务会议审议。清理后继续有效、废止和失效的规章目录应当向社会公布。"},{"i":30,"n":"第三十条","txt":"由民政部负责起草的法律、行政法规，全国人大常委会、国务院要求提出解释意见或者民政部主动提出解释建议的，参照规章解释的程序办理。"},{"i":31,"n":"第三十一条","txt":"其他部门起草的法规草案征求民政部意见的，由政策法规司归口办理，有关司（局）应当积极配合，依照职责及时回复意见。"},{"i":32,"n":"第三十二条","txt":"部领导列席全国人大及其常务委员会、国务院有关会议讨论或者审议法律草案、行政法规草案，由政策法规司会同有关司（局）按时限要求准备以下材料： （一）该草案过去的办理情况及相关材料； （二）民政部对该草案反馈的修改意见； （三）其他与该草案相关的材料。"},{"i":33,"n":"第三十三条","txt":"使用民政部命令序号的规章需要翻译外文译本的，由政策法规司组织翻译，原起草司（局）、部国际合作司予以协助，按照相关规定报国务院法制机构审定。"},{"i":34,"n":"第三十四条","txt":"政策法规司依照《法规汇编编辑出版管理规定》，对涉及民政行政管理工作的法律、行政法规和规章进行汇编。"},{"i":35,"n":"第三十五条","txt":"规范性文件的制发按照《民政部规范性文件制定与审查办法》执行。"},{"i":36,"n":"第三十六条","txt":"本规定自2014年3月1日起施行。 2005年7月28日印发的《民政部立法工作程序规定》（民办发〔2005〕9号）同时废止。"}],"minzhengbuxingzhengfuyiyuxingzhengyingsubanfa":[{"i":1,"n":"第一条","txt":"为了防止和纠正违法或者不当的行政行为，保护公民、法人和其他组织的合法权益，保障和监督民政行政机关依法行使职权，根据《中华人民共和国行政复议法》，结合民政部行政工作的实际情况，制定本办法。"},{"i":2,"n":"第二条","txt":"民政部受理行政复议申请和组织审理行政复议案件，作出行政复议决定以及行政应诉工作，适用本办法。"},{"i":3,"n":"第三条","txt":"纪检、监察、审计、信访等机构根据有关规定受理的案件或者申诉，不适用本办法。"},{"i":4,"n":"第四条","txt":"公民、法人和其他组织对下列具体行政行为不服可以向民政部申请行政复议： (一)对民政部作出的具体行政行为不服的； (二)对民政部与其他行政机关以共同名义作出的具体行政行为不服的； (三)对法律、法规授权的，由民政部直接主管的组织作出的具体行政行为不服的； (四)对省级人民政府民政部门作出的具体行政行为不服的； (五)法律、法规规定可以向民政部申请行政复议的其他具体行政行为。"},{"i":5,"n":"第五条","txt":"公民、法人和其他组织申请行政复议时，可以同时提出对该具体行政行为所依据的规定的审查申请。"},{"i":6,"n":"第六条","txt":"民政部法规办公室具体办理行政复议与行政应诉事项，其主要职责是： (一)审查行政复议申请； (二)向有关单位和有关人员调查取证、查阅文件和资料； (三)组织审理行政复议案件； (四)拟订行政复议决定，制定行政复议决定书； (五)受部长委托出庭应诉，并具体办理行政应诉有关事宜； (六)组织行政复议和行政应诉工作人员培训； (七)对民政系统的行政复议和行政应诉案件进行调查研究、统计分析。"},{"i":7,"n":"第七条","txt":"各司(局)协助法规办公室具体办理主管业务范围内的行政复议和行政应诉有关事项，主要职责是： (一)对民政部作出的具体行政行为提起的行政复议案件，相关业务司(局)应当自收到行政复议申请书副本之日起10日内，向法规办公室提交作出具体行政行为的有关材料和证据，并提出答辩书； (二)各司(局)负责审查属于本部门主管业务范围内的行政复议申请，并在2日内向法规办公室提出是否受理的初步意见； (三)各司(局)负责审理属于本部门主管业务范围内的行政复议案件，并提出行政复议初审意见书； (四)因民政部作出的具体行政行为而引起的行政诉讼案件和经行政复议予以维持而申请人不服引起的行政诉讼案件的应诉工作，相关业务司(局)有关人员作为民政部诉讼代理人出庭应诉。"},{"i":8,"n":"第八条","txt":"公民、法人和其他组织向民政部申请行政复议，应当自知道具体行政行为之日起60日内提出，但是法律规定的申请期限超过60日的除外。 因不可抗力或者其他正当理由耽误法定申请期限的，申请期限自障碍消除之日起继续计算。"},{"i":9,"n":"第九条","txt":"当事人口头申请行政复议，法规办公室应当制作行政复议申请笔录，申请人确认无误后，应当在笔录上签名或者盖章。"},{"i":10,"n":"第十条","txt":"民政部应当自收到行政复议申请之日起5日内，对行政复议申请进行审查，决定是否受理。"},{"i":11,"n":"第十一条","txt":"行政复议申请具有下列情形之一的，不予受理，并制作《行政复议不予受理决定书》送达申请人，《行政复议不予受理决定书》应当载明不予受理的理由。 (一)行政复议申请超过法定申请期限，无正当理由的； (二)没有明确的被申请人的； (三)没有具体的行政复议请求和事实根据的； (四)不属于申请行政复议范围的； (五)不属于民政部受理的； (六)申请人已经向人民法院起诉，人民法院已经受理的； (七)申请人已经向其他有权受理的行政机关申请行政复议的。 对于前款第(四)项不予受理的，应当告知申请人到有关机关申诉；对于前款第(五)项不予受理的，应当告知申请人到有权受理的行政机关申请复议。"},{"i":12,"n":"第十二条","txt":"行政复议原则上采用书面审查的办法。但有下列情形之一的，法规办公室可以决定采取其他方式审理行政复议案件： (一)主要事实不清，当事人双方争议较大的； (二)当事人一方或者双方要求到民政部当面说明问题或者情况的； (三)案情重大、影响面广或者书面行政复议不能有效解决行政纠纷的其他情形。"},{"i":13,"n":"第十三条","txt":"民政部应当自受理之日起7日内将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。被申请人应当自收到申请书副本或者申请笔录复印件之日起10日内，向民政部提交作出具体行政行为的有关证据、依据和其他有关材料，并提出答辩书。逾期不答辩的，不影响行政复议。"},{"i":14,"n":"第十四条","txt":"答辩书应当载明下列内容： (一)被申请人的名称、地址，法定代表人的姓名、职务； (二)作出具体行政行为的事实依据及有关的证据材料； (三)作出具体行政行为所依据的法律、法规、规章和具有普遍约束力的决定、命令； (四)作出答辩的日期。 答辩书应当加盖被申请人的印章。"},{"i":15,"n":"第十五条","txt":"对被申请人作出的具体行政行为，应当审查以下内容： (一)是否超越或者滥用职权； (二)所认定的事实是否清楚，证据是否确凿； (三)适用的依据是否正确； (四)程序是否合法； (五)内容是否适当。"},{"i":16,"n":"第十六条","txt":"申请人同时提出对具体行政行为所依据的规定进行审查的，应当审查规定的内容是否与法律、法规相抵触。 对该规定民政部有权处理的，应当在30日内处理；无权处理的，应当在7日内按法定程序转送有权处理的行政机关处理。处理期间，中止对具体行政行为的审查。"},{"i":17,"n":"第十七条","txt":"法规办公室应当认真审查行政复议材料，有下列情形之一的，应当进行实地调查： (一)案情比较复杂，影响较大的； (二)证据与当事人陈述有较大差异的； (三)可能引起行政诉讼的。"},{"i":18,"n":"第十八条","txt":"行政复议人员进行调查时，应当制作调查笔录，经被调查人确认无误后，由被调查人、调查人签名或者盖章。"},{"i":19,"n":"第十九条","txt":"行政复议决定作出以前，申请人撤回行政复议申请，经说明理由，民政部记录在案，可以撤回。"},{"i":20,"n":"第二十条","txt":"申请人在申请行政复议时一并提出行政赔偿请求的，经审理决定给予当事人赔偿的，赔偿费用由民政部行政经费列支。"},{"i":21,"n":"第二十一条","txt":"行政复议决定书由部长签发；重大、复杂的行政复议案件或者经行政复议拟撤销具体行政行为所依据的规定的案件，行政复议决定应当经部务会议或者部长办公会议讨论通过。"},{"i":22,"n":"第二十二条","txt":"民政部行政诉讼代理人由法规办公室或者有关司(局)推荐，报部长决定。 法规办公室根据部长的决定，为诉讼代理人办理授权委托书。"},{"i":23,"n":"第二十三条","txt":"对民政部作出的具体行政行为直接引起的行政诉讼，相关司(局)应当在收到起诉状副本之日起5日内拟出答辩书，连同作出具体行政行为的有关证据和材料送法规办公室，经审核后，报部长签发。"},{"i":24,"n":"第二十四条","txt":"对民政部作出的具体行政行为经行政复议维持原具体行政行为引起的行政诉讼，适用第二十三条。"},{"i":25,"n":"第二十五条","txt":"对申请人提出的行政复议申请，民政部经行政复议改变或者撤销原具体行政行为，当事人不服又引起的行政诉讼，由法规办公室起草答辩书，报部长签发。"},{"i":26,"n":"第二十六条","txt":"法规办公室应当在收到起诉状副本之日起10日内，将答辩书和有关材料或证据提交人民法院。"},{"i":27,"n":"第二十七条","txt":"民政部送达行政复议决定书，可以直接送交受送达人，也可以委托受送达人所在地的民政部门或者其他组织代为送达，或者邮寄送达。"},{"i":28,"n":"第二十八条","txt":"行政复议案件审理完毕，法规办公室应当将案件文书立卷归档。"},{"i":29,"n":"第二十九条","txt":"民政部法规办公室工作人员在行政复议活动中，徇私舞弊或者有其他渎职、失职行为的，根据情节轻重，依法给予行政处分。 各司(局)有关人员不按本办法规定的期限提出行政复议是否受理意见、提交作出具体行政行为的有关材料和证据，并提出答辩书的，根据情节轻重，依法给予行政处分。"},{"i":30,"n":"第三十条","txt":"民政部受理行政复议申请，不得向申请人收取任何费用。 民政部行政复议与行政应诉活动所需经费，由民政部行政经费列支。"},{"i":31,"n":"第三十一条","txt":"本办法自公布之日起施行。"}],"minzhengbuguifanxingwenjianzhidingyushenchabanfa":[{"i":1,"n":"第一条","txt":"为了全面推进依法行政，加强对民政部规范性文件（以下简称规范性文件）制定和审查工作的管理，根据有关规定，结合本部实际，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称规范性文件，是指民政部制定的部门规章以外的，涉及行政相对人权利义务，具有普遍约束力并且在法定期限内可以反复适用的文件。"},{"i":3,"n":"第三条","txt":"规范性文件的起草、合法性审查、审议、发布、解释、清理、修改和废止等工作，适用本办法。 规范性文件的备案，依据国家有关规定执行。"},{"i":4,"n":"第四条","txt":"制定规范性文件，应当符合法律、行政法规、规章以及国务院决定、命令的规定，应当坚持公开、效能和权责统一原则。"},{"i":5,"n":"第五条","txt":"部办公厅负责规范性文件管理工作；部业务司（局）负责职责范围内的规范性文件的起草、清理等工作，并对规范性文件的解释、修改和废止提出建议；部政策法规司负责规范性文件的合法性审查、备案等工作。"},{"i":6,"n":"第六条","txt":"规范性文件由相关业务司（局）负责起草。涉及部内多个司（局）业务的，由主办司（局）负责组织相关业务司（局）起草。 制定规范性文件需要事先请示国务院同意的，应当报请国务院批准后再起草。"},{"i":7,"n":"第七条","txt":"规范性文件可以用条款形式表述，也可以用段落形式表述。 规范性文件名称可以使用“规定”、“办法”、“细则”、“规则”、“通知”、“意见”等，但不得使用“条例”、“批复”、“报告”。"},{"i":8,"n":"第八条","txt":"起草规范性文件，应当根据内容需要，在规范性文件中明确制定目的和依据、适用范围、适用主体、主要措施、施行日期等内容。 对有特定含义或者特定适用范围的术语，应当在规范性文件中作出界定，指明其特定的、确切的含义。"},{"i":9,"n":"第九条","txt":"规范性文件不得设定下列事项： （一）与法律、行政法规、规章和国务院决定、命令相抵触的事项； （二）行政处罚、行政许可、行政审批、行政强制、行政事业性收费、机构编制以及其他不得由规范性文件创设的事项； （三）违法增加行政相对人义务或者限制行政相对人合法权益的事项； （四）超越民政部职能职权范围的事项。"},{"i":10,"n":"第十条","txt":"起草规范性文件，应当听取社会意见并进行社会风险评估。 听取社会意见可以采取书面征求意见、座谈会、论证会、听证会等形式。涉及公众切身利益，或者社会关注度高的规范性文件，应当向社会公开征求意见。 规范性文件内容涉及国务院其他部门职能范围的，应当征求相关部门意见。"},{"i":11,"n":"第十一条","txt":"起草规范性文件，应当对需要废止的现行规范性文件或者相关条款作出明确规定。"},{"i":12,"n":"第十二条","txt":"规范性文件起草工作完成后，在报请审议前，起草司（局）应当将规范性文件送审稿及其起草说明送政策法规司进行合法性审查。 起草说明，应当包括下列内容： （一）制定该文件的必要性和可行性； （二）所依据的法律、行政法规、规章和有关文件； （三）拟解决的主要问题以及采取的主要措施； （四）征求意见、对分歧意见的协调处理以及社会风险评估等情况； （五）其他需要说明的问题。"},{"i":13,"n":"第十三条","txt":"政策法规司收到规范性文件送审稿后，一般应当在7个工作日内提出审查意见。 合法性审查的内容包括： （一）是否符合法定职权和程序； （二）是否与法律、行政法规、规章和国务院决定、命令相抵触； （三）是否有规范性文件不得创设的内容； （四）是否与民政部现行规范性文件相衔接； （五）其他需要审查的事项。"},{"i":14,"n":"第十四条","txt":"经审查无异议，政策法规司应当作出合法性审查通过的审查意见。 规范性文件送审稿存在重大缺陷或者较大争议，不符合本办法要求的，政策法规司可以作出审查不予通过意见并说明理由和依据。"},{"i":15,"n":"第十五条","txt":"规范性文件应当提交部长办公会议或者部务会议审议。 审议规范性文件，由起草司（局）作说明，政策法规司就合法性审查情况作说明。"},{"i":16,"n":"第十六条","txt":"规范性文件经审议通过后，由起草司（局）正式行文，送政策法规司会签后，按照部公文办理程序报请部长或者部长委托的其他部领导签发。 规范性文件需要送国务院其他部门会签的，或者需要报请国务院批准的，按照相关规定办理。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，经部长批准可以简化制定程序： （一）依据法律、行政法规授权例行调整和发布标准的； （二）执行国务院的紧急命令、决定，需要立即制定和实施规范性文件的； （三）为应对和处置自然灾害等突发事件，需要立即制定和实施规范性文件的。 依照前款规定简化制定程序的，起草司（局）形成规范性文件送审稿，会签政策法规司后直接报请部长签发。"},{"i":18,"n":"第十八条","txt":"规范性文件应当以民政部公告形式发布，经部长批准，也可以其他方式发布。"},{"i":19,"n":"第十九条","txt":"规范性文件自公布之日起施行，也可以确定自公布之日起一定期间后施行。"},{"i":20,"n":"第二十条","txt":"规范性文件的解释，由原起草司（局）负责起草，经政策法规司会签后按照部公文办理程序报请部长签发。 规范性文件解释事关重大的应当提交部长办公会议或者部务会议审议。 规范性文件的解释与规范性文件具有同等效力。"},{"i":21,"n":"第二十一条","txt":"规范性文件的日常清理由起草司（局）负责，集中清理按照国务院的相关规定由部统一部署。 清理后继续有效、废止和失效的规范性文件目录，应当向社会公布。"},{"i":22,"n":"第二十二条","txt":"修改或者废止规范性文件，由原起草司（局）提出，按照规范性文件的制定程序办理。"},{"i":23,"n":"第二十三条","txt":"规范性文件有效期限一般不得超过5年。名称冠以“暂行”、“试行”的，有效期限不超过2年。 规范性文件在有效期届满后，需要继续实施的，应当在有效期届满前进行清理，并向社会公布继续有效的规范性文件目录。"},{"i":24,"n":"第二十四条","txt":"本办法自2011年8月1日起施行。"}],"minzhengbumenshishixingzhengxukebanfa":[{"i":1,"n":"第一条","txt":"为了规范民政部门行政许可实施行为，根据《中华人民共和国行政许可法》及有关法律、法规，结合民政部门实际，制定本办法。"},{"i":2,"n":"第二条","txt":"民政部门实施行政许可，应当遵守《中华人民共和国行政许可法》及有关法律、法规和本办法的规定。"},{"i":3,"n":"第三条","txt":"民政部门实施行政许可，应当按照法定的权限、范围、条件和程序，遵循公开、公平、公正、便民、高效和监督检查的原则。"},{"i":4,"n":"第四条","txt":"民政部门应当在法定职权范围内实施行政许可，也可以依照法律、法规、规章的规定委托其他行政机关实施行政许可；除此之外，不得委托其他组织、法人或公民实施行政许可。"},{"i":5,"n":"第五条","txt":"民政部门实施行政许可，不得在法定条件之外附加任何不正当要求。"},{"i":6,"n":"第六条","txt":"涉及公共利益的重大许可事项，行政许可申请人及利害关系人认为办理行政许可的审查人员或者听证主持人员与行政许可事项有直接利害关系的，有权申请其回避。 办理行政许可的审查人员或者听证主持人员是否回避，由相应民政部门负责人决定。"},{"i":7,"n":"第七条","txt":"民政部门应当将法律、法规、规章规定的有关本部门办理的行政许可事项、依据、条件、数量、程序、期限、收取费用的法定项目和标准，以及需要提交的全部材料的目录和申请书格式文本、示范文本等在办公场所公示。 有条件的民政部门应当通过机关网站或者其他适当方式将前款内容向社会公开，便于申请人查询和办理。 申请人要求对公示或者公开内容予以说明、解释的，办理行政许可事项的工作人员应当说明、解释，提供准确、可靠的信息。 民政部门应当为申请人通过信函、电报、电传、电子数据交换和电子邮件等方式提出行政许可申请提供便利。"},{"i":8,"n":"第八条","txt":"建立服务窗口的民政部门，由该服务窗口负责统一受理行政许可申请、统一送达行政许可决定；没有服务窗口的，具体办理某项行政许可的有关业务机构应当设立专门岗位，负责统一受理行政许可申请，统一送达行政许可决定。"},{"i":9,"n":"第九条","txt":"行政许可申请人依法向民政部门提出行政许可申请，申请书需要采用格式文本的，民政部门应当免费提供申请书格式文本。申请书格式文本中不得包含与申请行政许可事项没有直接关系的内容。 民政部门不得要求申请人提交与其申请的行政许可事项无关的材料。 申请人依法委托代理人提出行政许可申请的，应当提交授权委托书。授权委托书应当载明授权委托事项和授权范围。"},{"i":10,"n":"第十条","txt":"办理行政许可工作人员在收到申请人递交的申请材料后，除依法可以当场作出不予受理决定外，应当即时填写《行政许可申请材料登记表》，将收到行政许可申请时间、申请人、申请事项、提交材料情况等记录在案。 《行政许可申请材料登记表》一式两份，在申请人和承办人签字后，一份交申请人，一份留民政部门存档备查。"},{"i":11,"n":"第十一条","txt":"民政部门对申请人提出的行政许可申请，应当根据下列情况分别作出处理： (一)申请事项依法不需要取得行政许可的，应当即时告知申请人不受理，并向其出具《行政许可申请不予受理决定书》； (二)申请事项依法不属于本部门职权范围的，应当即时作出不予受理的决定，向申请人出具《行政许可申请不予受理决定书》，并告知其向有关行政机关申请； (三)申请材料存在文字、计算等可以当场更正的错误的，应当告知申请人当场更正，并让其在修改处确认； (四)申请材料不齐全或者不符合法定形式的，应当场或者在五日内作出《行政许可申请材料补正通知书》，一次告知申请人需要补正的全部内容。逾期不告知，自收到申请材料之日起即为受理； (五)申请事项属于本部门职权范围，申请材料齐全、符合法定形式或者申请人依照本部门要求提交补正材料的，应当受理行政许可申请，并向申请人出具《行政许可申请受理决定书》。 民政部门出具的上述书面凭证，应当加盖"},{"i":12,"n":"第十二条","txt":"对民政部门收到的行政许可申请，承办人员应当在《行政许可申请处理审批表》中写明处理情况，并归档备查。"},{"i":13,"n":"第十三条","txt":"申请人对提交申请材料的真实性负责。民政部门一般采取书面审查的办法对申请人提交的申请材料进行审查。 依法需要对申请材料的实质内容进行核实的，民政部门应当派两名以上工作人员进行核查，并制作现场检查笔录或者询问笔录。 现场检查笔录应当如实记载核查情况，并由核查人员签字。 核查中需要询问当事人或者有关人员时，核查人员应当出示执法证件，表明身份，询问笔录应当经被询问人核对无误后签名或者盖章。"},{"i":14,"n":"第十四条","txt":"民政部门实施行政许可应当注意听取公民、法人或者其他组织的陈述和申辩。对行政许可申请进行审查时，发现该行政许可事项直接关系他人重大利益的，应当在决定前告知利害关系人。申请人、利害关系人有权进行陈述和申辩。行政许可办理工作人员对申请人、利害关系人的口头陈述和申辩，应当制作陈述、申辩笔录。民政部门应当对申请人、利害关系人提出的事实、理由进行复核。事实、理由成立的，应当采纳。"},{"i":15,"n":"第十五条","txt":"依法应当先经下级民政部门审查后报上级民政部门决定的行政许可，下级民政部门应当依法接受申请人的申请，并进行初步审查。申请人提交材料齐全，符合法定形式的，应在法定期限内审查完毕并将初步审查意见和全部申请材料直接报送上级民政部门。上级民政部门不得要求申请人重复提供申请材料。 申请人直接向上级民政部门提出申请前款规定的行政许可事项，上级民政部门不得受理，并告知申请人通过下级民政部门提出申请。"},{"i":16,"n":"第十六条","txt":"法律、法规、规章规定实施行政许可应当听证的事项，或者民政部门认为需要听证的涉及公共利益的重大行政许可事项，民政部门应当在行政许可事项涉及的区域内发布听证公告，并举行听证。听证公告应当明确听证事项、听证举行的时间、地点、参加人员要求及提出申请的时间和方式等。"},{"i":17,"n":"第十七条","txt":"行政许可直接涉及申请人与他人之间重大利益关系，民政部门应当发出《行政许可听证告知书》，告知申请人、利害关系人有要求听证的权利。"},{"i":18,"n":"第十八条","txt":"申请人、利害关系人要求听证的，应当在收到民政部门《行政许可听证告知书》后五日内提交申请听证的书面材料；逾期不提交的，视为放弃听证的权利。"},{"i":19,"n":"第十九条","txt":"民政部门应当在接到申请人、利害关系人申请听证的书面材料二十日内组织听证，并且在举行听证的七日前，发出《行政许可听证通知书》，将听证的事项、时间、地点通知申请人、利害关系人。"},{"i":20,"n":"第二十条","txt":"申请人、利害关系人在举行听证之前，撤回听证申请的，应当准许，并记录在案。"},{"i":21,"n":"第二十一条","txt":"申请人、利害关系人可以亲自参加听证，也可以委托一至二名代理人参加听证。委托代理人参加听证的，应当提交书面授权委托书。"},{"i":22,"n":"第二十二条","txt":"听证主持人由民政部门负责人从本机关行政许可审查工作人员以外的国家公务员中指定。"},{"i":23,"n":"第二十三条","txt":"行政许可审查工作人员应当在举行听证五日前，向听证主持人提交行政许可审查意见的证据、理由等全部材料。"},{"i":24,"n":"第二十四条","txt":"听证会按照以下程序公开进行： (一)主持人宣布会场纪律； (二)核对听证参加人姓名、年龄、身份，告知听证参加人权利、义务； (三)行政许可审查人提出许可审查意见的证据、理由； (四)申请人、利害关系人进行申辩和质证； (五)许可审查人与申请人、利害关系人就有争议的事实进行辩论； (六)许可审查人与申请人、利害关系人作最后陈述； (七)主持人宣布听证会中止、延期或者结束。"},{"i":25,"n":"第二十五条","txt":"对于申请人、利害关系人或者其委托的代理人无正当理由不出席听证或者放弃申辩和质证权利退出听证会的，主持人可以宣布听证取消或者听证终止。"},{"i":26,"n":"第二十六条","txt":"听证记录员应当将听证的全部活动制作笔录，由听证主持人和记录员签名。听证笔录应当经听证参加人确认无误或者补正后，由听证参加人当场签名或者盖章。听证参加人拒绝签名或者盖章的，由听证主持人记明情况，在听证笔录中予以载明。"},{"i":27,"n":"第二十七条","txt":"民政部门应当根据听证笔录，作出行政许可决定。对听证笔录中没有认证、记载的事实依据，或者申请人听证后提交的证据，民政部门可以不予采信。"},{"i":28,"n":"第二十八条","txt":"依法应当举行听证而不举行听证的，根据利害关系人的请求或者依据职权，可以撤销行政许可，由此给当事人的合法权益造成损害的，应当给予赔偿；撤销行政许可可能对公共利益造成重大损害的，不予撤销。"},{"i":29,"n":"第二十九条","txt":"民政部门对行政许可申请进行审查后，对申请人提交的申请材料齐全，符合法定形式，能够当场作出决定的，应当场作出书面的行政许可决定；对不能当场作出决定的，应当在法定期限内按照规定程序作出行政许可决定。"},{"i":30,"n":"第三十条","txt":"申请人的申请符合法定条件、标准的，民政部门应当依法作出准予行政许可的书面决定；申请人的申请不符合法定条件、标准的，民政部门应当依法作出不予行政许可的书面决定。 民政部门依法作出不予行政许可书面决定的，应当说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。 行政许可书面决定应当载明作出决定的时间，并加盖作出决定的民政部门的印章。"},{"i":31,"n":"第三十一条","txt":"民政部门作出准予行政许可的决定，依法需要颁发行政许可证件的，应当向申请人颁发加盖本部门印章的下列行政许可证件： (一)许可证、执照或者其他许可证书； (二)资格证、资质证或者其他合格证书； (三)批准文件或者证明文件； (四)法律、法规规定的其他行政许可证件。 民政部门依法实施检验、检测的，可以在检验、检测合格的设备、设施、产品上加贴标签或者加盖检验、检测印章。"},{"i":32,"n":"第三十二条","txt":"行政许可证件一般应当载明证件名称、发证机关名称、持证人名称、行政许可事项、证件编号、发证日期、证件有效期等事项。"},{"i":33,"n":"第三十三条","txt":"行政许可决定依法作出即具有法律效力，民政部门不得擅自改变已经生效的行政许可。 行政许可所依据的法律、法规、规章修改或者废止，或者准予行政许可所依据的客观情况发生重大变化的，为了公共利益的需要，民政部门可以依法变更或者撤销已经生效的行政许可。由此给公民、法人或者其他组织造成财产损失的，应当依法给予补偿。"},{"i":34,"n":"第三十四条","txt":"民政部门作出的准予行政许可决定，应当根据行政许可事项的不同情况，以不同形式予以公开，并允许公众查阅。"},{"i":35,"n":"第三十五条","txt":"除当场作出行政许可决定的外，民政部门应当自受理行政许可申请之日起二十日内作出行政许可决定。二十日内不能作出决定的，经本部门负责人批准，可以延长十日，并向申请人出具《行政许可决定延期通知书》，告知延长期限的理由。法律、法规对作出行政许可决定的期限另有规定的，依照其规定。"},{"i":36,"n":"第三十六条","txt":"民政部门作出行政许可决定，依法需要听证、检验、检测、鉴定和专家评审的，所需时间不计算在本章规定的期限内，但应当将所需时间书面告知申请人。"},{"i":37,"n":"第三十七条","txt":"民政部门作出准予行政许可的决定，应当自作出决定之日起十日内向申请人颁发、送达行政许可证件，或者加贴标签。"},{"i":38,"n":"第三十八条","txt":"民政部门送达行政许可决定以及其他行政许可文书，一般应当由受送达人到民政部门办公场所直接领取。 受送达人直接领取行政许可决定以及其他行政许可文书时，一般应当在送达回证上注明收到日期，并签名或者盖章。"},{"i":39,"n":"第三十九条","txt":"受送达人不直接领取行政许可决定以及其他行政许可文书时，民政部门可以采取以下方式送达： (一)受送达人是法人或者其他组织的，应当由法人的法定代表人、该组织的主要负责人或者办公室、收发室、值班室等负责收件人在送达回证上签收或者盖章。 (二)受送达人拒绝接收行政许可文书的，送达人应当在送达回证上记明拒收的事由和日期，由送达人、有关基层组织或者所在单位的代表及其他见证人签名或者盖章，把行政许可文书留在受送达人的收发部门或者住所，视为送达；见证人不愿在送达回证上签字或者盖章的，送达人在送达回证上记明情况，把送达文书留在受送达人住所，视为送达。 (三)直接送达有困难的，可以委托当地民政部门送达，也可以邮寄送达。 邮寄送达的，以邮局回执上注明的收件日期为送达日期。 (四)无法采取上述方式送达，或者同一送达事项的受送达人众多的，可以在公告栏、受送达人住所地张贴公告，也可以在报刊上刊登公告。自公告发布之"},{"i":40,"n":"第四十条","txt":"被许可人要求变更行政许可事项，符合法定条件、标准的，作出行政许可决定的民政部门应当在受理申请之日起二十日内依法办理变更手续，并作出《准予变更行政许可决定书》；不符合法定条件、标准的，作出行政许可决定的民政部门应当作出《不予变更行政许可决定书》。法律、法规、规章另有规定的，依照其规定。"},{"i":41,"n":"第四十一条","txt":"被许可人需要延续行政许可有效期的，应当在该行政许可有效期届满三十日前向作出行政许可决定的民政部门提出。民政部门应当根据被许可人的申请，在该行政许可有效期届满前作出是否准予延续的决定，并作出《准予延续行政许可决定书》或者《不予延续行政许可决定书》；逾期未作出决定的，视为准予延续。法律、法规、规章另有规定的，依照其规定。"},{"i":42,"n":"第四十二条","txt":"实施行政许可的民政部门应当依法对被许可人从事行政许可事项的活动进行监督检查。 上级民政部门应当加强对下级民政部门实施行政许可的监督检查。 各级民政部门内设机构承担具体业务范围内行政许可的监督检查工作，并以本民政部门名义开展监督检查。"},{"i":43,"n":"第四十三条","txt":"县级以上民政部门应当建立健全法制工作机构，加强监督检查的协调工作、开展行政复议工作，实施国家赔偿制度和补偿制度，依法保障当事人获得行政许可的合法权益。"},{"i":44,"n":"第四十四条","txt":"监督检查不得妨碍被许可人正常的生产经营活动。"},{"i":45,"n":"第四十五条","txt":"民政部门应当将监督检查的情况和处理结果予以记录，由监督检查人员签字后归档。公众有权查阅监督检查记录。"},{"i":46,"n":"第四十六条","txt":"被许可人在作出行政许可决定的民政部门管辖区域内违法从事行政许可事项活动的，由作出该行政许可决定的民政部门依法进行处理。 被许可人在作出行政许可决定的民政部门管辖区域外违法从事行政许可事项活动的，由违法行为发生地的民政部门依法进行处理。 违法行为发生地的民政部门对违法的被许可人作出处理后，应当于十日内将违法事实、相关证据材料和处理结果等抄告作出行政许可决定的民政部门。"},{"i":47,"n":"第四十七条","txt":"民政部门应当建立对被许可人监督检查制度，依法对被许可人实施定期检查、实地检查。"},{"i":48,"n":"第四十八条","txt":"民政部门应当指导被许可人建立自查制度，并监督被许可人依照制度进行自查，督促被许可人将重要工作自查情况报民政部门备案。"},{"i":49,"n":"第四十九条","txt":"有行政许可法第六十九条第一款所列情形之一的，作出行政许可决定的民政部门或者其上级民政部门，根据利害关系人的请求或者依据职权，可以撤销行政许可。 被许可人以欺骗、贿赂等不正当手段取得行政许可的，应当予以撤销。 依照前两款的规定撤销行政许可，可能对公共利益造成重大损害的，不予撤销。 依照本条第一款的规定撤销行政许可，被许可人的合法权益受到损害的，民政部门应当依法给予赔偿。依照本条第二款的规定撤销行政许可的，被许可人基于行政许可取得的利益不受保护。"},{"i":50,"n":"第五十条","txt":"有行政许可法第七十条所列情形之一的，作出行政许可决定的民政部门应当依法办理行政许可的注销手续。"},{"i":51,"n":"第五十一条","txt":"各级民政部门必须建立行政执法责任制，定岗、定责、定人，及时纠正承办人员的违法、违纪行为。"},{"i":52,"n":"第五十二条","txt":"民政部门及其工作人员有以下违反行政许可法规定，应当承担法律责任情形的，依法由上级行政机关或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员给予行政处分： (一)对符合法定条件的行政许可申请不予受理的； (二)不在办公场所公示依法应当公示的材料的； (三)在受理、审查、决定行政许可过程中，未向申请人、利害关系人履行法定告知义务的； (四)申请人提交的申请材料不齐全、不符合法定形式，不一次告知申请人必须补正的全部内容的； (五)未依法说明不受理行政许可申请或者不予行政许可的理由的； (六)依法应当举行听证而不举行听证的。"},{"i":53,"n":"第五十三条","txt":"民政部门工作人员在办理行政许可、实施监督检查中，索取或者收受他人财物及谋取其他利益，尚不构成犯罪的，依法给予行政处分；构成犯罪的，移送司法机关追究刑事责任。"},{"i":54,"n":"第五十四条","txt":"民政部门实施行政许可，对不符合法定条件的申请人准予行政许可、对符合法定条件的申请人不予行政许可、超越法定职权或者不在法定期限内作出准予行政许可决定的，依法由上级行政机关或者监察机关责令改正，对直接负责的主管人员和其他直接责任人员给予行政处分；构成犯罪的，移送司法机关追究刑事责任。"},{"i":55,"n":"第五十五条","txt":"民政部门违法实施行政许可，给当事人的合法权益造成损害的，在机关对外承担赔偿责任后，责令有故意或者重大过失的承办人员承担部分或者全部赔偿费用，并作出相应的处理决定。"},{"i":56,"n":"第五十六条","txt":"被许可人有违反行政许可法规定情形的，由作出行政许可的民政部门依法给予行政处罚；构成犯罪的，移送司法机关追究刑事责任。"},{"i":57,"n":"第五十七条","txt":"民政部门实施非行政许可的行政审批，可参照本办法。"},{"i":58,"n":"第五十八条","txt":"本办法自2004年7月1日起施行。 附件：民政部门实施行政许可通用文书(略)"}],"shengjixingzhengquyujiexianlianhejianchashishibanfc16676":[{"i":1,"n":"第一条","txt":"为了规范对省级行政区域界线联合检查的管理，根据国务院《行政区域界线管理条例》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称省级行政区域界线联合检查（以下简称“联检”）,是指毗邻的省、自治区、直辖市人民政府联合组织对已勘定的省级行政区域界线管理情况进行检查，并对发现问题进行处理的一项法定工作制度。"},{"i":3,"n":"第三条","txt":"联检实地检查的内容包括： （一）已勘定行政区域界线的贯彻落实情况； （二）界桩及其方位物变化和界桩的维护情况； （三）指示行政区域界线走向的其他标志物及与行政区域界线实地位置有关的地物、地貌变化情况和组织修测情况； （四）跨行政区域生产建设和管理及有关问题的处理情况； （五）其他与行政区域界线管理有关的情况。"},{"i":4,"n":"第四条","txt":"联检应当坚持有利于巩固勘界成果、保持行政区域界线走向明确，有利于维护行政区域界线附近地区的社会稳定和双方群众利益，有利于促进当地经济与社会发展的原则。"},{"i":5,"n":"第五条","txt":"联检的依据： （一）国务院批准的省、自治区、直辖市人民政府联合勘定的行政区域界线协议书（以下简称“协议书”）及其附图、附表，界桩登记表； （二）国务院和有关部门划定行政区域界线的批复、协调处理意见及其附图； （三）历次联检报告。"},{"i":6,"n":"第六条","txt":"同一条行政区域界线的联检每5年进行1次。遇有影响行政区域界线实地走向辨认的自然灾害、河流改道、道路变化等特殊情况，由毗邻的省、自治区、直辖市人民政府民政部门共同对行政区域界线或界线上需要检查的特定地段进行确认，报省、自治区、直辖市人民政府随时安排联检。"},{"i":7,"n":"第七条","txt":"联检由国务院民政部门统一部署，在行政区域界线毗邻的省、自治区、直辖市人民政府的共同领导下，由有关的省、自治区、直辖市人民政府民政部门联合组织实施。"},{"i":8,"n":"第八条","txt":"根据联检任务，毗邻的省、自治区、直辖市人民政府民政部门应当成立由负责同志任组长的联检工作领导小组，负责联检的组织实施和重大问题的协调处理。联检工作领导小组可以根据行政区域界线的实际情况吸收有关部门的同志参加。沿线毗邻地区的县级人民政府民政部门应当成立联检工作组，负责具体实地联检。"},{"i":9,"n":"第九条","txt":"联检工作领导小组应当根据行政区域界线的实际情况，制定联检实施方案，报国务院民政部门备案。实施方案应当明确联检的组织领导、实施步骤、重大问题的处理原则、工作要求和时间安排。 实施方案确定后，由行政区域界线毗邻的省、自治区、直辖市人民政府民政部门向沿线双方下级人民政府民政部门通报联检实施方案，提出联检的具体要求，组织实施联检。"},{"i":10,"n":"第十条","txt":"实施联检，应当向行政区域界线附近地区基层人民政府和干部群众明确已勘定行政区域界线的实地走向，宣传已勘定行政区域界线的法律地位及地方各级人民政府和有关部门的管理职责，了解已勘定行政区域界线的管理落实情况，发现问题应当及时处理。"},{"i":11,"n":"第十一条","txt":"实地检查中，应当按照下列要求对界桩及其方位物进行维护： （一）界桩完好无损或者轻度损坏可以修复的，应当清除界桩周围的遮挡物，修复界桩损坏部位，刷新界桩上的注记； （二）界桩丢失或者严重损坏不能修复的，由负责管理该界桩的一方重新制作，并与毗邻方共同按照界桩登记表和界桩成果表记载的界桩位置，在原地重新设立； （三）界桩因建设、开发等原因需要移动或者增设的，毗邻的各有关人民政府应当协商一致，可以在原界桩附近行政区域界线上选取适当位置重新埋设或者在协商一致的地方增设。 不在行政区域界线上的单立界桩，丢失或者严重损坏不能修复的，应当在原界桩附近行政区域界线上选取适当位置重新设立；因建设、开发等原因需要移动的，毗邻的各有关人民政府应当协商一致，移动并埋设在实地行政区域界线上。 行政区域界线交会点界桩的检查应当与联检同步进行。 原界桩方位物消失，但不影响界桩实地位置的确定，可以不再新设界桩方位物。"},{"i":12,"n":"第十二条","txt":"重新设立、移动和增设界桩后，应当按照《省级行政区域界线勘界测绘技术规定》的有关要求，制作并埋设界桩，测定界桩坐标，填写界桩登记表，拍摄界桩照片。 重新设立和增设界桩上的时间注记，应当以启动联检的时间为准。"},{"i":13,"n":"第十三条","txt":"单方设立的指示行政区域界线实地位置的标志物应当予以清除。确需设立的，经毗邻的有关人民政府协商一致后共同设立或者增设界桩。"},{"i":14,"n":"第十四条","txt":"行政区域界线其他标志物及与行政区域界线相关的地物、地貌，应当按照协议书中行政区域界线走向说明及协议书附图进行实地检查。发生变化的地段，应当将变化情况详细记载，并组织行政区域界线地形图的修测，修测结果标绘在与原协议书附图比例尺相同的地形图上，变化较大时应当重新测制行政区域界线地形图。"},{"i":15,"n":"第十五条","txt":"对联检中发现未依法办理审批手续，越界从事生产建设等活动的，联检工作领导小组应当及时通知有关人民政府责成业务主管部门予以处理。"},{"i":16,"n":"第十六条","txt":"确因生产建设需要局部变更行政区域界线的，按照《国务院关于行政区划管理的规定》办理。"},{"i":17,"n":"第十七条","txt":"联检实地检查结束后，由联检工作领导小组组织联检资料的检查验收、整理汇总、成果上报和立卷归档。"},{"i":18,"n":"第十八条","txt":"对联检中重新设立、移动和增设的界桩，应当整理并填写界桩登记表和界桩成果表。图表项目填写应当清晰齐全，文字叙述简明准确。"},{"i":19,"n":"第十九条","txt":"联检工作领导小组组织起草联检报告，通过毗邻的省、自治区、直辖市人民政府共同报送国务院备案，并抄送国务院民政部门。 联检报告应当包括以下内容：联检的基本情况、组织实施、实地检查、有关问题的处理结果和加强界线管理的措施等；有重新设立、移动和增设界桩情况的，应当报送界桩成果表。"},{"i":20,"n":"第二十条","txt":"联检中形成的实施方案、会议纪要、检查及修测记录、联检报告以及界桩成果表、登记表、照片等与行政区域界线管理有关的资料，由有关的省、自治区、直辖市人民政府民政部门按照档案管理的规定立卷归档，同时将立卷归档的文件副本报送国务院民政部门。"},{"i":21,"n":"第二十一条","txt":"本办法自公布之日起施行。"}],"shehuituantifenzhijigoudaibiaojigoudengjibanfa":[{"i":1,"n":"第一条","txt":"为了加强对社会团体分支机构、代表机构的管理，根据《社会团体登记管理条例》有关规定,制定本办法。"},{"i":2,"n":"第二条","txt":"社会团体的分支机构，是社会团体根据开展活动的需要，依据业务范围的划分或者会员组成的特点，设立的专门从事该社会团体某项业务活动的机构。 分支机构可以称分会、专业委员会、工作委员会、专项基金管理委员会等。 社会团体的代表机构，是社会团体在住所地以外属于其活动区域内设置的代表该社会团体开展活动、承办该社会团体交办事项的机构。 代表机构可以称代表处、办事处、联络处等。"},{"i":3,"n":"第三条","txt":"社会团体设立分支机构、代表机构应当按照章程的规定，履行民主程序，经业务主管单位审查同意后，向负责该社会团体登记的登记管理机关提出申请。经登记管理机关登记后，方可开展活动。"},{"i":4,"n":"第四条","txt":"社会团体申请设立分支机构、代表机构应当具备下列条件： (一)有规范的名称； (二)有固定的住所； (三)有符合章程所规定的业务范围。"},{"i":5,"n":"第五条","txt":"社会团体申请设立分支机构、代表机构应当向登记管理机关提交下列文件： (一)设立申请书； (二)业务主管单位审查同意的意见； (三)拟任主要负责人基本情况以及本人所在单位人事部门的意见； (四)住所产权或使用权证明； (五)社会团体理事会或常务理事会决议； (六)登记管理机关要求提交的其他材料。 申请书应当包括设立的理由，分支机构、代表机构的业务范围和工作任务。 社会团体设立专项基金管理委员会，应当遵照《社会团体设立专项基金管理机构暂行规定》办理。 社会团体代表机构以及分支机构住所与社会团体住所不在一地的，还需提交拟设在地登记管理机关的意见。"},{"i":6,"n":"第六条","txt":"有下列情形之一的，登记管理机关不予登记： (一)在社会团体内拟设立的分支机构与已设立的分支机构业务范围相同或者相似的； (二)拟设立的分支机构冠以行政区划名称，带有地域性特征的； (三)在分支机构、代表机构下又设立分支机构、代表机构的； (四)拟设立的分支机构业务与该社会团体宗旨、业务范围无关的； (五)拟设立代表机构的活动内容、承办事项与该社会团体的业务范围无关的； (六)拟设立的分支机构、代表机构设定的活动范围超越该社会团体设定的活动地域的； (七)有法律、行政法规禁止的其他情形的。"},{"i":7,"n":"第七条","txt":"登记管理机关自收到本办法第五条所列全部有效文件后，在法定期限内作出准予或者不予登记的决定。准予登记的，由登记管理机关发给《社会团体分支机构登记证书》或《社会团体代表机构登记证书》；对不予登记的，应当将不予登记的决定书面通知社会团体，并说明理由。 社会团体分支机构、代表机构登记事项包括：名称、住所、业务范围、活动地域、负责人。"},{"i":8,"n":"第八条","txt":"符合《社会团体登记管理条例》第十七条规定的社会团体设立分支机构、代表机构，应当向登记管理机关备案。登记管理机关自收到备案文件之日起30日内，发给《社会团体分支机构登记证书》或《社会团体代表机构登记证书》。"},{"i":9,"n":"第九条","txt":"社会团体可以凭登记管理机关颁发的《社会团体分支机构登记证书》或《社会团体代表机构登记证书》向有关部门申请刻制印章。 分支机构因特殊需要建立银行基本存款账户的，由社会团体向登记管理机关申请，经登记管理机关同意后，按有关规定办理。 印章式样向登记管理机关备案。"},{"i":10,"n":"第十条","txt":"社会团体办理分支机构、代表机构变更，应当向登记管理机关提交下列文件： (一)社会团体法定代表人签署的变更申请书； (二)社会团体理事会或常务理事会关于变更事项的会议决议； 负责人变更的还需提交本人的基本情况及身份证明。 住所变更的还需提交新住所产权或使用权证明。"},{"i":11,"n":"第十一条","txt":"社会团体决定注销其分支机构、代表机构，应当经业务主管单位审查同意后，向登记管理机关提交下列文件，申请注销登记： (一)注销登记申请书； (二)业务主管单位审查同意的意见； (三)社会团体理事会或常务理事会决议。 登记管理机关准予注销的，发给注销证明文件，收缴该分支机构、代表机构的《社会团体分支机构登记证书》或《社会团体代表机构登记证书》、印章。"},{"i":12,"n":"第十二条","txt":"社会团体的分支机构、代表机构是社会团体的组成部分，不具有法人资格，其法律责任由设立该分支机构、代表机构的社会团体承担。 社会团体的分支机构应当在该社会团体的授权范围内发展会员、收取会费，其发展的会员属于该社会团体的会员，其收取的会费属于该社会团体所有。 社会团体分支机构、代表机构的名称前应当冠以社会团体名称；开展活动，应当使用全称。分支机构、代表机构的英文译名应当与中文名称一致。"},{"i":13,"n":"第十三条","txt":"社会团体在申请设立分支机构、代表机构时弄虚作假的，或者自取得《社会团体分支机构登记证书》或《社会团体代表机构登记证书》之日起1年未开展活动的，由登记管理机关对所设立的分支机构、代表机构予以撤销。"},{"i":14,"n":"第十四条","txt":"社会团体有下列情形之一的，由登记管理机关依据《社会团体登记管理条例》第三十三条规定予以处理： (一)未经登记，擅自以分支机构、代表机构名义进行活动的； (二)以分支机构下设的分支机构名义进行活动的； (三)以地域性分支机构名义进行活动的； (四)未尽到管理职责，致使分支机构、代表机构进行违法活动造成严重后果的。"},{"i":15,"n":"第十五条","txt":"社会团体注销的，其所属的分支机构、代表机构同时注销。"},{"i":16,"n":"第十六条","txt":"《社会团体分支机构登记证书》、《社会团体代表机构登记证书》的式样由国务院民政部门制定。"},{"i":17,"n":"第十七条","txt":"本办法实施前已经备案的社会团体分支机构、代表机构，应当自本办法施行之日起1年内依照本办法有关规定申请登记。"},{"i":18,"n":"第十八条","txt":"香港特别行政区、澳门特别行政区、台湾地区和外国社会团体在中国大陆设立分支机构、代表机构的，另行规定。"},{"i":19,"n":"第十九条","txt":"本办法自发布之日起施行。"}],"shehuituantiyinzhangguanliguiding":[],"shehuixiaofanganquanjiaoyupeixunguiding":[{"i":1,"n":"第一条","txt":"为了加强社会消防安全教育培训工作，提高公民消防安全素质，有效预防火灾，减少火灾危害，根据《中华人民共和国消防法》等有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"机关、团体、企业、事业等单位（以下统称单位）、社区居民委员会、村民委员会依照本规定开展消防安全教育培训工作。"},{"i":3,"n":"第三条","txt":"公安、教育、民政、人力资源和社会保障、住房和城乡建设、文化、广电、安全监管、旅游、文物等部门应当按照各自职能，依法组织和监督管理消防安全教育培训工作，并纳入相关工作检查、考评。 各部门应当建立协作机制，定期研究、共同做好消防安全教育培训工作。"},{"i":4,"n":"第四条","txt":"消防安全教育培训的内容应当符合全国统一的消防安全教育培训大纲的要求，主要包括： （一）国家消防工作方针、政策； （二）消防法律法规； （三）火灾预防知识； （四）火灾扑救、人员疏散逃生和自救互救知识； （五）其他应当教育培训的内容。"},{"i":5,"n":"第五条","txt":"公安机关应当履行下列职责，并由公安机关消防机构具体实施： （一）掌握本地区消防安全教育培训工作情况，向本级人民政府及相关部门提出工作建议； （二）协调有关部门指导和监督社会消防安全教育培训工作； （三）会同教育行政部门、人力资源和社会保障部门对消防安全专业培训机构实施监督管理； （四）定期对社区居民委员会、村民委员会的负责人和专（兼）职消防队、志愿消防队的负责人开展消防安全培训。"},{"i":6,"n":"第六条","txt":"教育行政部门应当履行下列职责： （一）将学校消防安全教育培训工作纳入教育培训规划，并进行教育督导和工作考核； （二）指导和监督学校将消防安全知识纳入教学内容； （三）将消防安全知识纳入学校管理人员和教师在职培训内容； （四）依法在职责范围内对消防安全专业培训机构进行审批和监督管理。"},{"i":7,"n":"第七条","txt":"民政部门应当履行下列职责： （一）将消防安全教育培训工作纳入减灾规划并组织实施，结合救灾、扶贫济困和社会优抚安置、慈善等工作开展消防安全教育； （二）指导社区居民委员会、村民委员会和各类福利机构开展消防安全教育培训工作； （三）负责消防安全专业培训机构的登记，并实施监督管理。"},{"i":8,"n":"第八条","txt":"人力资源和社会保障部门应当履行下列职责： （一）指导和监督机关、企业和事业单位将消防安全知识纳入干部、职工教育、培训内容； （二）依法在职责范围内对消防安全专业培训机构进行审批和监督管理。"},{"i":9,"n":"第九条","txt":"住房和城乡建设行政部门应当指导和监督勘察设计单位、施工单位、工程监理单位、施工图审查机构、城市燃气企业、物业服务企业、风景名胜区经营管理单位和城市公园绿地管理单位等开展消防安全教育培训工作，将消防法律法规和工程建设消防技术标准纳入建设行业相关执业人员的继续教育和从业人员的岗位培训及考核内容。"},{"i":10,"n":"第十条","txt":"文化、文物行政部门应当积极引导创作优秀消防安全文化产品，指导和监督文物保护单位、公共娱乐场所和公共图书馆、博物馆、文化馆、文化站等文化单位开展消防安全教育培训工作。"},{"i":11,"n":"第十一条","txt":"广播影视行政部门应当指导和协调广播影视制作机构和广播电视播出机构，制作、播出相关消防安全节目，开展公益性消防安全宣传教育，指导和监督电影院开展消防安全教育培训工作。"},{"i":12,"n":"第十二条","txt":"安全生产监督管理部门应当履行下列职责： （一）指导、监督矿山、危险化学品、烟花爆竹等生产经营单位开展消防安全教育培训工作； （二）将消防安全知识纳入安全生产监管监察人员和矿山、危险化学品、烟花爆竹等生产经营单位主要负责人、安全生产管理人员以及特种作业人员培训考核内容； （三）将消防法律法规和有关消防技术标准纳入注册安全工程师培训及执业资格考试内容。"},{"i":13,"n":"第十三条","txt":"旅游行政部门应当指导和监督相关旅游企业开展消防安全教育培训工作，督促旅行社加强对游客的消防安全教育，并将消防安全条件纳入旅游饭店、旅游景区等相关行业标准，将消防安全知识纳入旅游从业人员的岗位培训及考核内容。"},{"i":14,"n":"第十四条","txt":"单位应当根据本单位的特点，建立健全消防安全教育培训制度，明确机构和人员，保障教育培训工作经费，按照下列规定对职工进行消防安全教育培训： （一）定期开展形式多样的消防安全宣传教育； （二）对新上岗和进入新岗位的职工进行上岗前消防安全培训； （三）对在岗的职工每年至少进行一次消防安全培训； （四）消防安全重点单位每半年至少组织一次、其他单位每年至少组织一次灭火和应急疏散演练。 单位对职工的消防安全教育培训应当将本单位的火灾危险性、防火灭火措施、消防设施及灭火器材的操作使用方法、人员疏散逃生知识等作为培训的重点。"},{"i":15,"n":"第十五条","txt":"各级各类学校应当开展下列消防安全教育工作： （一）将消防安全知识纳入教学内容； （二）在开学初、放寒（暑）假前、学生军训期间，对学生普遍开展专题消防安全教育； （三）结合不同课程实验课的特点和要求，对学生进行有针对性的消防安全教育； （四）组织学生到当地消防站参观体验； （五）每学年至少组织学生开展一次应急疏散演练； （六）对寄宿学生开展经常性的安全用火用电教育和应急疏散演练。 各级各类学校应当至少确定一名熟悉消防安全知识的教师担任消防安全课教员，并选聘消防专业人员担任学校的兼职消防辅导员。"},{"i":16,"n":"第十六条","txt":"中小学校和学前教育机构应当针对不同年龄阶段学生认知特点，保证课时或者采取学科渗透、专题教育的方式，每学期对学生开展消防安全教育。 小学阶段应当重点开展火灾危险及危害性、消防安全标志标识、日常生活防火、火灾报警、火场自救逃生常识等方面的教育。 初中和高中阶段应当重点开展消防法律法规、防火灭火基本知识和灭火器材使用等方面的教育。 学前教育机构应当采取游戏、儿歌等寓教于乐的方式，对幼儿开展消防安全常识教育。"},{"i":17,"n":"第十七条","txt":"高等学校应当每学年至少举办一次消防安全专题讲座，在校园网络、广播、校内报刊等开设消防安全教育栏目，对学生进行消防法律法规、防火灭火知识、火灾自救他救知识和火灾案例教育。"},{"i":18,"n":"第十八条","txt":"国家支持和鼓励有条件的普通高等学校和中等职业学校根据经济社会发展需要，设置消防类专业或者开设消防类课程，培养消防专业人才，并依法面向社会开展消防安全培训。 人民警察训练学校应当根据教育培训对象的特点，科学安排培训内容，开设消防基础理论和消防管理课程，并列入学生必修课程。 师范院校应当将消防安全知识列入学生必修内容。"},{"i":19,"n":"第十九条","txt":"社区居民委员会、村民委员会应当开展下列消防安全教育工作： （一）组织制定防火安全公约； （二）在社区、村庄的公共活动场所设置消防宣传栏，利用文化活动站、学习室等场所，对居民、村民开展经常性的消防安全宣传教育； （三）组织志愿消防队、治安联防队和灾害信息员、保安人员等开展消防安全宣传教育； （四）利用社区、乡村广播、视频设备定时播放消防安全常识，在火灾多发季节、农业收获季节、重大节日和乡村民俗活动期间，有针对性地开展消防安全宣传教育。 社区居民委员会、村民委员会应当确定至少一名专（兼）职消防安全员，具体负责消防安全宣传教育工作。"},{"i":20,"n":"第二十条","txt":"物业服务企业应当在物业服务工作范围内，根据实际情况积极开展经常性消防安全宣传教育，每年至少组织一次本单位员工和居民参加的灭火和应急疏散演练。"},{"i":21,"n":"第二十一条","txt":"由两个以上单位管理或者使用的同一建筑物，负责公共消防安全管理的单位应当对建筑物内的单位和职工进行消防安全宣传教育，每年至少组织一次灭火和应急疏散演练。"},{"i":22,"n":"第二十二条","txt":"歌舞厅、影剧院、宾馆、饭店、商场、集贸市场、体育场馆、会堂、医院、客运车站、客运码头、民用机场、公共图书馆和公共展览馆等公共场所应当按照下列要求对公众开展消防安全宣传教育： （一）在安全出口、疏散通道和消防设施等处的醒目位置设置消防安全标志、标识等； （二）根据需要编印场所消防安全宣传资料供公众取阅； （三）利用单位广播、视频设备播放消防安全知识。 养老院、福利院、救助站等单位，应当对服务对象开展经常性的用火用电和火场自救逃生安全教育。"},{"i":23,"n":"第二十三条","txt":"旅游景区、城市公园绿地的经营管理单位、大型群众性活动主办单位应当在景区、公园绿地、活动场所醒目位置设置疏散路线、消防设施示意图和消防安全警示标识，利用广播、视频设备、宣传栏等开展消防安全宣传教育。 导游人员、旅游景区工作人员应当向游客介绍景区消防安全常识和管理要求。"},{"i":24,"n":"第二十四条","txt":"在建工程的施工单位应当开展下列消防安全教育工作： （一）建设工程施工前应当对施工人员进行消防安全教育； （二）在建设工地醒目位置、施工人员集中住宿场所设置消防安全宣传栏，悬挂消防安全挂图和消防安全警示标识； （三）对明火作业人员进行经常性的消防安全教育； （四）组织灭火和应急疏散演练。 在建工程的建设单位应当配合施工单位做好上述消防安全教育工作。"},{"i":25,"n":"第二十五条","txt":"新闻、广播、电视等单位应当积极开设消防安全教育栏目，制作节目，对公众开展公益性消防安全宣传教育。"},{"i":26,"n":"第二十六条","txt":"公安、教育、民政、人力资源和社会保障、住房和城乡建设、安全监管、旅游部门管理的培训机构，应当根据教育培训对象特点和实际需要进行消防安全教育培训。"},{"i":27,"n":"第二十七条","txt":"国家机构以外的社会组织或者个人利用非国家财政性经费，举办消防安全专业培训机构，面向社会从事消防安全专业培训的，应当经省级教育行政部门或者人力资源和社会保障部门依法批准，并到省级民政部门申请民办非企业单位登记。"},{"i":28,"n":"第二十八条","txt":"成立消防安全专业培训机构应当符合下列条件： （一）具有法人条件，有规范的名称和必要的组织机构； （二）注册资金或者开办费一百万元以上； （三）有健全的组织章程和培训、考试制度； （四）具有与培训规模和培训专业相适应的专（兼）职教员队伍； （五）有同时培训二百人以上规模的固定教学场所、训练场地，具有满足技能培训需要的消防设施、设备和器材； （六）消防安全专业培训需要的其他条件。 前款第（四）项所指专（兼）职教员队伍中，专职教员应当不少于教员总数的二分之一；具有建筑、消防等相关专业中级以上职称，并有五年以上消防相关工作经历的教员不少于十人；消防安全管理、自动消防设施、灭火救援等专业课程应当分别配备理论教员和实习操作教员不少于两人。"},{"i":29,"n":"第二十九条","txt":"申请成立消防安全专业培训机构，依照国家有关法律法规，应当向省级教育行政部门或者人力资源和社会保障部门申请。 省级教育行政部门或者人力资源和社会保障部门受理申请后，可以征求同级公安机关消防机构的意见。 省级公安机关消防机构收到省级教育行政部门或者人力资源和社会保障部门移送的申请材料后，应当配合对申请成立消防安全培训专业机构的师资条件、场地和设施、设备、器材等进行核查，并出具书面意见。 教育行政部门或者人力资源和社会保障部门根据有关民办职业培训机构的规定，并综合公安机关消防机构出具的书面意见进行评定，符合条件的予以批准，并向社会公告。"},{"i":30,"n":"第三十条","txt":"消防安全专业培训机构应当按照有关法律法规、规章和章程规定，开展消防安全专业培训，保证培训质量。 消防安全专业培训机构开展消防安全专业培训，应当将消防安全管理、建筑防火和自动消防设施施工、操作、检测、维护技能作为培训的重点，对经理论和技能操作考核合格的人员，颁发培训证书。 消防安全专业培训的收费标准，应当符合国家有关规定，并向社会公布。"},{"i":31,"n":"第三十一条","txt":"省级教育行政部门或者人力资源和社会保障部门应当依法对消防安全专业培训机构进行管理，监督、指导消防安全专业培训机构依法开展活动。 省级教育行政部门或者人力资源和社会保障部门应当对消防安全专业培训机构定期组织质量评估，并向社会公布监督评估情况。省级教育行政部门或者人力资源和社会保障部门在对消防安全专业培训机构进行质量评估时，可以邀请公安机关消防机构专业人员参加。"},{"i":32,"n":"第三十二条","txt":"地方各级人民政府及有关部门对在消防安全教育培训工作中有突出贡献或者成绩显著的单位和个人，应当给予表彰奖励。 单位对消防安全教育培训工作成绩突出的职工，应当给予表彰奖励。"},{"i":33,"n":"第三十三条","txt":"地方各级人民政府公安、教育、民政、人力资源和社会保障、住房和城乡建设、文化、广电、安全监管、旅游、文物等部门不依法履行消防安全教育培训工作职责的，上级部门应当给予批评；对直接责任人员由上级部门和所在单位视情节轻重，根据权限依法给予批评教育或者建议有权部门给予处分。 公安机关消防机构工作人员在协助审查消防安全专业培训机构的工作中疏于职守的，由上级机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":34,"n":"第三十四条","txt":"学校未按照本规定第十五条、第十六条、第十七条、第十八条规定开展消防安全教育工作的，教育、公安、人力资源和社会保障等主管部门应当按照职责分工责令其改正，并视情对学校负责人和其他直接责任人员给予处分。"},{"i":35,"n":"第三十五条","txt":"单位违反本规定，构成违反消防管理行为的，由公安机关消防机构依照《中华人民共和国消防法》予以处罚。"},{"i":36,"n":"第三十六条","txt":"社会组织或者个人未经批准擅自举办消防安全专业培训机构的，或者消防安全专业培训机构在培训活动中有违法违规行为的，由教育、人力资源和社会保障、民政等部门依据各自职责依法予以处理。"},{"i":37,"n":"第三十七条","txt":"全国统一的消防安全教育培训大纲由公安部会同教育部、人力资源和社会保障部共同制定。"}],"shehuizuzhixinyongxinxiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强社会组织信用信息管理，推进社会组织信用体系建设，促进社会组织健康有序发展，依据有关法律法规和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于社会组织登记管理机关（以下简称登记管理机关）在依法履行职责过程中形成或者获取的与社会组织信用状况有关信息的管理。 政府其他有关部门以及司法机关在履行职责过程中形成的与社会组织信用状况有关的信息，依法依规纳入社会组织信用信息进行管理。"},{"i":3,"n":"第三条","txt":"国务院民政部门指导全国社会组织信用信息管理工作。 国务院民政部门和县级以上地方各级人民政府民政部门负责在本机关登记的社会组织信用信息管理工作。"},{"i":4,"n":"第四条","txt":"社会组织信用信息的管理应当遵循依法公开、统一管理、分级负责、信息共享、动态更新的原则。"},{"i":5,"n":"第五条","txt":"登记管理机关开展社会组织信用信息管理工作，应当依法保守国家秘密、商业秘密和个人隐私。"},{"i":6,"n":"第六条","txt":"社会组织信用信息包括基础信息、年报信息、行政检查信息、行政处罚信息和其他信息。"},{"i":7,"n":"第七条","txt":"基础信息是指反映社会组织登记、核准和备案等事项的信息。 年报信息是指社会组织依法履行年度工作报告义务并向社会公开的信息。 行政检查信息是指登记管理机关及政府有关部门对社会组织开展监督检查形成的结论性信息。 行政处罚信息是指社会组织受到的行政处罚种类、处罚结果、违法事实、处罚依据、处罚时间、作出行政处罚的部门等信息。 其他信息是指社会组织评估等级及有效期限、获得的政府有关部门的表彰奖励、承接政府购买服务或者委托事项、公开募捐资格、公益性捐赠税前扣除资格等与社会组织信用有关的信息。"},{"i":8,"n":"第八条","txt":"登记管理机关应当在信息形成或者获取后5个工作日内将应予记录的社会组织信用信息采集录入到社会组织信息管理系统。尚未建立社会组织信息管理系统的登记管理机关，应当采取适当方式及时采集、记录相关信息。 登记管理机关应当加强对信用信息的管理和维护，保证信息安全。"},{"i":9,"n":"第九条","txt":"登记管理机关依据社会组织未依法履行义务或者存在违法违规行为的有关信用信息，建立社会组织活动异常名录和严重违法失信名单制度。"},{"i":10,"n":"第十条","txt":"因非行政处罚事项被列入活动异常名录或者严重违法失信名单的社会组织，登记管理机关在作出决定前，应当向社会组织书面告知列入的事实、理由、依据及其依法享有的权利。通过登记的住所无法取得联系的，可以通过互联网公告告知。 社会组织对被列入活动异常名录或者严重违法失信名单有异议的，可以在收到告知书之日起10个工作日内向登记管理机关提出书面陈述申辩意见并提交相关证明材料。通过公告方式告知的，社会组织自公告之日起30日内未提交陈述申辩意见的，视为无异议。 登记管理机关应当自收到陈述申辩意见之日起10个工作日内进行核实，作出是否列入活动异常名录或者严重违法失信名单的决定，并书面告知申请人。"},{"i":11,"n":"第十一条","txt":"登记管理机关应当将有下列情形之一的社会组织列入活动异常名录： （一）未按照规定时限和要求向登记管理机关报送年度工作报告的； （二）未按照有关规定设立党组织的； （三）登记管理机关在抽查和其他监督检查中发现问题，发放整改文书要求限期整改，社会组织未按期完成整改的； （四）具有公开募捐资格的慈善组织，存在《慈善组织公开募捐管理办法》第二十一条规定情形的； （五）受到警告或者不满5万元罚款处罚的； （六）通过登记的住所无法与社会组织取得联系的； （七）法律、行政法规规定应当列入的其他情形。 登记管理机关在依法履职过程中通过邮寄专用信函向社会组织登记的住所两次邮寄无人签收的，视作通过登记的住所无法与社会组织取得联系。两次邮寄间隔时间不得少于15日，不得超过30日。"},{"i":12,"n":"第十二条","txt":"社会组织存在第十一条所列情形，但由业务主管单位或者其他有关部门书面证明该社会组织对此不负直接责任的，可以不列入活动异常名录。"},{"i":13,"n":"第十三条","txt":"社会组织在被列入活动异常名录期间，再次出现应当列入活动异常名录情形的，列入时限重新计算。"},{"i":14,"n":"第十四条","txt":"被列入活动异常名录的社会组织按照规定履行相关义务或者完成整改要求的，可以向登记管理机关申请移出活动异常名录，登记管理机关应当自查实之日起5个工作日内将其移出活动异常名录；如不存在应当整改或者履行相关义务情形的，自列入活动异常名录之日起满6个月后，由登记管理机关将其移出活动异常名录。"},{"i":15,"n":"第十五条","txt":"登记管理机关应当将有下列情形之一的社会组织列入严重违法失信名单： （一）被列入活动异常名录满2年的； （二）弄虚作假办理变更登记，被撤销变更登记的； （三）受到限期停止活动行政处罚的； （四）受到5万元以上罚款处罚的； （五）三年内两次以上受到警告或者不满5万元罚款处罚的； （六）被司法机关纳入“失信被执行人”名单的； （七）被登记管理机关作出吊销登记证书、撤销成（设）立登记决定的； （八）法律、行政法规规定应当列入的其他情形。"},{"i":16,"n":"第十六条","txt":"社会组织在被列入严重违法失信名单期间，出现应当列入活动异常名录或者严重违法失信名单情形的，列入时限重新计算。"},{"i":17,"n":"第十七条","txt":"依照本办法第十五条第（一）项被列入严重违法失信名单的社会组织，登记管理机关应当自列入之日起，将其移出活动异常名录；自被列入严重违法失信名单之日起满2年，且按照规定履行相关义务或者完成整改要求的，可以向登记管理机关提出移出申请，登记管理机关应当自查实之日起5个工作日内将其移出严重违法失信名单。 依照本办法第十五条第（二）项至第（六）项规定被列入严重违法失信名单的社会组织，自被列入严重违法失信名单之日起满2年，可以向登记管理机关提出移出申请，登记管理机关应当自查实之日起5个工作日内将其移出严重违法失信名单。 依照本办法第十五条第（七）项规定被列入严重违法失信名单的，登记管理机关应当自该组织完成注销登记之日起5个工作日内将其移出严重违法失信名单。"},{"i":18,"n":"第十八条","txt":"列入严重违法失信名单所依据的行政处罚决定、撤销登记决定或者“失信被执行人”名单被依法撤销或者删除的，社会组织可以向登记管理机关提出移出申请，登记管理机关应当自查实之日起5个工作日内将其移出严重违法失信名单。"},{"i":19,"n":"第十九条","txt":"社会组织的信用信息、活动异常名录和严重违法失信名单应当向社会公开。登记管理机关通过互联网向社会提供查询渠道。"},{"i":20,"n":"第二十条","txt":"社会组织对自身信用信息、活动异常名录和严重违法失信名单有异议的，可以向负责的登记管理机关提出书面申请并提交相关证明材料。登记管理机关应当在30个工作日内进行核实，发现存在错误的，应当自核实之日起5个工作日内予以更正；经核实后作出不予更改决定的，应当书面告知申请人并说明理由。"},{"i":21,"n":"第二十一条","txt":"各级登记管理机关根据国家和本行政区域内信用体系建设的相关规定，通过全国信用信息共享平台向有关部门提供社会组织信用信息，实现部门信息共享。"},{"i":22,"n":"第二十二条","txt":"各级登记管理机关协调配合相关部门，在各自职权范围内，依据社会组织信用信息采取相应的激励和惩戒措施，重点推进对失信社会组织的联合惩戒。"},{"i":23,"n":"第二十三条","txt":"对信用良好的社会组织，登记管理机关可以采取或者建议有关部门依法采取下列激励措施： （一）优先承接政府授权和委托事项； （二）优先获得政府购买社会组织服务项目； （三）优先获得资金资助和政策扶持； （四）优先推荐获得相关表彰和奖励等； （五）实施已签署联合激励备忘录中各项激励措施。"},{"i":24,"n":"第二十四条","txt":"对被列入严重违法失信名单的社会组织，登记管理机关可以采取或者建议有关部门依法采取下列惩戒措施： （一）列入重点监督管理对象； （二）不给予资金资助； （三）不向该社会组织购买服务； （四）不授予相关荣誉称号； （五）作为取消或者降低社会组织评估等级的重要参考； （六）实施已签署联合惩戒备忘录中各项惩戒措施。"},{"i":25,"n":"第二十五条","txt":"登记管理机关工作人员在开展社会组织信用信息管理工作中滥用职权、徇私舞弊、玩忽职守的，视其情节轻重给予批评教育或者行政处分；构成犯罪的，依法追究其刑事责任。"},{"i":26,"n":"第二十六条","txt":"本办法自发布之日起施行。"}],"shehuizuzhimingchengguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强和完善社会组织名称管理，保护社会组织合法权益，根据社会组织登记管理相关法律、行政法规和国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于依法办理登记的社会组织。    本办法所称的社会组织，包括社会团体、基金会和民办非企业单位。"},{"i":3,"n":"第三条","txt":"国务院民政部门主管全国社会组织名称管理工作，县级以上人民政府民政部门（以下称登记管理机关）负责本机关登记的社会组织名称管理工作。"},{"i":4,"n":"第四条","txt":"国务院民政部门建立全国社会组织信用信息公示平台，为社会组织名称信息查询提供支持。"},{"i":5,"n":"第五条","txt":"社会组织只能登记一个名称，社会组织名称受法律保护。"},{"i":6,"n":"第六条","txt":"社会组织名称应当符合法律、行政法规、规章和国家有关规定，准确反映其特征，具有显著识别性。    社会团体的名称应当与其业务范围、会员分布、活动地域相一致。基金会、民办非企业单位的名称应当与其业务范围、公益目的相一致。"},{"i":7,"n":"第七条","txt":"社会组织命名应当遵循含义明确健康、文字规范简洁的原则。    民族自治地方的社会组织名称可以同时使用本民族自治地方通用的民族文字。    社会组织名称需要翻译成外文使用的，应当按照文字翻译的原则翻译使用。"},{"i":8,"n":"第八条","txt":"社会团体名称由行政区划名称、行（事）业领域或者会员组成、组织形式依次构成。异地商会名称由行政区划名称、原籍地行政区划专名和“商会”字样依次构成。    基金会、民办非企业单位名称由行政区划名称、字号、行（事）业领域、组织形式依次构成。    国务院民政部门登记的社会组织名称一般不冠以行政区划名称；按照国家有关规定经过批准的，可以冠以“中国”、“全国”、“中华”等字词。"},{"i":9,"n":"第九条","txt":"社会组织名称中的行政区划名称应当是社会组织住所地的县级以上地方行政区划名称。市辖区名称在社会组织名称中使用时，应当同时冠以其所属的设区的市的行政区划名称。开发区等区域名称在社会组织名称中使用时，应当与行政区划名称连用，不得单独使用。    城乡社区社会组织名称可以在县级行政区划名称后，缀以其住所地的乡镇（街道）或者村（社区）名称。"},{"i":10,"n":"第十条","txt":"基金会和民办非企业单位的字号应当由两个以上汉字组成，不得使用语句和句群，且应当与行（事）业领域显著区分。    县级以上地方行政区划名称（专名或者简称）、行（事）业领域不得作为字号，但具有其他含义且可以明确识别的除外。    基金会不得使用姓氏作为字号。冠以“中国”、“全国”、“中华”等字词以及符合国务院民政部门规定的其他情形的基金会，可以不使用字号。"},{"i":11,"n":"第十一条","txt":"社会组织名称中的行（事）业领域表述应当明确、清晰，与社会组织主要业务范围相一致。    社会组织名称中的行（事）业领域应当根据国民经济行业分类标准、学科分类标准和社会组织的主要业务等标明。社会团体名称中的会员组成应当根据国家职业分类标准、会员共同特点等标明。没有相关规定的，社会组织可以参照国家有关政策进行表述。行（事）业领域不得使用“第一”、“最高”、“国家级”等具有误导性的文字，但具有其他含义的除外。    县级以上地方人民政府的登记管理机关登记的社会组织名称中间含有“中国”、“全国”、“中华”、“国际”、“世界”等字词的，该字词应当是行（事）业领域限定语，并且符合国家有关规定。"},{"i":12,"n":"第十二条","txt":"社会组织名称应当规范标明其组织形式。    社会团体名称应当以“协会”、“商会”、“学会”、“研究会”、“促进会”、“联合会”等字样结束。    基金会名称应当以“基金会”字样结束。    民办非企业单位名称应当以“学校”、“大学”、“学院”、“医院”、“中心”、“院”、“园”、“所”、“馆”、“站”、“社”等字样结束。结束字样中不得含有“总”、“连锁”、“集团”等。"},{"i":13,"n":"第十三条","txt":"社会组织名称不得有下列情形：    （一）损害国家尊严或者利益；    （二）损害社会公共利益或者妨碍社会公共秩序；    （三）含有淫秽、色情、赌博、迷信、恐怖、暴力的内容；    （四）含有民族、种族、宗教、性别歧视的内容；    （五）违背公序良俗或者可能有其他不良影响；    （六）含有外国文字、汉语拼音字母、阿拉伯数字；    （七）可能使公众受骗或者产生误解；    （八）法律、行政法规、规章和国家有关规定禁止的其他情形。"},{"i":14,"n":"第十四条","txt":"社会团体名称中确有必要含有法人、非法人组织名称的，仅限于作为行（事）业领域限定语且符合国家有关规定。    基金会名称不得使用政党名称、国家机关名称、部队番号以及其他基金会名称，使用其他法人或者非法人组织名称的，仅限于作为字号使用，并应当符合下列要求：    （一）不得含有营利法人或者其他营利组织的组织形式；    （二）经该法人或者非法人组织依法授权；    （三）该法人或者非法人组织应当为基金会的捐赠人。      民办非企业单位名称中不得含有法人、非法人组织名称。"},{"i":15,"n":"第十五条","txt":"社会组织一般不得以党和国家领导人、老一辈革命家、政治活动家的姓名命名。    社会团体名称一般不以自然人姓名命名，确有需要的，仅限于在科技、文化、卫生、教育、艺术领域内有重大贡献、在国内国际享有盛誉的杰出人物。    基金会、民办非企业单位名称以自然人姓名作为字号的，需经该自然人同意。使用已故名人的姓名作为字号的，该名人应当是在相关公益领域内有重大贡献、在国内国际享有盛誉的杰出人物。    社会组织名称使用自然人姓名的，该自然人不得具有正在或者曾经受到剥夺政治权利的情形。    法律、行政法规和国家有关规定关于使用自然人姓名另有规定的，从其规定。"},{"i":16,"n":"第十六条","txt":"在同一登记管理机关，申请人拟使用的社会组织名称或者名称中的字号，不得与下列同行（事）业领域且同组织形式的社会组织名称或者名称中的字号相同：    （一）已经登记的社会组织；    （二）已经名称变更登记或者注销登记未满1年的原社会组织；    （三）被撤销成立登记或者被撤销名称变更登记未满3年的社会组织。"},{"i":17,"n":"第十七条","txt":"社会团体、基金会依法设立的分支机构、代表机构名称，应当冠以其所从属社会组织名称的规范全称。社会团体分支机构名称应当以“分会”、“专业委员会”、“工作委员会”、“专家委员会”、“技术委员会”等准确体现其性质和业务领域的字样结束；基金会分支机构名称一般以“专项基金管理委员会”等字样结束。社会团体、基金会代表机构名称应当以“代表处”、“办事处”、“联络处”字样结束。    社会团体、基金会的分支机构、代表机构名称，除冠以其所从属社会组织名称外，不得以法人组织名称命名；在名称中使用“中国”、“全国”、“中华”等字词的，仅限于作为行（事）业领域限定语。"},{"i":18,"n":"第十八条","txt":"社会组织内部设立的办事机构名称，应当以“部”、“处”、“室”等字样结束，除冠以其所从属社会组织名称外，不得以法人组织名称命名，且区别于分支机构、代表机构名称。"},{"i":19,"n":"第十九条","txt":"社会组织名称由申请人自主拟定，并向登记管理机关提交有关申请材料。申请人提交的申请材料应当真实、准确、完整。 实行双重管理的社会组织的名称，应当先经其业务主管单位审查同意。"},{"i":20,"n":"第二十条","txt":"登记管理机关在办理社会组织登记时，认为社会组织名称符合本办法的，按照登记程序办理；发现社会组织名称不符合本办法的，不予登记并说明理由。    登记管理机关审查名称时，可以听取相关管理部门、利益相关方的意见。"},{"i":21,"n":"第二十一条","txt":"社会组织应当在其住所或者主要活动场所标明社会组织名称。社会组织的印章、银行账户、法律文书、门户网站、新媒体平台等使用的社会组织名称，应当与其登记证书上的社会组织名称相一致。    使用社会组织名称应当遵守法律法规，诚实守信，不得损害国家利益、社会利益或者他人合法权益。"},{"i":22,"n":"第二十二条","txt":"登记管理机关依法对本机关登记的社会组织使用名称的行为进行监督，为社会组织提供名称管理政策指导和咨询服务。"},{"i":23,"n":"第二十三条","txt":"登记管理机关应当及时纠正本机关登记的不符合规定的社会组织名称。"},{"i":24,"n":"第二十四条","txt":"社会组织申请登记或者使用名称违反本办法的，依照社会组织登记管理相关法律、行政法规的规定予以处罚。    登记管理机关工作人员在社会组织名称管理工作中利用职务之便弄虚作假、玩忽职守的，依法追究责任。"},{"i":25,"n":"第二十五条","txt":"本办法自2024年5月1日起施行。《基金会名称管理规定》（民政部令第26号）、《民政部关于印发〈民办非企业单位名称管理暂行规定〉的通知》（民发〔1999〕129号）同时废止。"}],"shehuizuzhidengjiguanlijiguanxingzhengchufachengxu4c2072":[{"i":1,"n":"第一条","txt":"为规范社会组织登记管理机关（以下简称登记管理机关）行政处罚程序，保护公民、法人或者其他组织的合法权益，促进社会组织健康发展，根据《中华人民共和国行政处罚法》、《中华人民共和国行政强制法》以及社会组织登记管理等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"登记管理机关实施行政处罚应当遵循公正、公开的原则，坚持处罚与教育相结合，做到事实清楚、证据确凿、适用依据正确、程序合法、处罚适当。"},{"i":3,"n":"第三条","txt":"各级登记管理机关负责管辖在本机关登记的社会组织的行政处罚案件。"},{"i":4,"n":"第四条","txt":"登记管理机关发现不属于本机关管辖的社会组织在本行政区域内有违法行为的，应当及时通报有管辖权的登记管理机关。 有管辖权的登记管理机关可以书面委托违法行为发生地的登记管理机关对社会组织违法案件进行调查。 有管辖权的登记管理机关跨行政区域调查社会组织违法案件的，有关登记管理机关应当积极配合并协助调查。"},{"i":5,"n":"第五条","txt":"登记管理机关发现所调查的案件不属于本机关管辖的，应当将案件移送有管辖权的机关处理。"},{"i":6,"n":"第六条","txt":"登记管理机关应当依法以文字、音像等形式，对行政处罚的启动、调查取证、审核、决定、送达、执行等进行全过程记录，归档保存。"},{"i":7,"n":"第七条","txt":"登记管理机关对同时符合以下条件的违法行为，应当及时立案： （一）有违反社会组织登记管理规定的违法事实； （二）属于登记管理机关行政处罚的范围； （三）属于本机关管辖。 立案应当填写立案审批表，由登记管理机关负责人审批。"},{"i":8,"n":"第八条","txt":"行政处罚应当由具有行政执法资格的执法人员实施，执法人员不得少于两人。 执法人员应当文明执法，尊重和保护当事人合法权益。"},{"i":9,"n":"第九条","txt":"执法人员在调查或者进行检查时，应当主动向当事人或者有关人员出示执法证件。当事人或者有关人员有权要求执法人员出示执法证件。执法人员不出示执法证件的，当事人或者有关人员有权拒绝接受调查或者检查。 当事人或者有关人员应当如实回答询问，并协助调查或者检查，不得拒绝或者阻挠。询问或者检查应当制作笔录。"},{"i":10,"n":"第十条","txt":"执法人员与案件有直接利害关系或者有其他关系可能影响公正执法的，应当回避。 当事人认为执法人员与案件有直接利害关系或者有其他关系可能影响公正执法的，有权申请回避。 当事人提出回避申请的，登记管理机关应当依法审查，由登记管理机关负责人决定。决定作出之前，不停止调查。"},{"i":11,"n":"第十一条","txt":"执法人员调查和收集证据应当遵循全面、客观、公正原则。 证据包括： （一）书证； （二）物证； （三）视听资料； （四）电子数据； （五）证人证言； （六）当事人的陈述； （七）鉴定意见； （八）勘验笔录、现场笔录。 证据必须经查证属实，方可作为认定案件事实的根据。以非法手段取得的证据，不得作为认定案件事实的根据。"},{"i":12,"n":"第十二条","txt":"执法人员应当收集与案件有关的原件、原物作为书证、物证。收集原件、原物确有困难的，可以提取复制品、照片、录像、副本、节录本，由证据提供人核对无误后注明与原件、原物一致，并注明出证日期、证据出处，同时签名或者盖章。"},{"i":13,"n":"第十三条","txt":"执法人员收集视听资料、电子数据，应当收集有关资料、数据的原始载体，收集原始载体有困难的，可以提取复制件，注明制作方法、制作时间、制作人和证明对象等。声音资料应当附有该声音内容的文字记录。"},{"i":14,"n":"第十四条","txt":"执法人员向当事人、证人或者其他有关人员调查了解情况时，应当单独询问，并制作询问笔录。 询问笔录应当交被询问人核对；对阅读有困难的，应当向其宣读。询问笔录如有错误、遗漏，应当允许被询问人更正或者补充，涂改部分应当由被询问人签名、盖章或者以其他方式确认。经核对无误后，由被询问人在询问笔录上逐页签名、盖章或者以其他方式确认。 执法人员应当在询问笔录上签名。"},{"i":15,"n":"第十五条","txt":"执法人员可以要求当事人、证人或者其他有关人员提供证明材料，并要求其在提供的材料上签名或者盖章。"},{"i":16,"n":"第十六条","txt":"对有违法嫌疑的物品或者场所进行检查时，应当通知当事人到场。当事人不到场的，邀请见证人到场。执法人员应当制作现场笔录，载明时间、地点、事件等内容，由执法人员、当事人或者见证人签名或者盖章。当事人拒绝签名、盖章或者不能签名、盖章的，应当注明原因。"},{"i":17,"n":"第十七条","txt":"登记管理机关在收集证据时，在证据可能灭失或者以后难以取得的情况下，经登记管理机关负责人批准，可以采取先行登记保存措施。"},{"i":18,"n":"第十八条","txt":"先行登记保存有关证据，执法人员应当通知当事人到场，送达先行登记保存通知书，当场告知当事人采取先行登记保存措施的理由、依据以及当事人依法享有的权利、救济途径，听取当事人的陈述和申辩，并按照本规定第十六条制作现场笔录。 执法人员应当当场清点证据，加封登记管理机关先行登记保存封条，并开具证据清单，由当事人和执法人员签名或者盖章，交当事人留存一份，归档一份。 登记保存证据期间，当事人或者有关人员不得损坏、销毁或者转移证据。"},{"i":19,"n":"第十九条","txt":"先行登记保存证据后，登记管理机关应当在七个工作日内作出以下处理决定： （一）对依法应予没收的物品，依照法定程序处理； （二）对依法应当由有关部门处理的，移交有关部门； （三）不需要继续登记保存的，解除登记保存，并根据情况及时对解除登记保存的证据采取记录、复制、拍照、录像等措施。"},{"i":20,"n":"第二十条","txt":"执法人员应当围绕证据的真实性、关联性和合法性，针对有无证明效力对证据材料进行核实。"},{"i":21,"n":"第二十一条","txt":"对收集到的证据材料，执法人员应当制作证据目录，并对证据材料的来源、证明对象和内容作简要说明。"},{"i":22,"n":"第二十二条","txt":"案件调查终结，执法人员应当制作案件调查终结报告。 案件调查终结报告的内容包括：社会组织的基本情况、案件来源、调查过程、案件事实、证据材料、法律依据、处理建议等。"},{"i":23,"n":"第二十三条","txt":"登记管理机关在作出行政处罚决定之前，应当制作行政处罚事先告知书，告知当事人拟作出的行政处罚内容及事实、理由、依据，并告知当事人依法享有的陈述、申辩等权利。 当事人可以自收到行政处罚事先告知书之日起五个工作日内提出陈述和申辩。陈述和申辩可以书面或者口头形式提出。当事人口头提出的，执法人员应当制作陈述笔录，交由当事人核对无误后签字或者盖章。"},{"i":24,"n":"第二十四条","txt":"登记管理机关应当充分听取当事人的意见，对当事人提出的事实、理由和证据，应当进行复核；当事人提出的事实、理由或者证据成立的，登记管理机关应当采纳。 登记管理机关不得因当事人陈述、申辩而给予更重的处罚。"},{"i":25,"n":"第二十五条","txt":"登记管理机关作出较大数额罚款、没收较大数额违法所得、没收较大价值非法财物、限期停止活动、撤销登记、吊销登记证书的处罚决定前，应当在行政处罚事先告知书或者听证告知书中告知当事人有要求听证的权利。 当事人要求听证的，应当在登记管理机关告知后五个工作日内提出。登记管理机关应当在举行听证的七个工作日前，通知当事人以及有关人员听证的时间、地点。 听证应当制作笔录。笔录应当交当事人或者其代理人核对无误后签字或者盖章。当事人或者其代理人拒绝签字或者盖章的，由听证主持人在笔录中注明。听证结束后，登记管理机关应当根据听证笔录，依照本规定第二十七条作出决定。"},{"i":26,"n":"第二十六条","txt":"当事人逾期未提出陈述、申辩或者要求听证的，视为放弃上述权利。"},{"i":27,"n":"第二十七条","txt":"登记管理机关负责人应当对案件调查结果进行审查，根据不同情况分别作出如下决定： （一）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）违法行为轻微，依法可以不予行政处罚的，不予行政处罚； （三）违法事实不能成立的，不予行政处罚； （四）违法行为涉嫌犯罪的，移送司法机关。"},{"i":28,"n":"第二十八条","txt":"对下列案件，登记管理机关负责人应当集体讨论决定： （一）拟给予较大数额罚款、没收较大数额违法所得、没收较大价值非法财物的； （二）拟限期停止活动的； （三）拟撤销登记或吊销登记证书的； （四）其他情节复杂或者有重大违法行为的。"},{"i":29,"n":"第二十九条","txt":"有下列情形之一，在登记管理机关负责人作出行政处罚的决定之前，应当由从事行政处罚决定法制审核的人员进行法制审核；未经法制审核或者审核未通过的，不得作出决定： （一）涉及重大公共利益的； （二）直接关系当事人或者第三人重大权益，经过听证程序的； （三）案件情况疑难复杂、涉及多个法律关系的； （四）法律、法规规定应当进行法制审核的其他情形。 登记管理机关中初次从事行政处罚决定法制审核的人员，应当通过国家统一法律职业资格考试取得法律职业资格。"},{"i":30,"n":"第三十条","txt":"登记管理机关决定对社会组织给予行政处罚的，应当制作行政处罚决定书。行政处罚决定书应当载明下列事项： （一）当事人的姓名或者名称、地址； （二）违反法律、法规、规章的事实和证据； （三）行政处罚的种类和依据； （四）行政处罚的履行方式和期限； （五）申请行政复议、提起行政诉讼的途径和期限； （六）作出行政处罚决定的登记管理机关名称和作出决定的日期。 行政处罚决定书应当加盖作出行政处罚决定的登记管理机关的印章。"},{"i":31,"n":"第三十一条","txt":"登记管理机关应当自行政处罚案件立案之日起九十日内作出行政处罚决定。因案情复杂或者其他原因，不能在规定期限内作出处理决定的，经登记管理机关负责人批准，可以延长三十日。案情特别复杂或者有其他特殊情况，经延期仍不能作出处理决定的，应当由登记管理机关负责人集体讨论决定是否继续延期，决定继续延期的，应当同时确定延长的合理期限。 案件处理过程中，听证、公告、审计和检测、鉴定等时间不计入前款所指的案件办理期限。"},{"i":32,"n":"第三十二条","txt":"具有一定社会影响的行政处罚决定应当依法公开。公开的行政处罚决定被依法变更、撤销、确认违法或者确认无效的，登记管理机关应当在三日内撤回行政处罚决定信息并公开说明理由。"},{"i":33,"n":"第三十三条","txt":"登记管理机关及其工作人员对实施行政处罚过程中知悉的国家秘密、商业秘密或者个人隐私，应当依法予以保密。"},{"i":34,"n":"第三十四条","txt":"当事人对登记管理机关的行政处罚决定不服，申请行政复议或者提起行政诉讼的，行政处罚不停止执行，法律另有规定的除外。"},{"i":35,"n":"第三十五条","txt":"登记管理机关对当事人作出罚没款处罚的，应当严格执行罚没款收缴分离制度。登记管理机关及其执法人员不得自行收缴罚没款。当事人应当自收到行政处罚决定书之日起十五日内到指定银行或者通过电子支付系统缴纳罚没款。 当事人确有经济困难，需要延期或者分期缴纳罚没款的，应当提出书面申请。经登记管理机关负责人批准，同意当事人延期或者分期缴纳的，登记管理机关应当书面告知当事人延期或者分期的期限、数额。"},{"i":36,"n":"第三十六条","txt":"依法没收的非法财物，按照国家有关规定处理。"},{"i":37,"n":"第三十七条","txt":"社会组织被限期停止活动的，由登记管理机关封存登记证书（含正本、副本）、印章和财务凭证。停止活动的期间届满，社会组织应当根据登记管理机关要求提交整改报告。"},{"i":38,"n":"第三十八条","txt":"登记管理机关依法责令社会组织撤换直接负责的主管人员的，社会组织应当在登记管理机关规定的期限内执行。"},{"i":39,"n":"第三十九条","txt":"登记管理机关对社会组织作出撤销登记或者吊销登记证书的处罚决定的，应当收缴登记证书（含正本、副本）和印章。"},{"i":40,"n":"第四十条","txt":"当事人逾期不履行行政处罚决定的，登记管理机关可以采取下列措施： （一）到期不缴纳罚款的，每日按罚款数额的百分之三加处罚款，加处罚款的标准应当告知当事人，加处罚款的数额不得超出原罚款数额； （二）依照《中华人民共和国行政强制法》的规定申请人民法院强制执行； （三）法律规定的其他措施。 登记管理机关批准延期、分期缴纳罚款的，申请人民法院强制执行的期限，自暂缓或者分期缴纳罚款期限结束之日起计算。"},{"i":41,"n":"第四十一条","txt":"行政处罚决定书应当在宣告后当场交付当事人。当事人不在场的，应当在七个工作日内依照本规定将行政处罚决定书送达当事人。"},{"i":42,"n":"第四十二条","txt":"执法人员送达法律文书应当有送达回证，由受送达人在送达回证上记明收到日期，签名或者盖章。 受送达人在送达回证上的签收日期为送达日期。"},{"i":43,"n":"第四十三条","txt":"送达法律文书，应当直接送交受送达人。受送达人是自然人的，本人不在时交其同住成年家属签收；受送达人是法人或者其他组织的，应当由法人的法定代表人、其他组织的主要负责人或者该法人、其他组织负责收件的人签收；受送达人有委托代理人的，可以送交其代理人签收；受送达人已向登记管理机关指定代收人的，送交代收人签收。"},{"i":44,"n":"第四十四条","txt":"受送达人拒绝签收法律文书的，送达人可以邀请有关基层组织或者所在单位的代表到场，说明情况，在送达回证上记明拒收事由和日期，由送达人、见证人签名或者盖章，把法律文书留在受送达人的住所；也可以把法律文书留在受送达人的住所，并采用拍照、录像等方式记录送达过程，即视为送达。"},{"i":45,"n":"第四十五条","txt":"直接送达法律文书有困难的，有管辖权的登记管理机关可以委托其他登记管理机关代为送达，或者邮寄送达。邮寄送达的，以回执上注明的收件日期为送达日期。"},{"i":46,"n":"第四十六条","txt":"当事人同意并签订确认书的，可以采用手机短信、传真、电子邮件、即时通讯账号等能够确认其收悉的电子方式向其送达法律文书，登记管理机关应当通过拍照、截屏、录音、录像等方式予以记录，手机短信、传真、电子邮件、即时通讯信息等到达受送达人特定系统的日期为送达日期。"},{"i":47,"n":"第四十七条","txt":"本章规定的其他方式无法送达的，公告送达。可以在报纸或者登记管理机关门户网站等媒体刊登公告，自公告发布之日起，经过六十日，即视为送达，发出公告日期以刊登日期为准。公告送达，应当在案件材料中载明原因和经过。"},{"i":48,"n":"第四十八条","txt":"有下列情形之一的，应予结案： （一）行政处罚案件执行完毕的； （二）作出不予行政处罚决定的； （三）作出移送司法机关决定的。"},{"i":49,"n":"第四十九条","txt":"结案后，登记管理机关应当按照下列要求及时将案件材料整理归档： （一）案卷应当一案一卷，案卷可以分正卷、副卷； （二）各类文书和证据材料齐全完整，不得损毁伪造； （三）案卷材料书写时应当使用钢笔、毛笔或者签字笔。"},{"i":50,"n":"第五十条","txt":"卷内材料应当按照处罚决定书和送达回证在前、其余材料按照办案时间顺序排列的原则排列。 内部审批件可以放入副卷。 卷内材料应当编制目录，并逐页标注页码。"},{"i":51,"n":"第五十一条","txt":"案卷归档后，任何人不得私自增加或者抽取案卷材料。有关单位或者个人申请查阅案卷的，按照社会组织登记档案管理有关规定执行。"},{"i":52,"n":"第五十二条","txt":"本规定有关期间的规定，除注明工作日外，按自然日计算。 期间开始之日不计算在内。期间不包括在途时间，期间届满的最后一日为法定节假日的，以节假日后的第一日为期间届满的日期。"},{"i":53,"n":"第五十三条","txt":"本规定自2021年10月15日起施行。2012年8月3日民政部发布的《社会组织登记管理机关行政处罚程序规定》同时废止。"}],"shehuizuzhipingguguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范社会组织评估工作，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称社会组织是指经各级人民政府民政部门登记注册的社会团体、基金会、民办非企业单位。"},{"i":3,"n":"第三条","txt":"本办法所称社会组织评估，是指各级人民政府民政部门为依法实施社会组织监督管理职责，促进社会组织健康发展，依照规范的方法和程序，由评估机构根据评估标准，对社会组织进行客观、全面的评估，并作出评估等级结论。"},{"i":4,"n":"第四条","txt":"社会组织评估工作应当坚持分级管理、分类评定、客观公正的原则，实行政府指导、社会参与、独立运作的工作机制。"},{"i":5,"n":"第五条","txt":"各级人民政府民政部门按照登记管理权限，负责本级社会组织评估工作的领导，并对下一级人民政府民政部门社会组织评估工作进行指导。"},{"i":6,"n":"第六条","txt":"申请参加评估的社会组织应当符合下列条件之一： （一） 取得社会团体、基金会或者民办非企业单位登记证书满两个年度，未参加过社会组织评估的； （二）获得的评估等级满5年有效期的。"},{"i":7,"n":"第七条","txt":"社会组织有下列情形之一的，评估机构不予评估： （一） 未参加上年度年度检查； （二） 上年度年度检查不合格或者连续2年基本合格； （三） 上年度受到有关政府部门行政处罚或者行政处罚尚未执行完毕； （四） 正在被有关政府部门或者司法机关立案调查； （五） 其他不符合评估条件的。"},{"i":8,"n":"第八条","txt":"对社会组织评估，按照组织类型的不同，实行分类评估。 社会团体、基金会实行综合评估，评估内容包括基础条件、内部治理、工作绩效和社会评价。民办非企业单位实行规范化建设评估，评估内容包括基础条件、内部治理、业务活动和诚信建设、社会评价。"},{"i":9,"n":"第九条","txt":"各级人民政府民政部门设立相应的社会组织评估委员会（以下简称评估委员会）和社会组织评估复核委员会（以下简称复核委员会），并负责对本级评估委员会和复核委员会的组织协调和监督管理。"},{"i":10,"n":"第十条","txt":"评估委员会负责社会组织评估工作，负责制定评估实施方案、组建评估专家组、组织实施评估工作、作出评估等级结论并公示结果。 复核委员会负责社会组织评估的复核和对举报的裁定工作。"},{"i":11,"n":"第十一条","txt":"评估委员会由7至25名委员组成，设主任1名、副主任若干名。复核委员会由5至9名委员组成，设主任1名、副主任1名。 评估委员会和复核委员会委员由有关政府部门、研究机构、社会组织、会计师事务所、律师事务所等单位推荐，民政部门聘任。 评估委员会和复核委员会委员聘任期5年。"},{"i":12,"n":"第十二条","txt":"评估委员会和复核委员会委员应当具备下列条件： （一） 熟悉社会组织管理工作的法律法规和方针政策； （二） 在所从事的领域具有突出业绩和较高声誉； （三） 坚持原则，公正廉洁，忠于职守。"},{"i":13,"n":"第十三条","txt":"评估委员会召开最终评估会议须有2/3以上委员出席。最终评估采取记名投票方式表决，评估结论须经全体委员半数以上通过。"},{"i":14,"n":"第十四条","txt":"评估委员会可以下设办公室或者委托社会机构（以下简称评估办公室），负责评估委员会的日常工作。"},{"i":15,"n":"第十五条","txt":"评估专家组负责对社会组织进行实地考察，并提出初步评估意见。 评估专家组由有关政府部门、研究机构、社会组织、会计师事务所、律师事务所等有关专业人员组成。"},{"i":16,"n":"第十六条","txt":"社会组织评估工作依照下列程序进行： （一） 发布评估通知或者公告； （二） 审核社会组织参加评估资格； （三） 组织实地考察和提出初步评估意见； （四） 审核初步评估意见并确定评估等级； （五） 公示评估结果并向社会组织送达通知书； （六） 受理复核申请和举报； （七） 民政部门确认社会组织评估等级、发布公告，并向获得3A以上评估等级的社会组织颁发证书和牌匾。"},{"i":17,"n":"第十七条","txt":"地方各级人民政府民政部门应当将获得4A以上评估等级的社会组织报上一级民政部门审核备案。省级人民政府民政部门应当在每年12月31日前，将本行政区域社会组织等级评估情况以及获得5A评估等级的社会组织名单上报民政部。"},{"i":18,"n":"第十八条","txt":"评估期间，评估机构和评估专家有权要求参加评估的社会组织提供必要的文件和证明材料。参加评估的社会组织应当予以配合，如实提供有关情况和资料。"},{"i":19,"n":"第十九条","txt":"评估委员会委员、复核委员会委员和评估专家有下列情形之一的，应当回避： （一） 与参加评估的社会组织有利害关系的； （二） 曾在参加评估的社会组织任职，离职不满2年的； （三） 与参加评估的社会组织有其他可能影响评估结果公正关系的。 参加评估的社会组织向评估办公室提出回避申请，评估办公室应当及时作出是否回避的决定。"},{"i":20,"n":"第二十条","txt":"参加评估的社会组织对评估结果有异议的，可以在公示期内向评估办公室提出书面复核申请。"},{"i":21,"n":"第二十一条","txt":"评估办公室对社会组织的复核申请和原始证明材料审核认定后，报复核委员会进行复核。"},{"i":22,"n":"第二十二条","txt":"复核委员会应当充分听取评估专家代表的初步评估情况介绍和申请复核社会组织的陈述，确认复核材料，并以记名投票方式表决，复核结果须经全体委员半数以上通过。"},{"i":23,"n":"第二十三条","txt":"复核委员会的复核决定，应当于作出决定之日起15日内，以书面形式通知申请复核的社会组织。"},{"i":24,"n":"第二十四条","txt":"评估办公室受理举报后，应当认真核实，对情况属实的作出处理意见，报复核委员会裁定。裁定结果应当及时告知举报人，并通知有关社会组织。"},{"i":25,"n":"第二十五条","txt":"评估委员会委员、复核委员会委员和评估专家应当实事求是、客观公正，遵守评估工作纪律。"},{"i":26,"n":"第二十六条","txt":"社会组织评估结果分为5个等级，由高至低依次为5A级（AAAAA）、4A级(AAAA)、3A级(AAA)、2A级(AA)、1A级(A)。"},{"i":27,"n":"第二十七条","txt":"获得评估等级的社会组织在开展对外活动和宣传时，可以将评估等级证书作为信誉证明出示。评估等级牌匾应当悬挂在服务场所或者办公场所的明显位置，自觉接受社会监督。"},{"i":28,"n":"第二十八条","txt":"社会组织评估等级有效期为5年。 获得3A以上评估等级的社会组织，可以优先接受政府职能转移，可以优先获得政府购买服务，可以优先获得政府奖励。 获得3A以上评估等级的基金会、慈善组织等公益性社会团体可以按照规定申请公益性捐赠税前扣除资格。 获得4A以上评估等级的社会组织在年度检查时，可以简化年度检查程序。"},{"i":29,"n":"第二十九条","txt":"评估等级有效期满前2年，社会组织可以申请重新评估。 符合参加评估条件未申请参加评估或者评估等级有效期满后未再申请参加评估的社会组织，视为无评估等级。"},{"i":30,"n":"第三十条","txt":"获得评估等级的社会组织有下列情形之一的，由民政部门作出降低评估等级的处理，情节严重的，作出取消评估等级的处理： （一） 评估中提供虚假情况和资料，或者与评估人员串通作弊，致使评估情况失实的； （二） 涂改、伪造、出租、出借评估等级证书，或者伪造、出租、出借评估等级牌匾的； （三） 连续2年年度检查基本合格的； （四） 上年度年度检查不合格或者上年度未参加年度检查的； （五） 受相关政府部门警告、罚款、没收非法所得、限期停止活动等行政处罚的； （六） 其他违反法律法规规定情形的。"},{"i":31,"n":"第三十一条","txt":"被降低评估等级的社会组织在2年内不得提出评估申请，被取消评估等级的社会组织在3年内不得提出评估申请。"},{"i":32,"n":"第三十二条","txt":"民政部门应当以书面形式将降低或者取消评估等级的决定，通知被处理的社会组织及其业务主管单位和政府相关部门，并向社会公告。"},{"i":33,"n":"第三十三条","txt":"被取消评估等级的社会组织须在收到通知书之日起15日内将原评估等级证书、牌匾退回民政部门；被降低评估等级的社会组织须在收到通知书之日起15日内将评估等级证书、牌匾退回民政部门，换发相应的评估等级证书、牌匾。拒不退回（换）的，由民政部门公告作废。"},{"i":34,"n":"第三十四条","txt":"评估委员会委员、复核委员会委员和评估专家在评估工作中未履行职责或者弄虚作假、徇私舞弊的，取消其委员或者专家资格。"},{"i":35,"n":"第三十五条","txt":"社会组织评估经费从民政部门社会组织管理工作经费中列支。不得向评估对象收取评估费用。"},{"i":36,"n":"第三十六条","txt":"社会组织评估标准和内容、评估等级证书牌匾式样由民政部统一制定。"},{"i":37,"n":"第三十七条","txt":"本办法自2011年3月1日起施行。"}],"xingzhengquhuaguanlitiaolishishibanfa":[{"i":1,"n":"第一条","txt":"根据《行政区划管理条例》（以下简称条例），制定本办法。"},{"i":2,"n":"第二条","txt":"条例所称行政区划的变更，包括行政区划的设立、撤销，行政区划隶属关系的变更，行政区域界线的变更，人民政府驻地的迁移和行政区划名称的变更。 行政区划隶属关系的变更，是指行政区划整建制由其原上级行政区划划归另一个上级行政区划管辖。在不改变行政区划隶属关系的情况下，将行政区划整建制委托另一行政区划代管或者变更代管关系，参照行政区划隶属关系的变更办理。 行政区域界线的变更，是指将一个行政区划的部分行政区域划归另一行政区划管辖。 人民政府（派出机关）驻地的迁移，是指县级以上地方人民政府（派出机关）驻地跨下一级行政区划（派出机关管辖范围）的变更和乡、民族乡、镇人民政府、街道办事处驻地跨村（居）民委员会管辖范围的变更。 行政区划名称的变更，是指改变行政区划专名。"},{"i":3,"n":"第三条","txt":"行政区划的设立、撤销，由拟设立行政区划或者拟撤销行政区划的上一级地方人民政府制订变更方案。在撤销的同时设立新的行政区划且行政区域不变的，可以由拟撤销行政区划的地方人民政府制订变更方案。涉及设立行政区划的，应当在变更方案中明确拟设立行政区划的名称、建制类型、隶属关系（含代管关系）、行政区域界线和人民政府驻地。涉及撤销行政区划的，应当在变更方案中明确行政区划撤销后其所辖行政区域的归属。 变更行政区划隶属关系和变更行政区域界线，由有关地方人民政府先行协商并共同制订变更方案；如未能取得一致意见时，可以由单方、多方或者共同的上一级人民政府制订变更方案。 变更人民政府驻地和变更行政区划名称，由本级地方人民政府制订变更方案。"},{"i":4,"n":"第四条","txt":"市、市辖区设立标准的内容应当包括：人口规模结构、经济社会发展水平、资源环境承载能力、国土空间开发利用状况、基础设施建设状况和基本公共服务能力等。 拟订镇、街道设立标准，应当充分考虑本省、自治区、直辖市经济社会和城镇化发展水平、城镇体系和乡镇布局、人口规模和资源环境等情况。 组织拟订市、市辖区设立标准和镇、街道设立标准的民政部门，应当会同有关部门对标准的实施情况进行评估，并根据评估情况按照规定的权限和程序调整标准。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市人民政府批准县、市、市辖区部分行政区域界线变更或者县、不设区的市、市辖区人民政府驻地迁移时，应当将以下备案材料一式五份径送国务院民政部门： （一）由省、自治区、直辖市人民政府出具的备案报告； （二）行政区划变更批复文件； （三）申请变更行政区划的地方人民政府根据条例第十三条规定提交的行政区划变更申请材料。"},{"i":6,"n":"第六条","txt":"省、自治区、直辖市人民政府批准镇、街道设立标准时，应当将以下材料一式五份径送国务院民政部门： （一）由省、自治区、直辖市人民政府出具的备案报告； （二）省、自治区、直辖市印发标准的文件、标准文本和说明。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市人民政府报送备案的行政区划变更事项和镇、街道设立标准材料不符合本办法第五条、第六条规定的，由国务院民政部门指导补正；材料齐备合规的即为备案。 报送备案的行政区划变更事项和镇、街道设立标准不符合条例规定的，由国务院民政部门建议省、自治区、直辖市人民政府自行纠正；或者由国务院民政部门提出处理建议，报国务院决定。"},{"i":8,"n":"第八条","txt":"申请变更行政区划向上级人民政府提交的申请书内容应当包括： （一）行政区划变更理由； （二）行政区划变更方案； （三）与行政区划变更有关的经济发展、资源环境、人文历史、地形地貌、人口、行政区域面积和隶属关系的简要情况； （四）风险评估、专家论证、征求社会公众等意见的综合研判情况。"},{"i":9,"n":"第九条","txt":"条例第十三条第（三）项规定的风险评估报告一般应当包括以下内容： （一）行政区划变更的合法性、可行性、风险性和可控性； （二）行政区划变更对当地及一定区域范围内的人口资源、经济发展、行政管理、国防安全、民族团结、文化传承、生活就业、社会保障、基层治理、公共安全、资源环境保护、实施国土空间规划、机构调整和干部职工安置等方面可能造成的影响，以及可能引发的问题； （三）行政区划变更的主要风险源、风险点的排查情况及结果； （四）拟采取的消除风险和应对风险的举措； （五）风险评估结论； （六）其他与风险评估相关的内容。"},{"i":10,"n":"第十条","txt":"开展风险评估，可以通过舆情跟踪、重点走访、会商分析等方式，运用定性分析和定量分析等方法，对行政区划变更实施的风险进行科学预测、综合研判。 开展风险评估，可以委托专业机构、社会组织等第三方机构进行。"},{"i":11,"n":"第十一条","txt":"条例第十三条第（四）项规定的专家论证报告一般应当包括以下内容： （一）行政区划变更的必要性、科学性、合理性； （二）行政区划变更的经济社会效益； （三）行政区划变更的可行性及可能存在的风险； （四）对行政区划变更方案及组织实施的意见建议； （五）其他与专家论证相关的内容。"},{"i":12,"n":"第十二条","txt":"组织专家论证，可以采取论证会、书面咨询、委托咨询论证等方式。选择专家、专业机构参与论证，应当坚持专业性、代表性和中立性，注重选择不同专业背景的专家、专业机构，不得选择与行政区划变更事项有直接利益关系的专家、专业机构参与专家论证。 县级以上地方人民政府民政部门应当根据需要建立行政区划咨询论证专家库。"},{"i":13,"n":"第十三条","txt":"条例第十三条第（五）项规定的征求社会公众等意见报告的内容一般应当包括： （一）征求社会公众等意见的过程和范围； （二）社会公众等的主要意见和建议； （三）对意见建议的处理情况； （四）其他与征求社会公众等意见相关的内容。"},{"i":14,"n":"第十四条","txt":"征求社会公众等意见可以采取座谈会、实地走访、书面征求意见、问卷调查等方式。 申请变更行政区划的地方人民政府应当对社会各方面提出的意见进行归纳整理、研究论证，充分采纳合理意见，完善行政区划变更方案及配套措施。"},{"i":15,"n":"第十五条","txt":"提交条例第十三条第（六）项规定的变更前的行政区划图和变更方案示意图，应当符合下列要求： （一）图件应为A3图幅彩色示意图； （二）图件能够全面、真实、准确反映行政区划变更涉及的各主要因素，底图中应包括行政区划名称、人民政府驻地、行政区域界线、水系、公路、铁路等要素； （三）行政区划轮廓线用加粗的红线表示，下级行政区划用对比明显的色块区别表示，下级行政区划间的界线用加粗的红色虚线表示，各级人民政府驻地根据级别高低采用不同大小的红色实五角星表示。"},{"i":16,"n":"第十六条","txt":"申请变更行政区划应当拟订组织实施总体方案，与申请书一并上报审核。 组织实施总体方案一般应当包括行政区划变更的组织领导体系及责任分工，行政区划变更的实施步骤，行政区划变更的保障措施等内容。行政区划设立、撤销和变更隶属关系的，总体方案一般还应当包括行政区划变更后发展定位、目标、方向，相关地方党政群机构设置调整，国有资产、债权债务划转，历史文化传承保护，民生保障和公共服务等方面的内容。 上级人民政府民政部门应当加强对行政区划变更事项组织实施的监督指导。"},{"i":17,"n":"第十七条","txt":"县级以上地方人民政府民政部门在审核下级人民政府上报的行政区划变更方案时，应当根据情况自行组织或者委托第三方机构开展实地调查。 开展实地调查，可以采取听取汇报、召开座谈会、查阅资料、个别访谈、随机访或者暗访等形式进行。"},{"i":18,"n":"第十八条","txt":"地方人民政府应当在收到上级人民政府行政区划变更批复文件后及时向社会公告审批机关批准行政区划变更的信息。法律、行政法规和国家有关规定另有规定的除外。"},{"i":19,"n":"第十九条","txt":"行政区划变更引起行政区域界线变化的，毗邻各方人民政府应当按照审批机关批准的行政区划变更方案，依照法律、行政法规和国家有关规定，在行政区划变更完成时限内完成行政区域界线的勘定工作。"},{"i":20,"n":"第二十条","txt":"条例第十五条规定的完成变更情况报告一般应当包括以下内容： （一）行政区划变更批复内容落实情况； （二）人民群众反应和舆论反响情况； （三）行政区划变更的影响和初步效果； （四）风险控制和处置情况； （五）行政区划变更后需要勘定行政区域界线的，还应当报告完成界线勘定情况； （六）其他应当报告的情况。"},{"i":21,"n":"第二十一条","txt":"行政区划变更完成情况报告上报审批机关后3个月内，有关地方人民政府民政部门应当将更新后的行政区划图标准样图报批准行政区划变更的人民政府民政部门审核。由组织更新行政区划图的地方人民政府民政部门按照地图管理有关规定送审后向社会公布。"},{"i":22,"n":"第二十二条","txt":"国务院民政部门组织制定各级行政区划代码编码规则。 行政区划变更信息向社会公告之日起1个月内，国务院民政部门或者省、自治区、直辖市人民政府民政部门应当根据行政区划代码编码规则，确定、公布变更后的行政区划代码。"},{"i":23,"n":"第二十三条","txt":"省、自治区、直辖市人民政府应当在每年1月31日前，将本级及下一级人民政府1年内批准的行政区划变更事项（含派出机关变更事项）相关信息集中报送国务院民政部门。 上报的行政区划变更信息应当包括行政区划变更事项列表及相关行政区划变更批复文件。"},{"i":24,"n":"第二十四条","txt":"上级人民政府民政部门发现下级人民政府存在违反条例规定情形的，应当建议其及时纠正，或者提出建议报本级人民政府依法处理。"},{"i":25,"n":"第二十五条","txt":"旗、特区、林区的行政区划管理参照县执行，自治旗的行政区划管理参照自治县执行，盟的行政区划管理参照地区执行。"},{"i":26,"n":"第二十六条","txt":"本办法自2020年1月1日起施行。"}],"xingzhengquyujiexianjiezhuangguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强行政区域界线界桩的管理和保护，根据《行政区域界线管理条例》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"行政区域界线界桩，是由行政区域毗邻各方人民政府共同埋设的，用于指示行政区域界线实地位置的标志物。"},{"i":3,"n":"第三条","txt":"县级以上各级人民政府民政部门根据职责分工分级负责各级行政区域界线界桩的管理工作。 行政区域毗邻的县级人民政府民政部门具体承担各级行政区域界线界桩（以下简称“界桩”）的管理和保护工作。"},{"i":4,"n":"第四条","txt":"行政区域界线协议书或者有关各方人民政府达成的其他协议中未明确界桩管理责任方的，有关各方人民政府民政部门应当签订协议予以明确，经有关各方人民政府批准后实施，并报该行政区域界线批准机关的民政部门备案。"},{"i":5,"n":"第五条","txt":"界桩管理的依据： （一）毗邻双方人民政府签订的行政区域界线勘界协议书及其附图、界桩成果表； （二）毗邻双方人民政府民政部门签订的行政区域界线、界桩管理协议或者签发的行政区域界线、界桩管理文件； （三）毗邻各方人民政府或者民政部门签订的行政区域界线交会点协议书及其附件； （四）行政区域界线联合检查工作报告； （五）有关界桩变动的协议书或者文件； （六）界桩登记表。"},{"i":6,"n":"第六条","txt":"县级以上各级人民政府民政部门在界桩管理工作中，应当明确职责分工，按照规定程序移动或者增设界桩、及时修复或者恢复损坏的界桩、查处损坏界桩的行为，确保界桩位置准确、埋设牢固、明显易见、注记清晰、档案完备。"},{"i":7,"n":"第七条","txt":"界桩埋设后，任何组织和个人不得擅自移动或者损坏。 因建设、开发项目确需移动界桩的，建设、开发单位应当提出申请，由行政区域界线毗邻的任何一方人民政府民政部门报经各有关人民政府协商一致。 界桩移动、埋设和测绘的费用由建设、开发单位承担。"},{"i":8,"n":"第八条","txt":"需要增设界桩时，毗邻双方人民政府民政部门应当协商一致，确定增设界桩的数量和埋设位置，明确界桩管理责任方，共同提出方案报该行政区域界线批准机关的民政部门批准后实施。"},{"i":9,"n":"第九条","txt":"对主体完整、边角轻微损坏的界桩应当修复；对基座松动但主体完整的界桩应当在原地加固扶正。"},{"i":10,"n":"第十条","txt":"对丢失或者严重损坏、修复困难的界桩，应当重新制作，并根据下列情形在原地恢复埋设或者移位埋设: （一）双立、多立界桩和位于行政区域界线上的单立界桩，按照界桩成果表和登记表的记载在原地予以恢复；无法在原地恢复的，由双方就近选定适当位置移位埋设。 （二）不在行政区域界线上的单立界桩，由双方就近在行政区域界线上选定适当位置埋设或者改设为双立界桩埋设。 （三）行政区域界线交会点单立界桩无法在原地恢复的，可以改设为双立或者多立界桩埋设。 （四）重新制作、埋设的界桩，其标注年份为重新埋设时的年份。"},{"i":11,"n":"第十一条","txt":"移动、增设、修复或者恢复界桩，应当在毗邻行政区域各方人民政府民政部门人员在场的情况下，由负责管理该界桩的一方组织实施。"},{"i":12,"n":"第十二条","txt":"移动、增设或者恢复界桩，应当按照勘界测绘技术规定的有关要求，制作、埋设界桩，测定界桩坐标，填写界桩成果表和登记表，拍摄界桩照片。"},{"i":13,"n":"第十三条","txt":"负责界桩管理工作的地方各级人民政府民政部门应当建立本级界桩日常管理档案，每年向毗邻行政区域人民政府民政部门通报界桩管理情况。 移动、增设或者恢复界桩后，由负责管理的一方将有关界桩变动的文件、资料整理归档，并送毗邻各方保存一套，同时报该行政区域界线批准机关及其民政部门备案。"},{"i":14,"n":"第十四条","txt":"负责管理界桩的县级人民政府民政部门可以聘请当地居民为界桩维护员。"},{"i":15,"n":"第十五条","txt":"界桩维护员应当适时检查所维护的界桩，清除界桩周围杂草、淤泥和遮挡物，刷新界桩注记，保持界桩整洁，明显易见，做好检查记录，制止损坏界桩的行为。 界桩维护员发现界桩松动、移动、丢失、损坏时，应当及时报告负责管理该界桩的县级人民政府民政部门。"},{"i":16,"n":"第十六条","txt":"界桩管理经费由界桩管理责任方按照国家有关规定从同级行政区域界线管理经费中列支。"},{"i":17,"n":"第十七条","txt":"故意损毁或者擅自移动、增设、修复、恢复界桩以及指使他人故意损毁或者擅自移动、增设、修复、恢复界桩的，按照《行政区域界线管理条例》第十六条、第十七条的规定处罚。 因过失造成界桩损坏的，过失人应当及时报告界桩所在地任何一方县级人民政府民政部门。"},{"i":18,"n":"第十八条","txt":"乡、民族乡、镇的行政区域界线界桩的管理和维护参照本办法执行。"},{"i":19,"n":"第十九条","txt":"行政区域界线依法变更后，原行政区域界线上的界桩即行废止，由有关各方人民政府民政部门共同组织销毁。在变更后的行政区域界线上设立新界桩，应当按照勘界的有关规定进行。"},{"i":20,"n":"第二十条","txt":"本办法自2008年9月1日起施行。"}]};
